// ══════════════════════════════════════════════════════════════════════════
// IZ — 빙의 **새 시안 열**                                     (2026-08-28)
//
//   깨뜨리기 `shatter` · 빙판 `rinkfield` · 우박 `hail` · 엉김 `iceclump` ·
//   **파문 `pulse`**(3차 재설계) · **빙벽 `icewall`**(6차 재설계 · 셋을 한 몸통으로)
//   ⭐ **10차 채택 셋** — 서리탄 `frostshot` · 빙추 `icespire` · 얼음 채찍 `icewhip`
//   ⭐ **10차 4차 마지막 빈 칸** — 서리밭 `frostmire`
//   ⚠️ 머리말이 「여섯」에 멈춰 있었다 — 넷이 뒤에 들어오는 동안 이 줄을 아무도
//     안 고쳤다. **정의를 더할 때 머리말도 같은 편집에서** 고친다.
//
// ── ⚠️ 폐기된 둘은 여기 없다 ──────────────────────────────────────────────
//   **얼음 무지 `cairn`**(6차) · **상고대 `rime`**(8차) — 둘 다 사용자 판정이고
//   정의 · 지도 · 마운트 · 성장표 · 칸 수를 **한 패스에** 걷었다. 폐기 사유는
//   각각 아래 「걷어낸 둘」 절에 남긴다(⚠️ **개명으로 폐기하지 않았다**).
//
// ── 무엇을 그리는 파일인가 ────────────────────────────────────────────────
// 빙의 칸은 열둘인데 여덟이 서 있었고, 그중 **빙벽 두 종**(바늘 숲 `iceneedle` ·
// 모자이크 석벽 `icebrick`)이 「빙벽과 **같은 메커니즘**」이라 걷혔다(사용자
// 판정). 남은 여섯에 **다섯**이 허가됐고 한 칸이 비어 **엉김**을 새로 냈다.
// ⇒ 이 파일이 그 여섯의 그림이었고, 10차에 **채택 셋**(서리탄 · 빙추 · 얼음
//   채찍)과 **마지막 빈 칸**(서리밭)이 들어와 **열**이 됐다. 결빙(`POportal`)은
//   이미 `vfx.js` 에 그려져 있어 여기서는 **읽기만** 하고 문구 한 벌만 든다
//   (아래 [IZSK]). ⇒ 열두 칸 중 **열을 이 파일이 그린다**(나머지 둘 = 결빙 ·
//   서릿발은 `FX` 의 기존 함수를 부른다).
//
