// 🔴🔴 **정정 둘 — 앞서 이 파일에 걸려 있던 규약이 틀렸다**  (2026-08-28 10차)
//
// ── 정정 ① 「가산 합성 금지」는 **배경 규칙**이지 이펙트 규칙이 아니다 ─────
// 레포 원문이 근거를 같이 적고 있다:
//   `vfx.js:19451` 「배경 한 장. **가산 합성을 한 번도 안 쓴다** —
//                   **이펙트가 전부 가산이라** …」
// ⇒ 「이펙트가 전부 가산이라」가 **배경이 안 쓰는 까닭**이다. 관계가 뒤집혀
//   전달돼, 빙이 **함수 여든아홉 개에 가산 직접 호출 0회**가 됐다.
//   ⚠️ 정확히 말하면 0 이 아니었다 — [IBline]·[IBspark]·[IBroot]·[IBrim] 이
//     안에서 `gAdd` 를 쓰므로 **획은 가산**이었다. 가산이 아니었던 것은
//     **면**(`fillPoly` 직접 호출)이고, 하필 그것이 **결정의 몸**이다.
// ⇒ 그래서 결정 둘이 겹쳐도 **안 밝아졌고**, 얼음이 「색종이」가 됐다.
//   사용자가 빙에 낸 지적 넷이 전부 이 한 자리로 모인다:
//     「파문이 **너무 연하고**」 · 「빙판 투사체가 **그냥 스티커**」 ·
//     「얼음무지가 **조악하다**」(폐기됨) · (염에서) 「**색종이 덕지덕지**」
//   ⭐ 독 갈래만 이 지적을 안 받았고, 그 갈래만 가산을 34회 썼다 — 우연이 아니다.
// ⇒ **이펙트는 가산으로 그린다.** 얼음은 **빛을 통과시키고 굴절시키는 물건**이라
//   겹치는 데가 밝아져야 「속이 비친다」가 된다.
//   ⚠️ 다만 **비싼 잉크의 규율은 그대로**다 — 넓은 가산 겹은 **코어 한 곳에만**,
//     나머지 밝음은 **작고 여럿**으로. 병목은 여전히 칠하는 픽셀 면적이다.
//   ⚠️ 가산 겹의 알파는 **낮게** 잡는다. 가산은 겹칠수록 저절로 차오르므로
//     한 장이 진하면 둘만 겹쳐도 흰색으로 포화돼 **면 쪼개기가 지워진다.**
//
// ── 정정 ② 「면이 본체, 획은 그 위의 결」은 **빙의 규칙이 아니다** ─────────
// 그것은 **꿰미 · 밧줄**에 대한 처방이었다(그 둘이 채우기 0 에 획만 일곱이라
// 문자 그대로 **선**이었다). 빙은 반대 병이었다 — **면만 있고 빛이 없었다.**
// ⇒ 빙에서 지킬 것은 「면이 본체」가 아니라 **「면 + 그 위에 가산으로 얹는 빛」**이다.
//
// ── 어디에 가산을 얹었나(10차) ───────────────────────────────────────────
//   [IZprism3] **속심 면** 한 겹 + **이방성 하이라이트** + **서리 알갱이**
//   [IZvTop] 윗면 · 바늘 숲 **뿌리 무지**의 윗면 · [IZspirit] C안 **육각 등**의 앞 기둥
//   ⚠️ 세 면에 다 얹지 않았다 — 결정이 흰 덩어리가 되고 값이 세 배가 된다.
// ══════════════════════════════════════════════════════════════════════════
//
// ── ⚠️ 정식 시안이 갖춰야 하는 넷 ────────────────────────────────────────
// 이 레포의 이식 실패 62%가 「숫자는 맞는데 **항이 빠짐**」이다. 그래서 여섯이
// **전부 네 항을 다 갖는다** — 빠뜨린 칸이 하나도 없다는 것이 이 파일의 계약이다.
//
//   ① **덩어리** — 눈에 들어오는 넓이를 가진 몸. 이것이 없으면 선 그림이 된다
//   ② **층**     — 어두움 · 바탕 · 밝은 앞날. `IBcrys`/`IBpane` 이 한 벌로 준다
//   ③ **불티**   — 튀는 조각. 정체를 만드는 것은 큰 것이 아니라 이 작은 것들이다
//   ④ **잔상**   — 지나간 자리에 남는 것. 「무엇이 방금 여기서 일어났나」를 말한다
//
// ── ⚠️ 박자는 초로 못 박는다 ─────────────────────────────────────────────
// 솟는 시간 · 스러지는 시간 · 수명 · 주기를 전부 상수로 이름 지어 둔다. 흥정할
// 값이 아니라 **이식 때 그대로 옮길 값**이다. 피해 · 판정 주기 · 판정 반경은
// **여기 없다** — 그건 엔진의 몫이고 시안이 지어내면 거짓이 된다.
//
// ── ⚠️ 다섯 칸은 **크기만 다른 그림이면 안 된다** ────────────────────────
// 2026-08-28 에 빙벽 셋이 「L1 이 L5 와 모양이 같고 크기만 작은」 상태로
// 발견됐다. 그래서 여섯 전부 **칸마다 사건이 하나씩** 붙는다(레벨 문구의 굵은
// 글씨가 그 사건이다). 크기는 사건에 딸려 오는 것이지 축이 아니다.
//
// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐ **빙의 축 — 얼린다 → 깬다 → 잇는다**                     (2026-08-28)
//
// 사용자가 **빙판**과 **우박**에 **똑같은 한 줄**을 붙였다: 「지나가거나 부딪힌
// 적 **빙결 효과**(깨트리기와 **연쇄 작용**)」. 같은 말이 두 칸에 붙었다는 것은
// 낱개 치장이 아니라 **한 몸의 구조**라는 뜻이다.
//
//     빙판 · 우박  →  적을 **얼린다**(빙결 표식이 적 몸에 앉는다)
//                          ↓
//     깨뜨리기      →  **언 것을 골라** 쳐서 터뜨린다 (+ 폭발 + 스플래시)
//                          ↓
//     엉김          →  **언 것들을 이어** 한 번에 더 크게 터뜨릴 밥을 만든다
//
// ⇒ 다섯을 따로 그리지 않는다. 「얼었다」를 말하는 **표식 한 벌**을 먼저 못
//   박고([IZseal]), 빙판·우박이 그것을 **붙이고**([IZchill]), 깨뜨리기가
//   **터뜨리고**([IZboom]), 엉김이 **잇는다**. 그 표식이 다섯 칸을 꿰는 실이다.
//
// ── 표식 한 벌이 무엇인가 ────────────────────────────────────────────────
//   ㉠ **차오름** — `f.pv` 가 0 → 1.5 로 찬다. 이 구간은 `pvMark("frost")`,
//      곧 **몸에 붙어 자라는 성에**다(아직 안 언 것이다)
//   ㉡ **빙결**   — 1.5 를 넘는 순간 `f.frz=1`. `pvMark("freeze")` 로 바뀌어
//      몸이 얼음 **기둥 속에 잠긴다**. 그리고 요동이 멎는다([IZstand] 의 `hold`)
//   ㉢ **도장**   — 언 몸 위에 **육각 결정 하나**가 앉는다([IZseal]). 이것이
//      다섯 칸에서 **글자 하나까지 같은** 유일한 획이고, 「이 놈이 깨뜨리기의
//      밥이다」를 말한다. ⚠️ **한 점도 안 움직인다** — 멈춤이 이 상태의 전부라
//      `pvMark` 의 freeze 가지가 `t` 를 안 쓰는 것과 같은 규율이다.
//
// ⚠️ 앞 갈래가 이 실을 반쯤 갖고 있었다 — 「엉김은 **깨뜨리기의 밥**」이라
//   적었고, 깨뜨리기의 연쇄 문턱 [IZS_NEAR] 이 무대에서 **한 번도 안 터지던**
//   결함도 잡았다. 이번에 그것을 **다섯 칸의 설계 축으로 올린다.**
// ══════════════════════════════════════════════════════════════════════════
/// 얼기까지 차야 하는 몫 · 최대치. 1.5 는 `pvMark` 가 `f.pv*1.6` 로 알파를
/// 만들므로 그 앞에서 표식이 **이미 꽉 진해진 뒤**에 얼음으로 넘어가는 값이다.
const IZF_ON = 1.5, IZF_MAX = 2.4;

// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐⭐ **다섯 마디 — 시전 · 생성 · 발현 · 소멸 · 종료**       (2026-08-28)
//
// 사용자 지시(전 갈래 공통):
//   > 「스킬시전 → 스킬생성(공격 넣기 전) → 스킬발현(공격) → 스킬소멸(공격 후)
//   >  → 스킬종료. 지금 우리 스킬은 대부분 **'즉발'**이거나 스킬이 발동되기
//   >  전까지의 시간들이 짧고 소멸되는 시간도 짧아서 **화려함이나 액션감이
//   >  부족**한 듯해」
//   > 「렉 때문이면 **스킬 발동 주기를 낮추고 스킬 한 번을 발동하더라도
//   >  멋있게** 날아가도록 변경」
//
// ⚠️ 실측이 이를 뒷받침한다 — `lib/game/fx/w_*.dart` **85개 중 예고 항을 가진
//   것이 16개(19%)**. 다섯 중 넷이 예고 없이 곧장 터진다.
//
// ── 다섯 마디의 계약 ─────────────────────────────────────────────────────
//   ㉠ **시전** — 「곧 온다」. 몸에서 냉기가 모이거나 표적 위에 문장이 뜬다.
//                 ⚠️ **0 이면 안 된다.** 여기가 없으면 스킬이 즉발이 된다
//   ㉡ **생성** — 공격이 닿기 **전**. 투사체가 날거나 판이 펼쳐지거나 다리가 자란다
//   ㉢ **발현** — 공격. 이 마디만 적을 건드린다
//   ㉣ **소멸** — 때린 **뒤**. 잔해 · 김 · 부서짐. ⚠️ **0 이면 액션감이 안 남는다**
//   ㉤ **종료** — 마지막 자국이 스러지고 화면이 비어 다음 주기와 이어진다
//
// ⚠️ 다섯이 **각각 다른 그림**이라야 한다. 같은 도형의 알파만 오르내리면 그것은
//   마디가 하나다 — 아래 다섯 칸 전부 마디마다 **다른 획**을 쓴다.
// ⚠️ 화려함의 값은 **주기를 늘려서** 사 온다(사용자가 명시로 허가했다).
//   병목은 칠하는 픽셀이지 사건의 수가 아니다(raster p95 18.24 vs build 0.49).
//   ⇒ 주기가 늘면 **한 프레임의 몫은 그대로인데 한 번이 커진다.**
// ⚠️ 밸런스 수(피해 · DPS)는 여기 없다 — 박자만 짠다. 주기가 늘면 한 방이
//   커지는 것은 **엔진이 나중에 맞춘다.**
//
// ══ 🔴🔴 **[IZ시전표] 「다섯 마디 전부 > 0」의 예외** ═══════ (2026-08-29)
// 사용자 원문(서릿발):
//   > 「**서릿발 스킬 쏘기 전에 뭐가 방정맞게 줜나 나왔다가 왜 투사체 발사하냐?
//   >  바로 투사체만 발사하면 되지.**」
// ⭐⭐ **주기가 짧고 쉬지 않고 나가는 칸에는 시전 그림을 두지 않는다.**
//   ㉠ **기본공격의 시전은 곧 발사다** — 총알을 쏘기 전에 매번 뜸 들이는 총은
//      없다. 주기 1.6초짜리에 예비 동작을 붙이면 **매 발마다 「준비」가 끼어**
//      「방정맞다」가 된다.
//   ㉡ 헌장의 뜻은 「**그림이 다섯 번 바뀐다**」이지 「**매 주기 예비 동작을
//      그린다**」가 아니다. 계속 나가는 칸은 **넷으로 접는다**(발사 → 발현 →
//      소멸 → 종료). 마디가 넷이어도 **넷이 다 다른 그림**이면 계약을 지킨다.
//
//   ┌─────────────────────────────┬──────────────────────────────────────┐
//   │ 계속 나가는 것              │ **시전 그림 없음.** 시전이 곧 발사   │
//   │ (기본공격 급 · 짧은 주기)   │ ⇒ 서릿발 · 서리탄 · 얼음 채찍        │
//   ├─────────────────────────────┼──────────────────────────────────────┤
//   │ 한 방짜리 · 느리고 큰 것    │ **시전 그림 있음.** 예비 동작이      │
//   │                             │ 무게를 만든다                         │
//   │                             │ ⇒ 우박 · 결빙 · 얼음창 · 서리밭      │
//   └─────────────────────────────┴──────────────────────────────────────┘
//   🔴 **둘을 섞지 마라.** 얼음창의 「머리 위 구 → 아공간」은 사용자가 직접
//     지시한 예비 동작이다 — 저쪽에서 시전을 걷으면 그 지시를 어긴다.
// ⚠️ **같은 사고가 오늘 세 번째다** — 화염방사(시계 둘) · 서릿발 예고선(두 번) ·
//   그리고 이 시전 그림. 마디를 「0 으로 못 둔다」로 읽고 **없어도 되는 자리에
//   잉크를 채운** 것이 셋의 공통 원인이다.
// ══════════════════════════════════════════════════════════════════════════
/// 다섯 마디 시각표. `B` = [시전, 생성, 발현, 소멸, 종료](초, 합 = 주기).
/// 마디마다 0→1 진행값과 「지금 이 마디인가」를 같이 돌려준다.
/// ⚠️ **`B[0] = 0` 을 받는다** — 기본공격 급 칸은 시전 마디를 안 갖는다
///   (아래 [IZ시전표] 참조). 그때 `t0 = 0` 이라 `tau / t0` 이 **NaN·Infinity**
///   가 되므로 `cast` 를 1(=이미 다 지났다)로 접는다. `inCast` 는 `tau < 0`
///   이라 저절로 거짓이고, 시전 그림을 안 그리는 칸은 `cast` 를 안 읽는다.
function IZbeat(tau, B) {
  const t0 = B[0], t1 = t0 + B[1], t2 = t1 + B[2], t3 = t2 + B[3], t4 = t3 + B[4];
  return { t0, t1, t2, t3, t4,
    cast: t0 > 0 ? IZcl(tau / t0) : 1, grow: IZseg(tau, t0, t1), hit: IZseg(tau, t1, t2),
    fade: IZseg(tau, t2, t3), rest: IZseg(tau, t3, t4),
    inCast: tau < t0, inGrow: tau >= t0 && tau < t1, inHit: tau >= t1 && tau < t2,
    inFade: tau >= t2 && tau < t3, inRest: tau >= t3 };
}

/// ⭐ **시전 그림의 정본** — 몸 둘레로 냉기가 **모여든다**.
/// ⚠️ 다섯 칸이 이 한 함수를 쓴다. 칸마다 따로 그리면 「시전」이 다섯 종류가 되어
///   화면에서 「무엇이 시작됐다」로 안 읽힌다.
/// ⚠️ 모이는 것이라 **밖에서 안으로** 온다 — 퍼지는 그림과 정반대여야 한다.
function IZcastFx(c, cx, cy, v, SC, a, seed, noSigil) {
  if (v <= 0 || v >= 1 || a <= .01) return;
  const R = 34 * SC;
  // ⓿ ⭐⭐ **바닥 마법진**(2026-08-28 4차). 사용자 레퍼런스 ㉡ 이 요구하는
  //   여섯 항을 [IZsigil] 이 한 벌로 준다 — 동심 고리 다섯 · 파선 고리 ·
  //   눈금 룬 띠 · 정다각별 셋 겹침 · 위성 원 넷 · 중심 코어.
  //   ⚠️ **여기 한 줄이 일곱 칸을 다 바꾼다** — 시전이 「빛이 좀 모인다」에서
  //     「마법진이 그려진다」가 된다. 칸마다 따로 그리면 그날로 일곱 종류가 된다.
  //   ⚠️ 파문은 **제 마법진을 더 크게** 그리므로 `noSigil` 로 끈다(두 겹이 되면
  //     고리가 열 개가 되어 오히려 뭉갠다).
  //   ⚠️ 전부 **싼 잉크**(가는 선)다 — 칠하는 면적이 거의 안 는다.
  if (!noSigil) IZsigil(c, cx, cy, 30 * SC, seed * .3, IZss(v), SC, .82 * a, seed);
  // ① 모여드는 조각 여섯 — 밖에서 몸으로 빨려 온다
  for (let j = 0; j < 6; j++) {
    const a0 = (j + .5) / 6 * TAU + seed;
    const d = R * (1.5 - 1.15 * IZss(v)) * (.8 + .4 * hash(seed + j * 3.1));
    IBshard(c, cx + Math.cos(a0) * d, cy + Math.sin(a0) * d * .72,
      (2.6 + 1.4 * hash(seed + j * 5.7)) * SC * v, a0 + 1.2, "frost", .85 * a, .5);
    IBline(c, [[cx + Math.cos(a0) * d * 1.32, cy + Math.sin(a0) * d * 1.32 * .72],
               [cx + Math.cos(a0) * d, cy + Math.sin(a0) * d * .72]],
      1.1 * SC, "frost", .34 * v * a, 1);
  }
  // ② 오므라드는 겨눔 테 — 발동 시각에 정확히 다 닫힌다
  IBrim(c, jagPoly(cx, cy, R * (1.35 - .95 * v), 9, seed + 2.3, 1.05, .72),
    "frost", (.30 + .40 * v) * a, 1.4 * SC);
  // ③ 심에 차오르는 빛 — 「충전」
  IBroot(c, cx, cy, 13 * SC * (.3 + .9 * v), "frost", .55 * v * a, .82);
}

/// ⭐ **종료 그림의 정본** — 마지막 자국이 스러진다(김 + 서리 고리).
/// ⚠️ 「소멸」과 다른 그림이라야 한다. 소멸은 **부서지는 것**이고 종료는
///   **남은 것이 없어지는 것**이다 — 그래서 조각이 없고 김과 고리만 있다.
function IZrestFx(c, cx, cy, v, R, SC, a, seed) {
  // 🔴🔴 **`v <= 0` 이 아니라 `v < 0` 이다** — [IZchain] 과 **똑같은 결함**이
  //   여기에도 있었다(사용자가 염에서 찾은 결함군을 빙에 훑다 나왔다).
  // ⚠️⚠️ 바로 아래 `f = (1 − v) · a` 는 **`v = 0` 에서 최댓값**이다. 곧
  //   **종료 마디의 첫 프레임 — 제일 밝은 프레임 — 이 통째로 빠지고 있었다.**
  //   소멸이 끝나고 종료가 시작되는 그 이음매에서 한 프레임이 비면 「뚝」 하고
  //   끊겨 보인다. ⇒ `v = 0` 을 그린다.
  // ⚠️ [IZcastFx]·[IZsigil] 도 같이 봤는데 **그 둘은 아니었다** — 둘 다 알파가
  //   `v` 에 **비례해 오르므로**(`op(k) = ss((v − k·.11)/.52)`) `v = 0` 은
  //   원래 아무것도 안 그린다. **고칠 자리와 아닌 자리를 갈라서** 봤다.
  if (v < 0 || v >= 1 || a <= .01) return;
  const f = (1 - v) * a;
  IBroot(c, cx, cy, R * (1 + .35 * v), "frost", .22 * f, .38);
  IBrim(c, jagPoly(cx, cy, R * (.86 + .30 * v), 13, seed + 6.1, 1.02, .38),
    "frost", .34 * f, 1.1 * SC);
  for (let j = 0; j < 3; j++) {
    const a0 = (j + .5) / 3 * TAU + seed;
    IBmist(c, cx + Math.cos(a0) * R * .5, cy + Math.sin(a0) * R * .5 * .38 - R * .5 * v,
      R * (.30 + .20 * v), seed + j * 4.3, .55 * f, .9);
  }
}

// ── ⚠️ 난수 0건 ──────────────────────────────────────────────────────────
// `Math.random` 을 부르는 도구(`emit` · `hitFoe` · `IBpushFrag`)를 **하나도 안
// 쓴다**(`vfx-frostspot.js` · `vfx-frostlv.js` 와 같은 규율). 조각 · 부스러기는
// [hash] 표에서 나오고, 그려지는 값이 전부 **주기에 못 박은 시각 `tau`** 에서
// 파생된다 ⇒ 주기 끝과 처음이 이어진다.
// ⚠️ 흔들림은 **주기당 정수 바퀴**의 사인이라야 한다. 절대 시각 `t` 로 도는
//   층(영웅 호흡 · 적 실루엣 요동)을 그대로 두면 이음매에서 도약이 난다 —
//   그래서 `tp`·`th` 를 주기에서 파생해 넘긴다([FQlv] 와 같은 수법).
//
// ── 왜 별도 파일인가 ──────────────────────────────────────────────────────
// `vfx.js` 는 5만 줄이고 같은 사이클에 여러 손이 같이 쓴다. `vfx-poison.js` ·
// `vfx-flamelv.js` · `vfx-frostspot.js` · `vfx-frostlv.js` 의 전례대로 새 그림은
// 여기 만들고 `vfx.js` 는 **읽기만** 한다. 장이 `vfx.js` · `char-page.js`
// **뒤에** 이 파일을 부르므로 `FX`·`LV`·`TONE`·`tile`·`lvTable`·`hash`·`saw`·
// `hero`·`charRk`·`IB*`·`IC*` 가 다 보인다.
// ⚠️ 최상위 이름을 전부 `IZ` 로 격리한다(실측: `IZ` 로 시작하는 이름이
//   `docs/vfx/*.js` 전체에 **0건**이었다).
// ⚠️ 이 파일이 찾는 격자는 **둘뿐**이다 — `#izfreeze`(결빙 성장표) ·
//   `#ispirit`(정령 — 하나와 상한 셋). 없는 장에서는
//   조용히 건너뛴다. ⚠️ `#izcairn` 은 얼음 무지와 같이 걷혔다.
// ⚠️⚠️ **`window.IZDBG.K` 에 뒤에 선 상수를 더할 때는 파일 맨 끝에서 한다** —
//   객체 리터럴 안에서 읽으면 TDZ 로 파일이 통째로 죽는다(맨 아래 참조).
// ══════════════════════════════════════════════════════════════════════════

// ── 공통 도우미 ───────────────────────────────────────────────────────────
const IZcl = (u) => (u < 0 ? 0 : (u > 1 ? 1 : u));
/// 매끈 계단 — 양 끝에서 미분이 0 이라 켜지고 꺼지는 자리가 안 튄다.
const IZss = (u) => { const v = IZcl(u); return v * v * (3 - 2 * v); };
/// `a`→`b` 구간을 0→1 로 편다.
const IZseg = (x, a, b) => IZcl((x - a) / (b - a));
/// 꼬리 램프 — 주기 끝 `w` 초 전부터 0 으로 내려가고 `PER-.04` 부터는 **정확히
/// 0** 이다. 그 0 구간이 있어야 주기 끝 화면이 주기 처음과 같아진다
/// (`vfx-frostlv.js` 의 `FQz` 가 같은 자리에서 같은 판단을 했다).
const IZz = (tau, PER, w) => 1 - IZss(IZseg(tau, PER - (w || .34), PER - .04));

/// 적 — **자리는 238칸 단위로 들고** 그릴 때만 `SC` 를 곱한다. 칸 크기가
/// 바뀌어도 박자가 안 흔들린다(`mgInit` 은 초기화 때 한 번만 곱해서 그렇게 못 한다).
function IZfoes(st, SC, l) {
  if (!st.F) st.F = l.map((v) => ({ ux: v[0], uy: v[1], ru: v[2],
    ox: 0, oy: 0, r: 0, hit: 0, kx: 0, ky: 0, ax: 0, ay: 0,
    sx: 0, sy: 0, pv: 0, frz: 0, burn: 0 }));
  for (const f of st.F) f.r = f.ru * SC;
  return st.F;
}

/// 주기가 넘어갔나 — 넘어갔으면 앞 주기의 셈을 **전부** 지운다.
/// ⚠️ 지우는 순간 화면이 바뀌면 안 된다. 그 앞에서 꼬리 램프가 이미 0 을
///   만들어 두므로, 이 함수가 지우는 것은 **안 보이는 상태**뿐이다.
function IZwrap(st, u) {
  const w = (st.pu === undefined || u < st.pu);
  st.pu = u;
  if (w) {
    st.n = 0; st.ch = []; st.ev = {}; st.tr = [];
    if (st.F) for (const f of st.F) {
      f.pv = 0; f.frz = 0; f.ax = 0; f.ay = 0; f.kx = 0; f.ky = 0;
      f.sx = 0; f.sy = 0; f.hit = 0;
    }
  }
  st.ch = st.ch || []; st.ev = st.ev || {}; st.tr = st.tr || [];
  return w;
}

/// 적을 제자리에 세운다 — 요동은 **주기당 정수 바퀴**라 이음매가 없다.
/// 언 놈은 요동이 멎고(`hold`), 밀린 몫·미끄러진 몫은 램프를 타 정확히 0 이 된다.
function IZstand(F, SC, wob, z) {
  for (const f of F) {
    const hold = f.frz ? z : 0;
    f.ox = f.ux * SC + (1 - hold) * Math.sin(wob + f.ux * .07) * 3.0 * SC + f.sx * SC * z;
    f.oy = f.uy * SC + (1 - hold) * Math.cos(wob + f.uy * .05) * 2.2 * SC + f.sy * SC * z;
    f.kx = f.ax * SC * z; f.ky = f.ay * SC * z;
  }
}

/// ⭐ **얼린다** — 빙판·우박이 부르는 **한 함수**. 문턱을 넘으면 언다.
/// ⚠️ 문턱 판정을 칸마다 손으로 쓰면 그날로 값이 갈린다 — 여기 하나뿐이다.
function IZchill(f, add) {
  f.pv = Math.min(IZF_MAX, f.pv + add);
  if (f.pv >= IZF_ON) f.frz = 1;
}
/// 녹는다 — **언 놈은 안 녹는다.** 빙결은 깨야 풀리는 것이지 시간이 푸는
/// 것이 아니다(그래야 「깨뜨리기의 밥」이 주기 내내 남는다).
function IZthaw(f, sub) { if (!f.frz) f.pv = Math.max(0, f.pv - sub); }

/// ⭐⭐ **빙결 도장** — 언 몸 위의 육각 결정 하나. **다섯 칸이 이것만 쓴다.**
/// ⚠️ 회전값이 상수 0 이다. 도는 도장은 「돌아가는 표식」이 되어 빙결(정지)의
///   뜻을 지운다 — `pvMark` 의 freeze 가지가 `t` 를 한 번도 안 쓰는 것과 같다.
function IZseal(c, x, y, r, SC, a) {
  IBflake(c, x, y, r * 1.28, 0, "frost", .88 * a, 1.15 * SC, .94);
  IBspark(c, x, y - r * .34, r * .40, "frost", .55 * a, .6);
}

/// 상태 표식을 **뒤 층 → 적 → 앞 층 → 도장** 으로 끼운다. `mgMarks` 와 같은
/// 일인데 **적마다 상태가 다를 수 있다**(동상 ↔ 빙결)는 것만 다르다 — 이 여섯은
/// 「굳는다」와 「서린다」가 한 칸에 같이 서므로 한 종류로는 못 그린다.
/// ⚠️ 도장은 **제일 위**다. 적 실루엣 밑에 깔면 「몸에 앉은 표식」이 아니라
///   「뒤에 있는 무늬」가 된다.
function IZmarks(c, tp, cx, cy, F, SC, z) {
  const mark = (L) => { for (const f of F) if (f.pv > 0)
    pvMark(c, cx + f.ox + f.kx, cy + f.oy + f.ky, f.r,
      f.frz ? "freeze" : "frost", f.pv, tp, "frost", SC, L); };
  mark(0); drawFoes(c, tp, cx, cy, F); mark(1);
  const zz = (z == null ? 1 : z);
  for (const f of F) if (f.frz)
    IZseal(c, cx + f.ox + f.kx, cy + f.oy + f.ky, f.r, SC, zz);
}

// ── 불티 — **조각 하나의 정본**(여섯이 같이 쓴다) ─────────────────────────
/// 조각을 낳는다. 각 · 속도 · 크기가 전부 [hash] 에서 나온다 — **난수 0**.
///   `b` 태어난 시각(주기 안, s) · `a` 각(없으면 한 바퀴에 고르게) ·
///   `v` 속도(238칸/s) · `g` 중력(238칸/s²) · `life` 수명(s)
function IZchip(st, x, y, seed, n, o) {
  for (let j = 0; j < n; j++) st.ch.push({ x, y, b: o.b,
    a: (o.a == null) ? (j + .5) / n * TAU + hash(seed + j * 1.7) * .5
                     : o.a + (hash(seed + j * 2.9) - .5) * (o.spread || 1.6),
    v: (o.v || 40) + (o.vr || 30) * hash(seed + j * 5.3),
    r: (o.r || 1.6) + (o.rr || 1.4) * hash(seed + j * 7.1),
    m: o.life || .40, g: (o.g == null ? 120 : o.g) });
}
/// 조각을 그린다 — 자리가 **시각의 함수**라 프레임을 건너뛰어도 같은 그림이다.
function IZchips(c, st, tau, SC, z) {
  for (const q of st.ch) {
    const s = tau - q.b; if (s <= 0 || s >= q.m) continue;
    const w = s / q.m;
    IBshard(c, q.x + Math.cos(q.a) * q.v * s * SC,
      q.y + Math.sin(q.a) * q.v * s * SC + .5 * q.g * s * s * SC,
      q.r * SC * (1 - .45 * w), q.a + 1.1, "frost",
      Math.min(1, w * 9) * (1 - w) * .92 * z, .5);
  }
}

// ── 각진 고리 — **마법진의 획 하나** ─────────────────────────────────────
/// 눌린 정n각형. ⚠️ **타원을 쓰면 안 된다** — 결빙(`POportal`)의 마법진이
/// `IBrune` 의 **동심 타원**이라, 여기서 타원 고리를 그으면 두 스킬이 화면에서
/// 같은 물건이 된다. 빙판의 마법진은 **결정 격자**라 각이 져야 한다([IZR_SIG]).
function IZpoly(px, py, r, n, rot, sq) {
  const P = [];
  for (let i = 0; i <= n; i++) {
    const a = rot + i * TAU / n;
    P.push([px + Math.cos(a) * r, py + Math.sin(a) * r * sq]);
  }
  return P;
}

// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐ **얼음 폭발 + 스플래시** — 「터졌다」의 정본           (2026-08-28)
//
// 사용자: 「깨트릴 경우 **얼음 폭발 효과를 화려하게 + 스플래시 추가**」.
// 깨뜨리기가 빙의 **터뜨리는 자리**라 제일 화려해야 하고, 우박의 착탄도 같은
// 사건이라 **같은 함수**를 쓴다 — 둘이 갈리면 「터졌다」가 두 종류가 된다.
//
// ── 다섯 겹이 다 있어야 「터졌다」로 읽힌다 ───────────────────────────────
//   ① **속심**   — 흰 발광이 한 번 부푼다. 제일 먼저 죽는다(0→1 의 앞 30%)
//   ② **충격테** — 각진 테가 빠르게 밖으로 (빠름)
//   ③ **뒤테**   — 두 번째 테가 **느리게** 뒤따른다. 겹이 둘이라야 「퍼진다」다
//   ④ **스플래시** — 바닥에 **눕는** 물결. 서 있는 테와 **면이 달라야** 겹이
//      겹으로 읽힌다(같은 면에 두 개면 그냥 굵은 테 하나로 보인다)
//   ⑤ **파편 날** — 방사로 **날아가는 프리즘 여덟**. 「사방으로」를 말하는
//      유일한 항이고, 이것이 **얼음** 폭발을 불 폭발과 가른다 ⚠️ 첫 판은 가는
//      획 여섯이라 「빛이 뻗었다」였지 「얼음이 터졌다」가 아니었다
//
// ⚠️ **면적이 아니라 겹으로 화려하게 만든다.** 이 레포 실측에서 병목은 GPU
//   채우기(raster p95 18.24 vs build 0.49)라 **넓은 면을 키우면 곧장 비싸다.**
//   같은 자리에 층을 쌓는 것은 면적이 안 늘어난다 — 위 다섯 겹이 전부 **같은
//   중심**에 서는 이유가 그것이다.
// ══════════════════════════════════════════════════════════════════════════
/// `v` 0→1 진행 · `R` 최대 반지름(px) · `sq` 서 있는 테의 눌림(1=안 눕는다)
function IZboom(c, x, y, v, R, SC, a, seed, sq) {
  if (v >= 1 || v < 0 || a <= .01) return;
  const q = (sq == null ? .86 : sq);
  // ① 속심 — 앞 30% 만 산다
  const core = 1 - IZcl(v / .30);
  if (core > .01) IBroot(c, x, y, R * (.34 + .40 * v), "frost", .92 * core * a, q);
  // ② 충격테 — 빠르다
  IBrim(c, jagPoly(x, y, R * (.22 + .86 * IZss(v * 1.25)), 11, seed, 1.10, q),
    "frost", (1 - v) * .95 * a, 2.8 * SC * (1 - v * .5));
  // ③ 뒤테 — 느리게 뒤따른다. **겹이 둘이라야 퍼지는 것으로 읽힌다**
  const v2 = IZcl(v * 1.55 - .28);
  if (v2 > 0) IBrim(c, jagPoly(x, y, R * (.18 + .70 * v2), 9, seed + 3.3, 1.06, q),
    "frost", (1 - v2) * .60 * a, 1.8 * SC);
  // ④ 스플래시 — **눕는다.** 서 있는 테와 면이 갈려야 겹이 겹으로 읽힌다
  IBroot(c, x, y + R * .16, R * (.30 + .95 * IZss(v)), "frost", (1 - v) * .40 * a, .34);
  IBrim(c, jagPoly(x, y + R * .16, R * (.26 + .92 * IZss(v)), 13, seed + 7.7, 1.03, .34),
    "frost", (1 - v) * .58 * a, 1.5 * SC);
  // ⑤ 파편 날 — 방사로 **날아가는 프리즘 여덟**. 얼음 폭발을 얼음으로 만드는 항
  for (let j = 0; j < 8; j++) {
    const a0 = (j + .5) / 8 * TAU + seed * .21;
    const d0 = R * (.26 + .78 * IZss(v)) * (.78 + .40 * hash(seed + j * 4.1));
    const L = R * (.30 + .16 * hash(seed + j * 6.7)) * (1 - v * .55);
    if (L < 1) continue;
    IBneedle(c, x + Math.cos(a0) * d0, y + Math.sin(a0) * d0 * q, a0,
      L, L * .26, seed + j * 3.3, "frost", (1 - v) * .90 * a,
      { tip: .18, slant: .55, mos: 1, w: 1.0 * SC });
  }
}

// ══════════════════════════════════════════════════════════════════════════
// ① 빙판 `rinkfield` — **결정 마법진이 깔린다. 한기가 오르고 적이 언다**
// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐ **2026-08-28 재설계 — 「일반 빙판」을 걷었다.**
//   > 「**빙판**은 다시 재설계. 방향은 **화려하고 마법진의 모양**으로.
//   >  일반 빙판이 아니라 **결정 모양의 마법진이 펼쳐지고 한기가 올라오며
//   >  거기서 얼음결정이 빛나는** 화려한 느낌으로.
//   >  지나가거나 부딪힌 적 **빙결 효과**(깨트리기와 연쇄 작용)」
//   앞 판은 **눌린 다각형 하나에 금 다섯**이었다 — 갈무리로 보면 「깨진 얼음
//   웅덩이」고, 사용자가 말한 셋(마법진 · 한기 · 빛나는 결정) 중 **하나도
//   없었다**. 그래서 그림을 통째로 다시 짰다.
//
// ── 세 마디가 **다 보여야** 한다 ─────────────────────────────────────────
//   ㉠ **마법진이 펼쳐진다** — 각진 고리 셋이 안에서 밖으로 차례로 열리고,
//      결정 살 여섯이 뻗어 나가며 끝마다 육각 문장이 앉는다
//   ㉡ **한기가 올라온다**   — 판 위로 **오르는** 김 줄기. ⚠️ 위로 흐르는
//      것이 이 마디의 전부다 — 제자리에서 밝기만 흔들면 「깔린 안개」가 된다
//   ㉢ **결정이 빛난다**     — 격자 자리마다 얼음 결정이 서고, 그중 하나씩
//      차례로 **밝아진다**(숨). 안 빛나면 그냥 놓인 돌이다
//
// ── ⚠️⚠️ **결빙(`POportal`)의 마법진과 겹치면 안 된다** ──────────────────
// 결빙도 바닥에 마법진을 그린다(`IBrune`). 둘이 같은 화면에 서므로 **무엇으로
// 가르는지**가 설계의 절반이다. 셋으로 갈랐다:
//
//   ┌────────┬─────────────────────────┬──────────────────────────────┐
//   │        │ 결빙 `POportal`         │ 빙판 `rinkfield`             │
//   ├────────┼─────────────────────────┼──────────────────────────────┤
//   │ 방향   │ **위에서 오는 문**      │ **바닥에서 오르는 결**       │
//   │ 획     │ **동심 타원**(`IBrune`) │ **각진 결정 격자**(`IZpoly`) │
//   │ 수명   │ 예고 0.165초 → 스러짐   │ **1.92초 깔린 채 남는다**    │
//   └────────┴─────────────────────────┴──────────────────────────────┘
//   ⚠️ **이 파일은 `IBrune` 를 한 번도 안 부른다** — 그것이 위 표의 집행이다.
//     검산은 **주석을 뺀 사본**에서 세야 한다(이 표 자체가 그 이름을 적고 있다):
//       `grep -v '^\s*//' docs/vfx/vfx-ice6.js | grep -c 'IBrune('`  = 0
//
// 면 = **눕는다**(장판). 위에서 본 원이 타원인 것이 맞다 — 눌림 [IZR_SQ].
//
// 항 넷 ─ 덩어리: 마법진 바닥판 + 결정 무리 / 층: 각진 고리 셋 + 살 + 문장 /
//         불티: 밟히는 자리의 부스러기 + 오르는 한기 / 잔상: 미끄러진 흰 자국
// ⭐⭐ **2026-08-28 사용자 설계 판정 — 장판은 몸 발밑이 아니라 「던져 까는」 것이다.**
//   > 「다른 속성 스킬들에게도 정전장·점멸판처럼 **같은 메커니즘으로 도는 게
//   >  있으면 1개만 남기고** 나머지 하나는 다른 식으로 구현하게 해 줘」
//   > 「보통 장판이라고 하면 **사거리가 있고, 캐릭터 주변에서 일정 사거리
//   >  바깥에다가 스킬 시전하는 경우**가 많더라고」
//   ⚠️ 까닭은 미학이 아니라 **동시 착용**이다 — 무기를 여섯 자루까지 끼는데
//     둘 다 발밑에 깔면 화면에서 서로를 지운다(뇌의 정전장·점멸판이 그렇게
//     반려됐다). ⇒ **몸 발밑 판은 한 속성에 하나까지.**
//   ⚠️⚠️ **2026-08-28 8차 — 이 근거가 바뀌었다.** 앞 판은 「빙에서 발밑을 쓰는
//     하나는 **상고대**」였는데 그 상고대가 폐기됐다 ⇒ **빙에 발밑 판이 하나도
//     없다.** 그래도 빙판은 **던져 깐다**를 유지한다. 까닭이 둘이다:
//       ① 규칙은 「발밑 판은 한 속성에 **하나까지**」이지 「하나는 있어야 한다」가
//          아니다 — 비어 있는 것은 위반이 아니다.
//       ② 이 칸의 항 셋(**던지는 순간** · 서 있는 동안 · 사라지는 순간)이
//          「던져 깐다」에서 나온 것이라, 발밑으로 되돌리면 **①이 통째로 없어진다**.
//     ⇒ 발밑 자리가 비었으니 **다음에 발밑 스킬을 낼 자리가 하나 생긴 것**이다.
//   ⚠️ **한 줄 설명은 안 바뀐다** — 「바닥이 얼어붙는다. 밟은 적이 미끄러져 판
//     바깥으로 밀려난다」 그대로다. 바뀐 것은 **어디에 깔리나** 하나뿐이다.
//   ⚠️ 그래서 항이 셋 붙는다: ① **던지는 순간**(어디서 왔나) ② 서 있는 동안
//     ③ **사라지는 순간**. ① 이 없으면 판이 **어디서 왔는지 안 읽힌다.**
// ── ⭐⭐ 다섯 마디 (2026-08-28 사용자 지시) ───────────────────────────────
//   시전 0.34  몸에서 냉기가 **모인다**([IZcastFx])
//   생성 0.30  **빛 투사체**가 자리로 날아가 꽂힌다 ⭐ 아래 [IZR_BOLT] 참조
//   발현 2.06  마법진이 펼쳐지고 · 한기가 오르고 · 결정이 빛나고 · 적이 언다
//   소멸 0.56  테가 깨지고 결정이 무너진다(조각 + 김)
//   종료 0.34  바닥 자국만 남아 스러진다([IZrestFx])
//   합 3.60 = 주기 ✓
/// ⚠️⚠️ **2026-08-28 6차 — 비행을 0.30 → 0.62 로 두 배 넘게 늘렸다.**
///   사용자 판정: 「던져 보내는 투사체가 **그냥 스티커가 날아가는 느낌**
///   (**폭발하는 효과가 없음. 투사체가 느림.**)」
///   ⚠️ 진단이 「느리다」였는데 실측은 **반대**였다 — 비행이 주기 3.60초의
///     **8%(0.30초)** 뿐이라 **볼 시간이 없어서** 「날아갔다」가 아니라
///     「자리가 바뀌었다」로 읽혔다. 속도선을 셋이나 그어 놓고 **나타났다
///     사라진 것**이다. ⇒ 느리게 만든 것이 아니라 **오래 보이게** 했다.
///   ⚠️ **주기는 안 늘렸다** — 발현에서 0.32 를 떼어 왔다(2.06 → 1.74).
///     ⭐ 떼어도 되는 근거: 발현의 몫은 「마법진이 서 있는 시간 = **밟는
///     시간**」인데, 그 안에서 한기가 **주기당 세 바퀴** 오르고 결정 여섯이
///     차례로 빛나는 것이 1.74초로도 **다 들어간다**(한 바퀴 0.58초).
///     밟는 시간을 더 줄이면 그때는 게임 감각을 건드리므로 **여기가 바닥**이다.
const IZR_B = [.34, .62, 1.74, .56, .34];
const IZR_PER = 3.6;          // 주기(s) — 3.0 에서. **한 번을 크게** 사 온 값
const IZR_UP = .34;           // 마법진이 펼쳐지는 데 걸리는 몫(발현 앞머리)
const IZR_OUT = .56;          // 소멸 — 테가 깨지며 조각이 난다
// ── ⭐ 「거미줄」을 걷는다 (2026-08-28 사용자 판정) ────────────────────────
//   > 「**스파이더맨 거미줄 날리듯이 날리지 말고** 투사체나 **빛 그 자체를
//   >  날리는** 게 좋아 보임」
// 앞 판은 몸에서 코어까지 **선을 그었다**(`IBline`) — 그것이 거미줄로 읽혔다.
// ⇒ **선을 지웠다.** 대신 날아가는 것은 **빛덩이 하나**이고, 뒤에 남는 것은
//   선이 아니라 **점점이 흩어지는 반짝이**(꼬리는 그리는 것이 아니라 남는 것이다).
const IZR_BOLT = 11;          // 날아가는 빛덩이의 반지름(238칸)
const IZR_TRAIL = 5;          // 뒤에 남는 반짝이 수 — **선이 아니다**
const IZR_R = 64;             // 판 반지름(238칸) — **다섯 칸이 같다**
const IZR_SQ = .44;           // 눕힘 — 장판이라 타원이다
/// 던지는 코어가 그리는 활의 높이(238칸). 직선으로 가면 「미끄러져 간 것」이
/// 되고, 살짝 떠야 **「던졌다」**로 읽힌다.
const IZR_ARC = 26;
const IZR_SPD = 17;           // 미끄러지는 속도(238칸/s)
const IZR_SPD2 = 27;          // 금 위에서(L2~) 빨라지는 속도
/// ⚠️ **자리는 몸에서 떨어져 있다.** 판 한 장의 자리는 몸에서 **70칸** 이고,
///   눌린 타원의 아래 테가 y=−43.6 이라 몸(반지름 ≈17)과 **27칸이 빈다** —
///   「발밑」으로 안 읽히는 최소 거리다.
/// ⚠️ 앞 판은 이 여백의 근거를 **상고대와의 대비**로 적었는데 상고대가 폐기됐다
///   (2026-08-28 8차). 근거는 **대비가 아니라 이 수 자체**로 바꾼다 — 27칸이
///   비어야 「놓고 온 것」이지 「발밑에 깔린 것」이 아니다.
const IZR_ONE = [[4, -70]];              // 판 한 장의 자리 — 몸에서 70.1칸
const IZR_TWO = [[-40, -74], [40, -76]]; // L4~ 두 장 (반지름이 44 로 준다)
/// 적 넷 — 앞 셋은 판 안, 넷째는 판 밖이다(경계를 읽어 주는 자리).
/// ⚠️ L4(두 장)에서는 적2 가 **두 판 사이**에 서서 「사이에 낀다」를 말한다.
const IZR_FOE = [[-30, -66, 9], [34, -80, 9], [2, -92, 10], [72, -40, 9]];
// ── ⭐ 마법진의 치수 — **여기가 재설계의 몸통이다** ───────────────────────
/// 결의 수. **여섯**이라야 얼음이다 — 육각이 아닌 마법진은 그냥 마법진이고,
/// 이 스킬이 팔아야 하는 것은 「얼음의 마법진」이다.
const IZR_SIG = 6;
/// 착탄에서 갈라지는 바닥 금의 갈래 수 · 한 번에 뿌리는 조각 수(세 벌).
/// ⚠️ 「꽂혔다」를 말하는 항이라 **길고 여러 갈래**라야 한다.
const IZR_CRK = 9, IZR_LAND = 8;
/// 각진 고리 셋의 반지름 비. 안에서 밖으로 **차례로** 열린다(㉠ 의 「펼쳐진다」).
const IZR_RING = [.34, .68, .94];
/// 고리 하나가 열리는 데 걸리는 몫(마디 진행 0~1 안에서). 셋이 겹쳐 열려야
/// 「한 장이 펴진다」이지, 다 떨어져 열면 고리 셋이 따로 논다.
const IZR_RGAP = .22;
/// 안에서 빛나는 결정 수 — 살 끝에 하나씩. ⚠️ 개수를 늘리는 것보다 **하나가
/// 차례로 밝아지는 것**이 싸고 잘 읽힌다(면적이 안 는다).
const IZR_GEM = 6;
/// 오르는 한기 줄기 수 · 오르는 높이(238칸) · **한 주기에 오르는 바퀴 수**.
/// ⚠️ 바퀴 수는 **정수**라야 주기 끝과 처음이 이어진다([FQlv] 와 같은 규율).
const IZR_VAP = 7, IZR_VAPH = 20, IZR_VAPT = 3;
/// 판 위에 선 적이 **초당 차는 빙결**. 1.30/s 라 [IZF_ON]=1.5 까지 **1.15초** —
/// 판이 서 있는 2.1초의 **절반**에서 언다. ⚠️ 앞 판의 0.9 로는 1.67초가 걸려
///   주기 끝에 겨우 얼었고, 그러면 「얼렸다」가 화면에 0.4초만 남는다.
const IZR_FRZ = 1.30;

// ══════════════════════════════════════════════════════════════════════════
// ② 우박 `hail` — **마당에 알이 쏟아진다. 세 번 맞은 놈이 언다**
// ══════════════════════════════════════════════════════════════════════════
// ⚠️⚠️ **결빙과 겹치지 않게** 네 자리를 갈랐다(결빙 = `POportal`, 포탈 낙하):
//   ㉠ 결빙은 **한 자리를 조준한다** · 우박은 **마당에 흩뿌린다**(조준이 없다)
//   ㉡ 결빙이 떨어뜨리는 것은 **길고 얇은 고드름 + 본체 기둥** ·
//      우박은 **짧고 굵은 알**이다(길이÷폭 7.6 ↔ 1.2)
//   ㉢ 결빙은 **공중 포탈**에서 나온다 · 우박의 예고는 **바닥 그림자**다
//   ㉣ 결빙은 한 주기에 **한 번** 발동한다 · 우박은 주기 내내 **계속** 쏟아진다
//
// 항 넷 ─ 덩어리: 얼음 알 / 층: 알의 결정 셋 + 그림자 + 낙하 빔 /
//         불티: 깨질 때 튀는 조각 / 잔상: 떨어진 자리의 **미끄러운 자국**
//
// ⭐⭐ **2026-08-28 사용자 판정 — 더 오래, 더 많이, 그리고 얼린다.**
//   > 「**우박**은 **떨어지는 지속시간과 양을 더 늘릴 것** → 화려함 추가 필요.
//   >  지나가거나 부딪힌 적 **빙결 효과**(깨트리기와 연쇄 작용)」
//
// ── ⚠️ 「더 많이」를 **동시에 더 많이**로 읽으면 비싸진다 ────────────────
// 앞 판은 알 4~10 이 **0.62초 안에 한꺼번에** 떨어졌다 — 한 프레임에 열 알이
// 다 살아 있어 **peak 가 거기서 났고**(L5 22,593), 그런데도 화면은 「잠깐 후드득」
// 이라 양이 안 느껴졌다. 답은 개수를 그 창에 더 쑤셔 넣는 것이 아니라
// **창을 늘리는 것**이다:
//     태어나는 폭  0.62초 → **1.90초** (주기의 26% → **59%**)
//     알 수        4~10   → **9~26**  (L5 기준 **2.6배**)
//     동시 생존    ≈ 10   → **≈ 8**   (오히려 준다 ⇒ peak 는 안 는다)
// ⇒ 「지속시간과 양」이 둘 다 늘면서 **한 프레임의 몫은 안 는다.** 이 레포의
//   병목이 개수가 아니라 **채우기 면적**이라는 실측이 그대로 적용된 자리다.
//
// ── 뒤끝 검산 — 마지막 알이 주기 안에 든다 ───────────────────────────────
//   마지막 알(i=N−1=25) 태어남 = 25/26 × 1.90 = **1.827**
//   착탄 = 1.827 + 0.20 + 0.26 = **2.287**
//   자국 끝 = 2.287 + 0.85 = **3.137** < 주기 3.20 − 0.04 ✓
//   ⚠️ 큰 알은 자국이 1.5배(1.275초)지만 **i<BIG 이라 늘 앞쪽에서 태어난다** —
//     i=2 는 0.146 에 나서 1.88 에 끝난다. 뒤끝이 안 잘린다.
// ── ⭐⭐ 다섯 마디 (2026-08-28) · 그리고 「여전히 개수가 적음」 판정 ────────
//   > 「**우박**은 여전히 **내리는 개수가 적음**」 (2026-08-28 2차 판정)
//   1차에서 4~10 → 9~26 으로 늘렸는데 **여전히 적다**는 판정이 왔다. 까닭은
//   개수가 아니라 **창**이었다 — 태어나는 폭 1.90초에 26 이면 초당 13.7 이지만
//   한 알의 생존이 0.60초라 **한 화면에 여덟**뿐이다. ⇒ 개수를 또 늘리면서
//   주기도 늘려(3.2 → **4.2**) 「오래 · 많이」를 둘 다 산다.
//   시전 0.40  머리 위에 **냉기 구름 고리**가 모인다([IZcastFx] + 하늘 고리)
//   생성 0.30  마당에 예고 그림자가 **쫙 퍼진다**(아직 안 떨어진다)
//   발현 2.60  알이 쏟아진다([IZH_SPREAD])
//   소멸 0.60  마지막 자국이 스러지고 조각이 남는다
//   종료 0.30  김만 남는다([IZrestFx])
//   합 4.20 = 주기 ✓
const IZH_B = [.40, .30, 2.60, .60, .30];
const IZH_PER = 4.2;          // 2.4 → 3.2 → **4.2**
const IZH_TELE = .20;         // 바닥 그림자가 먼저 보인다(예고)
const IZH_FALL = .32;         // 낙하 — 0.26 → 0.32. **공중에 떠 있는 알이 는다**
const IZH_BRK = .14;          // 깨짐
const IZH_MARK = .85;         // 미끄러운 자국의 수명 — 뒤끝이 주기 안에 들도록
/// ⭐ 알들이 태어나는 폭(s) — 0.62 → 1.90 → **2.55**(주기의 61%).
/// ⚠️ 발현 마디(2.60) 안에서 다 태어나야 한다. 마지막 알(i=N−1)은
///   (N−1)/N × 2.55 = 2.49 에 나고 착탄이 3.05, 자국 끝이 3.90 <
///   시전+생성+발현+소멸 = 3.90 ⇒ 뒤끝이 **정확히** 소멸 끝에 닿는다.
const IZH_SPREAD = 2.55;
const IZH_R = 8.2;            // 알 반지름(238칸) — 6.4 였는데 화면에서 너무 작았다
const IZH_BIGR = 2.1;         // 큰 알 배수
/// ⭐ 알 수 — 4~10 → 9~26 → **20~56**. 사용자 2차 판정(「여전히 적음」) 뒤의 값.
/// ⚠️ 「한 화면에 몇 알인가」로 계산한다(총 개수가 아니라 **동시 생존**이 눈에
///   보이는 수다): 창 2.55초에 56 이면 초당 22.0, 한 알이 예고+낙하+깨짐
///   0.66초를 사니 **한 화면에 열넷**이다(1차 여덟 · 2차 열). 자국은 0.85초
///   살아 **열아홉**이 겹친다.
const IZH_N = [30, 42, 54, 70, 88];
/// ⭐ 그중 큰 알. ⚠️ **L3 은 0 이라야 한다** — 축이 「수 → 파편 → 큰 알」이라
///   파편(L3)과 큰 알(L4)이 같은 칸에서 시작하면 사건 하나가 묻힌다.
const IZH_BIG = [0, 0, 0, 6, 9];
/// 낙하 빔의 길이 배수(알 반지름 대비). 앞 판은 2.6 이라 **꼬리가 안 보였다** —
/// 알이 어디서 왔는지가 안 읽히면 「떨어진다」가 「생겼다」가 된다.
const IZH_BEAM = 7.0;
/// 알 하나가 스치는 거리(238칸) · 한 번 스칠 때 차는 빙결.
/// [IZF_ON]=1.5 라 **세 번** 맞으면 언다 — 비가 오래 오는 칸이므로 이 정도가
/// 「비를 맞고 서 있으면 언다」로 읽힌다.
const IZH_NEAR = 30, IZH_FRZ = .55;
const IZH_FOE = [[-52, -64, 9], [22, -40, 9], [62, -86, 9], [-14, -96, 10]];

// ══════════════════════════════════════════════════════════════════════════
// ⭐ **걷어낸 둘** — 여기 있던 두 칸의 폐기 기록                (2026-08-28)
// ══════════════════════════════════════════════════════════════════════════
// ⚠️ **폐기 사유는 남긴다**(이 레포 규약) — 안 남기면 다음 손이 같은 것을 다시
//   낸다. 남기는 것은 **사유뿐**이고 정의 · 지도 · 마운트는 전부 걷었다.
//
// ── ㉠ 얼음 무지 `cairn` — 폐기 (6차) ────────────────────────────────────
//   사용자: 「**얼음무지는 폐지**」. 두 번(각진 판 → 홀로그램 등축)이나 다시
//   그린 뒤의 판정이다. 계열 · 등급은 **보조 · 변주**였다.
//   ⇒ 걷은 것: `FX.IZcairn` · 상수 `IZC_*` 열셋 · `IZiso`(등축 덩이) ·
//     `IZfixture`(설치물 세 마디) · [IZSK] 한 줄 · `#izcairn` 마운트 ·
//     장의 절 하나 · 목차 고리 · 표 넉 줄 · 칸 수 · **면 지도 [IZPLANE] 한 줄**.
//   ⚠️ **「쌓다」라는 동사가 이것과 같이 비었다** — 다음 칸의 자를 고를 때 쓴다.
//
// ── ㉡ 상고대 `rime` — 폐기 (8차) ────────────────────────────────────────
//   사용자: 「**빙에서 상고대 폐기하자**」. 계열 · 등급은 **보조 · 기초**였고,
//   **빙에서 발밑을 쓰던 유일한 하나**였다.
//   ⇒ 걷은 것: `FX.IZrime` · 상수 `IZM_*` · [IZSK] 한 줄 · 격자 줄 · 성장표 ·
//     장의 절 · 표 · 칸 수 · 계열 집계 · **면 지도 [IZPLANE] 한 줄**.
//   ⚠️⚠️ **이 폐기가 다른 칸의 근거를 지웠다** — 빙판이 「던져 깐다」인 근거가
//     「발밑을 쓰는 하나는 상고대」라는 **대비**였는데 그 한쪽이 없어졌다.
//     ⇒ 근거를 **대비가 아니라 수 자체**로 바꿔 다시 세웠다([IZR_ONE] 옆).
//     ⭐ 그리고 **발밑 자리가 비었으니 다음에 발밑 스킬을 낼 자리가 하나 생겼다.**
//   ⚠️ **개명으로 폐기하지 않았다** — 정의 · 지도 · 마운트 · 성장표 · 칸 수를
//     한 패스에 걷었다(이름만 갈고 지도를 안 고치면 시안이 통째로 죽는다).
//
// ── ⭐ **설치물 문법은 글로 남긴다** — 코드는 지웠다 ─────────────────────
// `IZfixture()` 를 「분광 · 화로 · 덫이 물려받는다」는 이유로 남기려 했는데,
// **부르는 데가 하나도 없는 함수는 아무도 안 돌려 보므로 조용히 썩는다.**
// ⇒ 코드가 아니라 **사양**으로 남긴다. 다음 설치물은 이 넉 줄로 다시 짓는다:
//   ㉠ **놓임** — 하나씩 **시차**를 두고 자리를 잡는다(시차가 곧 「놓았다」다)
//   ㉡ **서 있음** — 안 움직이면 죽은 물건이다. **아주 느린 숨** 하나만 준다
//   ㉢ **거둠**   — 부서지며 조각이 난다. **불티**가 여기서 나온다
//   ㉣ **자국**   — 거둔 뒤 밑동이 남는다. 「거기 있었다」를 말하는 유일한 항
//   ⚠️ 넷의 합이 **주기 안에 들어와야** 한다 — 안 들어오면 자국이 잘리고,
//     잘린 자국은 주기 이음매에서 통째로 사라져 **도약**이 된다.
// ══════════════════════════════════════════════════════════════════════════
// ③ 깨뜨리기 `shatter` — **언 것을 골라 쳐서 터뜨린다**  ⭐ 정령이 시전한다
// ══════════════════════════════════════════════════════════════════════════
// 면 = **선다**(upright) — 날도 조각도 날아가는 얼음 결정이다.
// 항 넷 ─ 덩어리: 3D 고드름 + 얼음 폭발 / 층: 겹 셋 + 폭발 다섯 겹 /
//         불티: 조각 16 + 스플래시 7 / 잔상: 베인 선 + 얼음 웅덩이
// ── ⭐⭐ 다섯 마디 (2026-08-28) ───────────────────────────────────────────
//   시전 0.30  언 놈 위에 문장이 뜨고 **정령 발치**에서 냉기가 모인다([IZcastFx])
//   생성 0.26  **고드름 투사체**가 날아간다 ⭐ 아래 「3D 고드름」 참조
//   발현 0.62  얼음 폭발 + 스플래시 + 연쇄 빔
//   소멸 0.80  조각이 흩어지고 잔해가 남는다
//   종료 0.62  터진 자리 웅덩이가 스러진다([IZrestFx])
//   합 2.60 = 주기 ✓
const IZS_B = [.30, .26, .62, .80, .62];
const IZS_PER = 2.6;          // 2.2 → 1.9 → **2.6**(마디 다섯을 사 온 값)
const IZS_AIM = .30;          // = 시전
const IZS_FLY = .26;          // = 생성
const IZS_BRK = .10;          // 깨지는 앞머리
const IZS_FRAG = .50;         // 조각이 흩어지는 동안
const IZS_SCAR = .50;         // 베인 선 · 흰 고리
// ── ⭐ 3D 고드름 (2026-08-28 사용자 판정) ─────────────────────────────────
//   > 「**투사체 고드름** 같은 걸 좀 더 **3D로** 표현하고 퀄리티도 높게.
//   >  깨트리는 **고드름 사이즈가 너무 크고** 조악해 보임」
// ⇒ **작게 · 촘촘하게 · 면이 보이게.** 셋을 같이 한다:
//   ① 길이 26 → **17** · 반폭 5.2 → **3.4** (사이즈를 줄인다)
//   ② 프리즘을 **셋 겹쳐** 그린다 — 각을 조금씩 어긋내면 **모서리 면**이 생겨
//      납작한 실루엣이 **입체**로 읽힌다(2D 로 3D 를 만드는 값싼 길)
//   ③ 앞끝에 **밝은 심**과 뒤로 **흩어지는 반짝이** — 밀도가 크기를 대신한다
const IZS_LEN = 17;           // 날 길이(238칸) — 26 에서
const IZS_W = 3.4;            // 날 반폭(238칸) — 5.2 에서
const IZS_FACET = 3;          // 겹쳐 그리는 프리즘 수 — **면**을 만든다
const IZS_FTILT = .17;        // 겹마다 어긋나는 각(rad)
/// ⭐⭐⭐ **총구** — 고드름이 나는 자리. **정령 몸에서 떨어진 몫**(238칸)이다.
/// ⚠️⚠️ 앞 판은 이 값이 **18**(= 캐릭터 몸 반지름 밖)이었고 원점도 `cx`·`cy`
///   였다 — 그래서 시전 마디만 정령으로 옮겨 놓고 **고드름은 여전히 캐릭터에서**
///   날아갔다. 사용자가 그것을 짚었다(「깨트리기 스킬이 정령에서 나가는 게
///   아니고 캐릭터에서 나가네」).
/// ⚠️ 14 = 정령 몸 반지름 [IZE_R] 8.6 의 1.63배다. 캐릭터 값 18 을 그대로 쓰면
///   날이 정령 몸(8.6)에서 5.4칸이나 떨어져 **허공에서 시작**하고, 8.6 이하면
///   몸 한가운데서 튀어나온다.
/// ⚠️ [IZE_R] 을 직접 못 읽는다 — 이 파일 **아래쪽**에 선언돼 TDZ 다.
const IZS_MUZ = 14;
const IZS_CHAIN = .12;        // L3 연쇄가 옮겨 붙는 시차
/// ⚠️⚠️ **옮겨 붙는 거리(238칸).** 처음에 52 로 뒀더니 **L3 이 한 번도 안 터졌다**
///   — 표적에서 제일 가까운 언 놈이 68 이라 문턱 밖이었고, 그 결과 L2 와 L3 의
///   그림이 **화소 하나까지 같았다**(실측 거리 0.000). 「레벨을 올렸는데 아무
///   일도 안 일어난다」가 정확히 이 모양으로 난다 ⇒ **상수를 무대에 맞춘다.**
///   76 이면 적3(68)은 물고 적2(90.8)는 안 문다 — 사건이 하나만 는다.
const IZS_NEAR = 76;
/// 적 다섯 — **0·2·3 이 이미 언 놈**(연계의 전제), 1·4 는 안 언 놈이다.
const IZS_FOE = [[-46, -70, 9], [-14, -44, 9], [44, -58, 9], [16, -98, 9], [-72, -30, 9]];
const IZS_FRZ0 = [1, 0, 1, 1, 0];   // 주기 처음에 얼어 있는가
// ── ⭐ 폭발과 스플래시 (2026-08-28 사용자 판정) ───────────────────────────
//   > 「**깨트리기**는 → 깨트릴 경우 **얼음 폭발 효과를 화려하게 + 스플래시 추가**」
// 이 칸이 빙의 **터뜨리는 자리**라 제일 화려해야 한다. 그림은 [IZboom] 이
// 쥐고(우박의 착탄도 같은 함수를 쓴다) 여기서는 **크기와 수명**만 정한다.
/// 폭발이 사는 시간(s) · 최대 반지름(238칸). ⚠️ 반지름을 더 키우면 옆 적까지
/// 삼켜 「누가 깨졌나」가 흐려진다 — 적 사이 최소 거리가 44 다.
const IZS_BOOM = .54, IZS_BR = 40;
/// 터질 때 튀는 조각 수 — 앞 판 10 에서. **연쇄 쪽은 늘 하나 적다**(주된
/// 폭발과 옮겨 붙은 폭발이 같은 무게면 「연쇄」가 아니라 「둘이 동시에」다).
const IZS_CHIP = 16, IZS_CHIP2 = 12;
/// ⭐ 연쇄가 **보이는** 획 — 깨진 자리에서 다음 놈으로 뻗는 **얼음 빔**.
/// ⚠️ 앞 판은 연쇄가 「0.12초 뒤에 저쪽도 터진다」뿐이라, 갈무리에서는 **두
///   폭발이 그냥 따로 난 것**으로 보였다. 이어진 것이 안 보이면 연쇄가 아니다.
const IZS_BEAMW = .26;        // 빔이 사는 시간(s) — 옮겨 붙는 0.12초보다 길다

// ══════════════════════════════════════════════════════════════════════════
// ④ 서리밭 `frostmire` — **머물면 언다. 다 얼면 깨트리기의 밥이 된다**
// ══════════════════════════════════════════════════════════════════════════
// 사용자: 「빙속성 스킬 1개 — **얼음장판** 하나 만들어 줘. **데미지보다는
//   '얼리는 것에 초점'**. **깨트리기가 있으니까 ㅋ 그거랑 시너지** 맞춰 볼까 해서」
//
// ── ⚠️⚠️ 제일 큰 함정 — **빙에 장판이 이미 하나 있다** ────────────────────
// 빙판(`rinkfield`)이 **바닥 장판**이다. 하나 더 놓으면 화면에서 **안 갈린다.**
// ⇒ 갈리는 자리는 사용자가 이미 줬다 — **동사가 다르다.**
//     빙판   = **민다**   — 위치를 바꾼다. 즉발이고 값이 **방향**이다
//     서리밭 = **얼린다** — 상태를 쌓는다. 값이 **머문 시간**이다
// ⇒ 그림도 그 차이를 진다. **화살(방향)을 한 획도 안 쓴다** — 그건 빙판의 말이다.
//   이 판의 말은 **차오름**이다.
// ⭐ 그리고 **자리도 갈랐다** — 빙판은 사거리 밖으로 **던져 깔고**(몸에서 70칸),
//   서리밭은 **발밑에 깔린다.** 상고대가 폐기되며 빈 「발밑 판」 자리가 이것이다
//   (규칙은 「발밑 판은 한 속성에 **하나까지**」이므로 하나는 놓을 수 있다).
//   ⚠️ **따라다니지 않는다** — 깔린 자리에 선다. 몸에 붙어 도는 것에는 바닥 진을
//     안 까는 규약과 안 부딪힌다.
//
// ── ⭐⭐ 이 칸의 정체 — **남을 위해 판을 깐다** ──────────────────────────
// 사용자가 **깨트리기와의 시너지**를 이유로 댔다. 그러면 이 판은 **혼자 완성되는
// 스킬이 아니다.** 빙 열하나에 그런 칸이 **하나도 없었다**(전부 자기가 끝낸다).
// ⇒ 비어 있던 축을 정면으로 메운다.
// ⚠️⚠️ **그래서 그림이 반드시 져야 하는 것은 「얼마나 얼었나」다.** 피해 수가
//   아니라 **누적**이 눈에 보여야 한다:
//     ㉠ **차오른다** — 적 발치부터 결정이 자라고, 색이 빠지고, 요동이 멎는다
//     ㉡ **뒤집힌다** — 문턱을 넘는 순간 **다른 그림**이 된다. 윤곽이 또렷해지고
//        **안에서 빛이 갇힌다**(가산). 「이제 치면 깨진다」가 화면의 말이 된다
//     ㉢ **판도 굳는다** — 오래 켜져 있을수록 가운데부터 두꺼워진다
//
// ── ⚠️ 얼리는 것이 초점이라 **피해 그림을 크게 안 그린다** ────────────────
// 터짐 · 사방으로 튀는 불티 · 큰 섬광을 쓰면 사용자 지시와 **정반대**가 된다.
// 이 판의 잉크는 **면과 결정**에 간다.
// ⚠️ 얌전하라는 뜻이 아니다 — 화려함은 **터짐이 아니라 차오름의 밀도**로 낸다.
//   2D→3D 여덟 조항 중 **면적을 안 늘리는 넷**이 여기 딱 맞는다:
//   ㉠ 면 쪼개기 · ㉢ 대기 원근 · ㉤ 밑동 흰 테 · ㉦ 떠 있는 조각.
//
// 면 = **눕는다**(ground). 항 넷 ─ 덩어리: 판 + **굳은 속심**(면이 쪼개진다) +
//   적마다 차오르는 결정 기둥 / 층: 판 세 겹 + 결정 면 셋 + **갇힌 빛** +
//   **굴절(어긋난 겹)** / 불티: 모여드는 서리 알갱이 + **자라는 끝의 밝은 점** +
//   뒤집히는 순간의 조각 / 잔상: 굳은 자국 + 서리 가지 + 빙결 도장
// ── ⭐⭐ 다섯 마디 ───────────────────────────────────────────────────────
// ⚠️⚠️ **「마디가 다섯」은 「스킬이 다섯 번 꺼졌다 켜진다」가 아니다.** 이건
//   **지속 장판**이라 판은 한 번 깔려 한 번 걷힌다 — 마디는 **판의 성격이
//   바뀌는 지점**이다.
//   시전 0.36  발밑 마법진 + **서리 실금**이 방사로 + **굳을 자리 예고**
//              (끝 반지름에 **고정된 테**가 서고 그 안이 채워진다)
//   생성 0.34  판이 **가지를 뻗어** 열린다([IZfern]) — 「커지는 원」이 아니다.
//              속심은 예고를 **이어받아** 이미 자리를 잡았고 테가 그 밖으로 벌어진다
//   발현 2.24  머문 놈이 **차오르고**(끝이 제일 밝다) · 문턱을 넘으면 **뒤집히고**
//              (껍질 + 갇힌 빛 + **굴절**) · 판이 굳는다(**면이 쪼개진다**)
//   소멸 0.58  판이 **가장자리부터 갈라진다** — **방사 금이 먼저, 동심 호가 나중**
//              (빙판은 테가 깨진다 — 다른 그림)
//   종료 0.48  굳은 자국이 서리 가지로 남았다가 김으로. **조각이 없다**
//   합 4.00 = 주기 ✓
//
// ── 🔴 인터넷에서 실물을 보고 고친 넷 (2026-08-29) ───────────────────────
// 사용자: 「스킬 만들다가 **레퍼런스 필요하면 크롬에 너가 검색해 가며** 하고
//   있어?」 ⇒ 아래 넷은 **글 설명이 아니라 실물·실코드**를 보고 고쳤다.
//   ⚠️ **베끼지 않았다** — 가져온 것은 **성질**(무엇이 먼저 오나 · 어디가 제일
//     밝나 · 몇 계열인가)뿐이다.
//   ㉠ **가지 친다**(atoptics 「Windscreen frost」 · Wikipedia 「Dendrite
//      (crystal)」) — 서리는 균일하게 안 번지고 **가지를 친다**. 핵이 드문드문할수록
//      **한 덩이가 크게** 자란다. ⇒ 생성이 [IZfern] 으로 열리고, 적 발치의 기둥을
//      고르게 안 흩고 **핵 둘에 몰았다**.
//   ㉡ **끝이 제일 밝다**(같은 글 — 「growth proceeds fastest at edges rather
//      than smooth planes」) ⇒ 기둥 끝마다 가산 점. **면적이 0 인데 밀도가 오른다**.
//   ㉢ **다 얼면 굴절 · 림 · 반투과가 같이 오른다**(robertrumney/frozen-shader-2D
//      의 `_FrozenAmount`) — 우리에겐 림과 반투과는 있었고 **굴절만 없었다**.
//      ⇒ 껍질 안쪽 윤곽을 **옆으로 밀어** 한 겹 더 그렸다.
//   ㉣ **깨짐은 방사 + 동심 두 계열**(forensicfield · SWGMAT 「Glass Fractures」)
//      — 방사가 먼저 나고 동심 호가 **나중에 가로지른다**. ⇒ 소멸에 동심 호 둘.
//   ⚠️ **안 가져온 것도 적는다** — 창 서리의 「완만한 곡선」은 **안 썼다**.
//     이 장의 **빙-1「곡선을 안 쓴다」**와 부딪히고, 곡선을 쓰면 결빙의 동심
//     타원과 화면에서 같은 물건이 된다. **실물이 그렇다고 규약을 깨지 않는다.**
const IZM_B = [.36, .34, 2.24, .58, .48];
const IZM_PER = 4.0;
/// 판 반지름 · 눕힘 · 결의 수(육각이라야 얼음이다).
const IZM_R = 62, IZM_SQ = LX3SQT, IZM_SIG = 6;
/// ⭐⭐⭐ **깔리는 자리 — 몸이 아니라 던진 곳**(2026-08-29 사용자 판정):
///   > 「서리밭 **캐릭터 주변이 아니라 사거리 있는 장판 스킬로** 변경해 줘」
/// ⚠️ 이것이 **바닥 진을 여는 열쇠**이기도 하다 — 규약이 「**몸에 붙어 따라다니는
///   지속 스킬에는 바닥 진을 안 깐다**」인데, 이제 **자리가 정해진 것**이 된다.
///   가르는 시험도 통과한다 — 「이 진 한가운데서 무엇이 솟는가?」에
///   **얼음이 차오른다**로 답한다.
const IZM_AT = [26, -72];
/// 씨앗이 날아가는 데 걸리는 몫(생성의 비) · 꼬리 반짝이 수 · 씨앗 반지름(238칸).
/// ⚠️ **날아가는 동안이 비면 「그냥 저기서 깔렸다」가 된다**(㉰ 머리·몸통·꼬리).
const IZM_FLY = .62, IZM_TRAIL = 5, IZM_SEED = 7;
/// ⭐⭐ **사다리의 축 = 「굳음」** — 판이 얼마나 굳고 얼마나 빨리 얼리나.
/// ⚠️⚠️ **면적을 싣는 축을 골랐다.** 빙추·채찍이 「가늘고 긴 것으로만」 자라
///   인접 레벨 화소차가 .001~.004 에 그친 전례가 있다(실측). 여기서는 **굳은
///   속심이 면으로 넓어진다** — 판 반지름의 0 → 1.00 이라 화소가 실제로 켜진다.
/// ⚠️ 그래도 「같은 판을 더 크게」가 아니다 — **판 반지름은 다섯 칸이 같고**,
///   그 안에서 **굳은 넓이**만 는다. 늘어나는 것은 크기가 아니라 **상태**다.
/// ⚠️⚠️ **이 표는 「넓이」다 — 반지름이 아니다.** 그리는 쪽이 `√` 를 씌운다
///   (`sr = R × √SOLID × sp`). 반지름에 그대로 곱하면 넓이가 **굳음의 제곱**이
///   되어 아랫칸(L1↔L2)이 윗칸보다 얇아진다 — 실제로 그렇게 났었다.
const IZM_SOLID = [0, .42, .62, .80, 1.00];
/// 초당 차는 몫(238칸 기준 아님 — [IZF_ON] 1.5 까지의 비율).
/// ⚠️ L1 이 1.5/0.85 = **1.76초**라 발현 2.24 안에서 **간신히** 언다 — 「겨우
///   얼렸다」가 L1 의 그림이고, 레벨이 오르면 **빨리 얼어 남는 시간이 는다**.
const IZM_RATE = [.72, 1.02, 1.40, 1.80, 2.30];
/// L3~ — 판을 벗어나도 **안 녹는다**(표식이 남아 깨트리기가 나중에 부른다).
const IZM_KEEP = [0, 0, 1, 1, 1];
/// L4~ — 다 언 놈에게서 **냉기가 곁으로 번진다**(시너지가 판 밖으로 나간다).
const IZM_SPREAD = [0, 0, 0, 1, 1];
/// L5 각성 — 빙결 도장이 **두 배**로 커진다(깨트리기가 멀리서도 고른다).
const IZM_SEAL = [1, 1, 1, 1, 2];
/// 곁으로 번지는 거리(238칸).
const IZM_NEAR = 46;
/// 적 넷 — **셋은 판 안, 하나는 판 밖**이다(경계를 읽어 주는 자리).
/// ⚠️ 안의 셋은 **중심에서 거리가 다르다** — 가까울수록 빨리 얼어야 「차오른다」가
///   한 화면에 **세 단계로** 같이 보인다(하나만 있으면 단계가 안 읽힌다).
const IZM_FOE = [[-16, -22, 9], [30, -40, 10], [-40, 34, 9], [78, -66, 9]];
/// 적 발치에서 자라는 결정 기둥 수 · 그 최대 높이(238칸).
const IZM_COL = 5, IZM_COLH = 15;
/// 판 위로 떠 있는 조각 수(㉦ — 「지금 막 일어났다」).
const IZM_FLOAT = 7;

// ══════════════════════════════════════════════════════════════════════════
// ⑤ 얼음창 `icepike` — **머리 위에서 멀리까지 일자로 박힌다**   (2026-08-29)
// ══════════════════════════════════════════════════════════════════════════
// 사용자: 「**얼음으로 된 엄청 크고 멋진 창** 같은 거 디자인되려나? 그런 게
//   **캐릭터 머리 위에서부터 멀리까지 일자로 팍 하고 박히는** 스킬 있으면
//   괜찮을 거 같은데」 (레퍼런스 = 「칼리아흐의 얼음 창」 외형 주문서)
// ⚠️ 레퍼런스는 **무기 외형 시트**이지 스킬 이펙트가 아니다 — **성질만** 가져왔다.
//
// ── 동사는 **박는다**. 한 낱말이고 빙에 없던 것이다 ──────────────────────
//   서 있는 동사: 밀다(파문·빙판) · 막다(빙벽) · 굳히다(결빙) · 때리다(우박) ·
//   깨다(깨뜨리기) · 잇다(엉김) · 쏘다(서리탄) · 휘두르다(채찍) · 뚫다(빙추) ·
//   얼린다(서리밭)  ⇒ **박다**는 하나도 안 쓰였다.
//   ⚠️ 「뚫다」(빙추)와 다르다 — 뚫는 것은 **지나가는 것**이고 박는 것은
//     **멈춰 남는 것**이다. 그 차이가 소멸 마디에 그대로 그려진다.
//
// ── ⚠️⚠️ 겹침 검사 — 먼저 했다 ──────────────────────────────────────────
//            빙추                     얼음창
//   축       **개수**(줄기가 는다)    **하나의 크기**
//   박자     계속 나간다              **한 방**
//   실루엣   가는 줄기 여럿           **큰 덩어리 하나 + 긴 자루**
//   ⇒ **「크다」가 이 칸의 전부다.** 크기로 안 갈리면 빙추와 같은 물건이 된다.
//   ⚠️ 염의 **불창**(`flarepike`)과는 동작이 같다(꽂힌다) — 읽어 보고 갈랐다
//     (`docs/vfx/mockup-char-fire.js` 의 성장표. **고치지 않았다**):
//       불창   = **적 자리**에 마법진이 서고 **하늘에서 둘**이 내리꽂히며,
//                「마법진에 **박힌 만큼 창이 사라진다**」
//       얼음창 = **캐릭터 머리 위**에서 나 **앞으로 멀리** 일자로 가고,
//                **하나**이며, 꽂힌 뒤 **남는다**(소멸 마디가 그 자리다)
//     ⇒ 나는 자리 · 가는 쪽 · 개수 · 남느냐가 다 다르다.
//
// ── 🔴 레퍼런스에서 뽑은 성질 (그림 여섯 + 실물 셋) ──────────────────────
//   ㉠ **자루가 극단적으로 가늘다** — 첫인상이 「길다」. 굵게 그리면 그림이 안 난다
//   ㉡ **무게가 아래쪽 3분의 1** — 큰 덩어리가 거기 하나. **창끝은 오히려 작다**
//      ⭐ 이것이 원근과 저절로 맞는다 — 가까운 밑동이 크고 **먼 끝이 작다**
//        (2D→3D ㉡ 「앞은 크고 뒤는 작다」). 억지로 안 만들어도 실물이 그렇다
//   ㉢ 그 덩어리는 **육각 눈꽃 + 사방 가시**(칼받침 자리)
//   ㉣ 날에 **격자 무늬**가 새겨지고 **속이 비친다** — 면 쪼개기(㉠)가 딱 맞는 자리
//   ㉤ **창끝은 별처럼 여러 갈래**로 터진 가시 뭉치다(뾰족한 하나가 아니다)
//   ㉥ 청백 단색인데 **테두리가 안보다 밝다**(림) ⇒ 가산은 **테와 결**에
//   ── 실물(인터넷) 셋 ──
//   ㉦ **축을 따라 기포가 기둥으로 갇힌다** — 빨리 얼면 공기가 안쪽에 갇혀
//      「고드름 축을 따라 늘어선 기포 기둥」이 된다(EPOD 「Air Bubble Formation
//      in Icicles」). ⇒ 날 한가운데에 **밝은 점의 줄**. **면적이 0 인 밀도**다
//   ㉧ **불순물이 갈매기 무늬 띠**로 모인다(arXiv 「Pattern of inclusions inside
//      rippled icicles」). ⇒ 날의 무늬를 **갈매기 띠**로 새긴다
//   ㉨ **길이가 먼저 자라고 폭은 천천히** 자란다(고드름의 성장 규칙).
//      ⇒ **생성 마디의 박자가 여기서 나온다** — 자루가 먼저 뻗고 나중에 굵어진다
//
// ── ⭐⭐ 다섯 마디 ───────────────────────────────────────────────────────
// ⚠️ **여기는 시전을 안 걷는다.** [IZ시전표] 의 오른쪽 칸이다 — 「한 방짜리 ·
//   느리고 큰 것」이고, 머리 위 구 → 아공간은 **사용자가 직접 지시한** 예비
//   동작이다. 서릿발에서 시전을 걷었다고 이쪽까지 걷으면 그 지시를 어긴다.
//   시전 0.34  **머리 위**에 구가 서고 별빛이 모여든다(마법진은 없다)
//   생성 0.72  **날부터** 길게 뽑혀 나온다 — 길이가 먼저, 폭이 나중(㉨)
//   발현 0.90  🔴 **든다 → 뺀다 → 멈춤 → 팍 → 여운**(안이 넷이다. 아래 참조)
//   소멸 0.60  **꽂힌 채 남는다** — 🔴 **끝이 잘린 채**다(위 「꽂혔다는 가려졌다」).
