// ══════════════════════════════════════════════════════════════════════════
// 🔴🔴🔴 **「꽂혔다」는 「가려졌다」로만 낸다**            (2026-08-29 사용자)
//
// 사용자 원문:
//   > 「**'얼음창'의 경우에는 꽂히면 바닥에 꽂히니까 창의 끝부분이 살짝 잘리듯이
//   >  없어져야 되잖아.** 근데 **그냥 창만 날아가니까 어딘가에 꽂혔다는 느낌이
//   >  없어**. 혹시 무슨 말인지 아나」
//
// ⭐⭐ **위에서 내려다보는 2D 에서 「박혔다」를 내는 방법은 하나뿐이다 —
//   바닥에 들어간 부분이 안 보이는 것.** 앞 판은 창 **전체**가 그대로 보였다
//   ⇒ 「바닥에 **놓인** 것」으로 읽힌다.
// ⭐ 규칙은 염의 **불창**([FQpike] 의 `cut`)이 이미 세웠다 — 「**물체가 면을
//   지나는 순간부터 면 아래는 안 그린다**」. 그쪽은 마법진이 면이고, 이쪽은
//   **꽂힌 점을 지나는 바닥선**이 면이다.
//
// ── 넷을 **같이** 놓는다(하나만 놓으면 안 읽힌다) ────────────────────────
//   ㉠ **끝이 잘린다** — 날 앞부분이 바닥선 아래로 사라진다([IZK_DEEP]).
//      ⚠️ 「투명해짐」이 아니라 **잘림**이다 — 경계가 또렷해야 「들어갔다」다.
//   ㉡ **밑동에 얇고 밝은 테**([IZK_LIP]) — 「여기가 지면이다」를 말한다.
//      🔴 **넷 중 이 한 항이 제일 크다.**
//   ㉢ **발치 그림자**([IZK_SHL]) — 없으면 공중에 떠 있는 것과 안 갈린다.
//   ㉣ **꽂힌 자리의 흐트러짐** — 밀려난 부스러기([IZK_GRIT]). 금·조각은 이미 있다.
//
// ── ⚠️ 함정 넷 ───────────────────────────────────────────────────────────
//   ㉠ **잘리는 양이 레벨을 탄다** — 그래야 「더 깊이 박힌다」가 화면에 보인다.
//   ㉡ **날아가는 동안은 안 잘린다.** 잘림은 **닿는 순간부터**이고,
//      🔴 **닿는 프레임과 잘리기 시작하는 프레임의 차 = 0** 이라야 한다
//      ⇒ [IZK_SINK0] 가 그것이다 — **닿는 그 프레임에 이미 절반 넘게** 들어가
//        있다. 0 에서 시작하면 한 프레임 늦는다(이 저장소의 `v <= 0` 결함군).
//   ㉢ **기울어진 창이라 잘리는 선도 기울어진다** — 창 축이 아니라 **바닥선**
//      (가로선)을 따라 자른다. ⇒ `ctx.clip` 한 번으로 낸다(획마다 자르면
//      [IZpike] 의 항 여덟을 다 고쳐야 하고 가산 패스가 새 나간다).
//   ㉣ **흔들려도 잘린 자리는 안 움직인다** — 흔들림의 축을 손잡이에서
//      **꽂힌 점**으로 옮겼다. 박힌 점이 고정이고 창의 **위쪽만** 흔들린다.
// ══════════════════════════════════════════════════════════════════════════
/// 🔴 **박힌 깊이** — 창 길이에서 **바닥선 아래로 들어가 안 보이는 몫**.
/// ⭐ 레벨을 탄다(㉠) — 잘린 길이 자체가 「얼마나 깊이 박혔나」다.
/// ⚠️ 그래도 **보이는 길이는 다섯 칸 다 늘어난다** — 창이 [IZK_SIZE] 로 더
///   길어지기 때문이다(재서 확인했다: 보이는 길이 70.2 → 81.0칸).
const IZK_DEEP = [.10, .14, .18, .22, .27];
/// 박히는 데 걸리는 시간(s) · 🔴 **닿는 그 프레임에 이미 들어가 있는 몫**.
/// ⚠️ `IZK_SINK0 = 0` 이면 「닿았는데 아직 안 잘린 프레임」이 하나 생긴다.
const IZK_SINKT = .07, IZK_SINK0 = .58;
/// 밑동 흰 테 — **그 자리 창 반폭의 배수** + **밀려 솟은 테 두께**(238칸).
/// ⚠️⚠️ **배수만으로는 L1 에서 안 보인다** — 재 보니 L1 의 바닥선 창 반폭이
///   **1.05칸**이라 배수 2.7 로는 테가 반지름 2.8칸이었다(같은 자리의 갈라진
///   테가 13칸이라 통째로 묻혔다). 뚫린 구멍의 테는 **구멍보다 두껍다** —
///   그 두께가 [IZK_LIP0] 이고, 그래야 L1 7.0 → L5 24.3칸으로 선다.
const IZK_LIP = 1.9, IZK_LIP0 = 5.0;
/// 발치 그림자 — 보이는 자루의 몇 할까지 눕나 · 밑동 반폭 · 먼 끝 반폭(238칸).
/// ⚠️ **면으로 칠한다.** 검정을 가산으로 칠하면 아무 일도 안 일어난다.
/// ⚠️ **바탕이 검은 칸이라 그림자는 절대 밝기로 거의 안 남는다**(잰 값: 200×200
///   한 프레임에 「바탕보다 어두운 화소」 8~24개). 힘을 쓰는 자리는 **훑은 자국
///   위**와 **뚫린 구멍 안**이다 — 그래서 자국보다 **뒤에** 그리고, 구멍의
///   어둠([plantLip] 의 `hr`)을 따로 둔다.
const IZK_SHL = .78, IZK_SHW0 = 2.2, IZK_SHW1 = 6.5;
/// 밀려난 부스러기 수 — 박히는 순간 튀어나와 **그 자리에 남는다**.
const IZK_GRIT = 7;

/// ⭐ **창 한 자루의 정본** — 밑동 `(x0,y0)` 에서 **끝** `(x1,y1)` 까지.
/// ⚠️⚠️ 모양을 **끝에서부터** 잰다(`v` = 끝에서의 몫). 까닭이 둘이다:
///   ① 사용자가 「**쇠붙이 쪽부터** 길게 뽑아져 나온다」고 했다 — 끝이 먼저 나고
///      자루가 따라 나오려면 자가 **끝에 붙어** 있어야 한다.
///   ② 「앞은 크고 뒤는 작다」(2D→3D ㉡)를 **폭으로** 낸다 — 실물 창이 그렇다.
/// 🔴 **앞 판은 「치실」이었다**(사용자 판정: 「창 디자인의 끝이 **치실처럼**
///   되어 있음. 치실이 아니라 **날카로운 쇠붙이**여야 함」). 원인 셋을 고쳤다:
///   ㉠ **날이 아예 없었다** — 자루가 처음부터 끝까지 **같은 굵기**였다
///     ⇒ 자루의 **3.4배** 넓은 날을 넣었다(레퍼런스 성질 ㉣ 을 빠뜨렸던 자리)
///   ㉡ **끝이 작은 가시 별**이라 「찌른다」가 안 읽혔다 ⇒ **한 점으로 모이는
///     뾰족한 끝**으로 바꾸고 가시는 그 **둘레**에 붙였다
///   ㉢ **자루가 안 가늘어졌다** ⇒ 뿌리가 굵고 끝으로 갈수록 가늘다
/// 창의 **반폭 옆모습** — `v` = **끝에서의 몫**(0 = 창끝, 1 = 밑동).
/// 끝(0) 뾰족 → 날(넓다) → 목(좁다) → 자루(밑동으로 굵어진다)
/// ⚠️⚠️ **[IZpike] 와 밑동 흰 테가 이 한 자를 나눠 쓴다.** 따로 적으면 그날로
///   테가 창을 안 좇는다(테 크기는 「바닥선에서의 창 반폭」에서 나온다).
function IZpikeW(v, sz, SC) {
  const HAFT = IZK_HAFT * sz * SC, BLW = IZK_BLW * sz * SC;
  // 🔴 **날 — 하나의 점으로 매끈하게 모인다.** ⚠️ 중간이 볼록하면 뚱뚱해 보인다 —
  //   앞 판은 `sin` 곡선이라 배가 불렀다. 이제 **거의 직선**(지수 1.10)이라
  //   밑동에서 끝까지 한 번에 좁아진다. 끝은 여전히 **점 하나**다.
  if (v < IZK_BL1) return BLW * Math.pow(IZcl(v / IZK_BL1), 1.10);
  // 날 뒤 — 목이 **바로** 자루 굵기로 떨어진다(화살촉이 자루에 물린 꼴)
  if (v < IZK_GD) return BLW - (BLW - HAFT) * IZss((v - IZK_BL1) / (IZK_GD - IZK_BL1));
  // 자루 — **아주 가늘고 거의 일정하다**(실처럼). 밑동만 살짝 굵다
  return HAFT * (.86 + .34 * (v - IZK_GD) / (1 - IZK_GD));
}

function IZpike(c, x0, y0, x1, y1, sz, SC, a, seed, o) {
  const op = o || {};
  const em = op.em == null ? 1 : IZcl(op.em);     // 얼마나 뽑혀 나왔나(끝부터)
  if (em <= .01 || a <= .01) return;
  const dx = x1 - x0, dy = y1 - y0, L = Math.hypot(dx, dy);
  if (!(L > 2)) return;
  const ux = dx / L, uy = dy / L, px = -uy, py = ux;
  /// `v` = **끝에서의 몫**(0 = 창끝, 1 = 밑동). 자리와 반폭.
  const P = (v, w) => [x1 - ux * L * v + px * w, y1 - uy * L * v + py * w];
  const HAFT = IZK_HAFT * sz * SC, BLW = IZK_BLW * sz * SC;
  /// 반폭 옆모습 — **정본은 [IZpikeW]** 다(밑동 흰 테가 같은 자를 쓴다).
  const wOf = (v) => IZpikeW(v, sz, SC);
  const T = toneOf("frost");
  const vMax = em;
  /// 옆모습을 폴리곤으로 — 한쪽을 훑고 반대쪽을 되훑는다.
  // ⚠️ **끝 쪽을 촘촘히** 뜬다(`i²`) — 고르게 뜨면 첫 토막이 굵어 끝이 뭉툭해진다
  const N = 22, sideA = [], sideB = [];
  for (let i = 0; i <= N; i++) {
    const v = vMax * Math.pow(i / N, 1.7), w = wOf(v);
    sideA.push(P(v, w)); sideB.push(P(v, -w));
  }
  const BODY = sideA.concat(sideB.reverse());
  // ① 몸 — **속이 비친다**(㉣). 옅은 면 + 밝은 테
  fillPoly(c, BODY, A(mixHex(T[0], T[1], .48), .60 * a));
  IBrim(c, BODY, "snow", .76 * a, 1.0 * SC * Math.max(.6, sz * .7));
  // ② 🔴🔴 **축 방향 금을 걷었다** — 그것이 마름모 금과 만나 **격자**가 됐다.
  // 사용자: 「**피해 범위를 누가 파리채처럼 그리드 형태로** 저런 식으로 구현해」
  // ⚠️⚠️ **가로줄과 세로줄이 만나는 곳이 한 군데라도 있으면 격자다.**
  //   두께는 **날의 앞날 두 줄**(아래 ⑤)이 이미 낸다 — 축 금은 없어도 된다.
  //   ⇒ 자루에는 **금이 하나도 없다**(가늘고 매끈한 쇠붙이다).
  // ③ 🔴 **금은 날에만, 길이 방향으로.** 날이 가늘어졌으니 **가운데 심 한 줄**이면
  //   충분하다. ⚠️ 가로지르는 금(갈매기 · 마름모)을 걷었다 — 앞날 두 줄과 만나
  //   **격자**가 될 수 있던 유일한 자리였다. **가로줄이 이제 한 줄도 없다.**
  {
    const v0 = IZK_BL1 * .12, v1 = Math.min(vMax, IZK_BL1 * .94);
    if (v1 > v0) IBline(c, [P(v0, 0), P(v1, 0)], .7 * SC * sz, "frost", .44 * a, 0);
  }
  // ④ ㉦ **축을 따라 갇힌 기포** — 가산 점의 줄. 면적이 0 인 밀도다
  gAdd(c, (cc) => { for (let j = 0; j < IZK_BUB; j++) {
    const v = .10 + .80 * (j + .5) / IZK_BUB;
    if (v > vMax) break;
    const q = P(v, (hash(seed + j * 3.7) - .5) * wOf(v) * .7);
    IBspark(cc, q[0], q[1], (1.4 + 1.5 * hash(seed + j * 5.1)) * SC * sz, "snow", .60 * a, 0);
  } });
  // ⑤ 🔴🔴 **끝은 점 하나다.** 가시를 사방으로 뻗지 않는다 — 그게 곤봉이다.
  // ⚠️ 밝히는 것은 **날의 앞날 두 줄**이다. 날카로움은 섬광이 아니라 **모서리**다.
  // ⚠️⚠️ **끝에 둥근 것을 하나도 두지 않는다.** 앞 판은 창끝에 [IBspark] 를
  //   찍고 앞날 두 줄을 **끝까지** 끌어 둥근 뭉치로 닫혔다 — 사용자가 「**둥근
  //   주걱**」이라 한 자리다. ⇒ 앞날은 **끝 못 미쳐 끊고**, 섬광은 **안 찍는다**.
  {
    const vE = Math.min(vMax, IZK_BL1 * .96), v0 = IZK_BL1 * .10;
    const NE = 9, eA = [], eB = [];
    for (let i = 0; i <= NE; i++) { const v = v0 + (vE - v0) * i / NE, w = wOf(v);
      eA.push(P(v, w)); eB.push(P(v, -w)); }
    IBline(c, eA, .8 * SC * sz, "snow", .76 * a, 0);
    IBline(c, eB, .8 * SC * sz, "snow", .76 * a, 0);
  }
  // ⑤-② 🔴 **미늘** — 날 밑동에서 **뒤쪽으로** 젖혀진 두 갈래. 화살촉의 표다.
  // ⚠️ `v` 가 커지는 쪽이 **뒤**다(밑동 쪽). 앞으로 벌리면 **작살**이 된다.
  if (vMax > IZK_BL1) {
    const vb = IZK_BL1, vt = Math.min(vMax, IZK_BL1 + IZK_FLUEV);
    const fw = IZK_FLUE * sz * SC;
    IBline(c, [P(vb, wOf(vb) * .9), P(vt, fw)], .9 * SC * sz, "frost", .70 * a, 0);
    IBline(c, [P(vb, -wOf(vb) * .9), P(vt, -fw)], .9 * SC * sz, "frost", .70 * a, 0);
    IBline(c, [P(vt, fw), P(vt - IZK_FLUEV * .55, wOf(vb) * .5)], .8 * SC * sz, "frost", .52 * a, 0);
    IBline(c, [P(vt, -fw), P(vt - IZK_FLUEV * .55, -wOf(vb) * .5)], .8 * SC * sz, "frost", .52 * a, 0);
  }
  // ⑥ 🔴 **자루 밑동의 작은 가시 뭉치** — 석장 밑동. **찌르는 데가 아니다**
  if (vMax > .94) {
    const Bt = P(1, 0);
    for (let j = 0; j < IZK_BUTT; j++) {
      const a0 = (j + .5) / IZK_BUTT * TAU + seed;
      const rr = IZK_BUTTR * sz * SC * (.8 + .5 * hash(seed + j * 2.3));
      IBline(c, [[Bt[0], Bt[1]], [Bt[0] + Math.cos(a0) * rr, Bt[1] + Math.sin(a0) * rr * .8]],
        .8 * SC * sz, "frost", .52 * a, 0);
    }
  }
  // ⑥ ㉢ **칼받침** — 눈꽃 + 사방 가시. 실루엣을 만드는 덩어리다
  if (vMax > IZK_GD) {
    const G = P(IZK_GD, 0), gr = IZK_GUARD * sz * SC, open = op.open || 0;
    for (let j = 0; j < IZK_BARB; j++) {
      const a0 = (j + .5) / IZK_BARB * TAU + seed * .3;
      const rr = gr * (1.05 + .95 * open) * (.72 + .5 * hash(seed + j * 7.7));
      IBline(c, [[G[0], G[1]], [G[0] + Math.cos(a0) * rr, G[1] + Math.sin(a0) * rr * .74]],
        1.0 * SC * sz, "frost", (.50 + .30 * open) * a, 0);
    }
    fillPoly(c, IZpoly(G[0], G[1], gr * .82, 6, seed * .7, .78), A(mixHex(T[0], T[1], .54), .68 * a));
    IBflake(c, G[0], G[1], gr * 1.02, seed * .5, "snow", .80 * a, 1.0 * SC * sz, .78);
  }
}

Object.assign(FX, {

// ── ④ 서리밭 ──────────────────────────────────────────────────────────────
IZmire(c, t, dt, W, H, st) {
  const cx = W / 2, cy = H / 2, SC = Math.min(W, H) / 238;
  const F = IZfoes(st, SC, IZM_FOE);
  const u = saw(t, IZM_PER), tau = u * IZM_PER;
  if (IZwrap(st, u)) { for (const f of F) { f.pv = 0; f.frz = 0; } st.mcy = (st.mcy || 0) + 1; }
  // ── ⭐⭐⭐ **회차마다 다르다** — 사용자가 두 번 청한 「매 시전마다 다르게」 ──
  // ⚠️⚠️ **난수를 안 쓰는 것과 회차마다 다른 것은 다른 이야기다.** 씨앗에서
  //   파생하면 둘 다 된다 — `lib/ui/watch_deco.dart` 의 `_frac(i)` 가 본보기다
  //   (「같은 i 는 늘 같은 값」이면서 회차마다 다르다). 여기서는 [hash] 가 그 일을
  //   하므로 **`Math.random` 은 여전히 0 회**다.
  // 🔴🔴 **바꾸는 것은 「어느 쪽으로」뿐이다 — 「얼마나」는 한 값도 안 건드린다.**
  //   `SOLID`·`sr`·`solid`·판 반지름은 회차를 **안 탄다**. 그것이 레벨의 축이고,
  //   회차가 그 축을 흔들면 **사다리가 회차에 먹힌다**(바늘 숲·석벽이 그렇게 됐다).
  //   ⇒ 회차가 타는 것은 **판의 결 방향(`CROT`)**과 **가지 뻗는 각(`CFRN`)** 둘뿐.
  //   ⚠️ 둘 다 **순수 회전·씨앗**이라 칠하는 넓이가 **수학적으로 안 변한다**
  //     ([IZpoly] 는 `rot` 만 돌리고, [jagPoly] 의 `seed` 는 **안 건드렸다** —
  //     그 씨앗은 들쭉날쭉한 반지름을 바꿔 넓이를 몇 % 흔들기 때문이다).
  // ⚠️⚠️⚠️ **흔들 폭을 「결 한 칸」으로 묶는다.** 처음엔 온 바퀴(`× TAU`)로
  //   돌렸더니 회차 인접차가 **.0126~.0167** 이 나와 **레벨(.0080~.0149)을
  //   넘겼다** — 바늘 숲·석벽이 겪은 바로 그 역전이다(회차 > 레벨이면 다섯 칸을
  //   나란히 놔도 레벨이 안 읽힌다). 잰 뒤에 알았고, 자를 다시 잡았다.
  // ⭐ 묶는 자리가 **공짜로 정해져 있다** — 판은 12각, 가지는 육각이라
  //   `TAU/12`·`TAU/6` 을 넘겨 돌리면 **같은 그림으로 되돌아온다**. 곧 한 칸이
  //   「다르게 보이는 전부」이고, 그 안에서 흔드는 것이 낭비가 없다.
  const CY = st.mcy || 0;
  const CROT = hash(CY * 3.7 + .21) * (TAU / 12);   // 판의 결이 향한 쪽 — 12각 한 칸
  const CFRN = hash(CY * 5.3 + .07) * (TAU / 6);    // 가지가 뻗는 각 — 육각 한 칸
  const z = IZz(tau, IZM_PER, IZM_B[4]);
  const tp = tau * TAU / IZM_PER, th = tau * (TAU * 2 / 2.2) / IZM_PER;
  const wob = TAU * 2 * tau / IZM_PER;
  const B = IZbeat(tau, IZM_B);
  // ⭐⭐ 사다리 — 한 낱말은 **굳음**. 속도·유지·번짐·도장이 그 낱말에 딸려 온다.
  const SOLID = IZM_SOLID[LV - 1], RATE = IZM_RATE[LV - 1];
  const KEEP = IZM_KEEP[LV - 1], SPREAD = IZM_SPREAD[LV - 1];
  const SEALS = IZM_SEAL[LV - 1];
  const R = IZM_R * SC;
  // ── ⭐⭐⭐ **던져서 깔린다** — 판의 중심은 몸이 아니라 `IZM_AT` 다.
  const mx = cx + IZM_AT[0] * SC, my = cy + IZM_AT[1] * SC;
  /// 씨앗이 날아가는 진행 — **생성 마디의 앞 [IZM_FLY] 몫** 안에 닿는다.
  const seedU = B.inCast ? 0 : (B.inGrow ? IZcl(B.grow / IZM_FLY) : 1);

  // ── 판이 열린다 — 안에서 밖으로. 소멸에서는 **가장자리부터 갈라진다**
  // ⚠️ 판은 **씨앗이 닿은 뒤**에 열린다 — 날아가는 동안은 아직 아무것도 안 깔린다.
  const open = (B.inCast || seedU < 1) ? 0
    : (B.inGrow ? IZss(IZcl((B.grow - IZM_FLY) / (1 - IZM_FLY))) : 1);
  const crack = tau >= B.t2 ? IZseg(tau, B.t2, B.t3) : 0;
  /// 굳은 속심의 진행 — 발현 동안 **가운데부터** 차오른다. 오래 켜져 있을수록 두껍다.
  // ⚠️⚠️ **굳음은 발현에서만 사는 것이 아니다.** 처음엔 발현 마디에만 그렸더니
  //   레벨 인접차가 **.0009~.0037** 에 그쳤다 — 위상 다섯 중 **하나에만** 차이가
  //   있어 나머지 넷이 그 차이를 희석했기 때문이다(빙벽은 판 수가 생성부터
  //   달라 다섯 위상 내내 갈렸다). 그리고 그림으로도 이쪽이 맞다 — **굳은
  //   바닥은 판이 꺼진다고 즉시 녹지 않는다.** 갈라질 뿐 자리에 남는다.
  //   ⇒ 생성에서 **미리 얼기 시작**하고, 소멸·종료까지 **남는다**.
  /// 굳음의 **시간축** — 「지금 얼마나 굳었나」. 레벨(`SOLID`)과는 따로 산다.
  // ⚠️⚠️ **생성 몫을 「0 → .38」에서 「.55 → .78」로 바꿨다** — 견줌 계량이
  //   근거다. 생성 마디의 레벨 인접차가 **.0011~.0026** 이라 사실상 **레벨을
  //   안 읽고** 있었다(고친 뒤 .0041~.0053).
  //   같은 자로 잰 빙벽은 그 마디가 **.0129~.0262** 인데, 까닭은 빙벽이
  //   **판 수가 생성부터 다르기** 때문이다 — 「세우는 과정」 자체가 레벨이다.
  //   ⇒ 서리밭의 대응물은 **「속심이 판보다 먼저 굳는다」**이다. 판이 안에서
  //     밖으로 열리는 스킬이니 **속심이 이미 자리를 잡고 그 둘레로 열리는** 것이
  //     그림으로도 맞다. 알파를 올린 것이 아니라 **사건을 앞당겼다.**
  // ⚠️⚠️ **생성이 .55 에서 시작한다** — 시전의 예고가 끝난 자리(`pf × .55`)를
  //   그대로 이어받는다. 0 에서 다시 자라면 마디 경계에서 그림이 **줄었다가**
  //   커지고, 그러면 예고가 거짓말이 된다.
  const sp = (B.inCast || seedU < 1) ? 0
    : B.inGrow ? .55 + .23 * IZss(IZcl((B.grow - IZM_FLY) / (1 - IZM_FLY)))
    : B.inHit ? .78 + .22 * IZss(B.hit)
    : B.inFade ? 1 - crack * .30
    : 1 - .45 * IZss(B.rest);
  /// ⭐⭐⭐ **굳은 반지름 = √(굳음)** — 그래야 **넓이가 굳음에 비례**한다.
  // ⚠️⚠️ 앞 판은 반지름에 `SOLID` 를 그대로 곱했다. 그러면 **넓이가 굳음의
  //   제곱**이라, 사다리의 아랫칸(L1↔L2)이 윗칸보다 **얇아진다** — 실제로 그
  //   칸이 제일 얇게(.0042) 나왔다. 축이 「굳은 **넓이**」인데 자란 것은
  //   반지름이었다. ⇒ √ 를 씌워 **인접 넓이차가 ΔSOLID 에 비례**하게 만든다.
  //   ⚠️ 판 반지름은 여전히 다섯 칸이 **같다** — 늘어나는 것은 굳은 몫뿐이다.
  const solid = Math.sqrt(SOLID) * sp;

  // ── ⭐⭐ 차오른다 — **머문 시간이 값이다** ────────────────────────────────
  // ⚠️ 판 안에 선 놈만 찬다. 밖에 선 넷째는 **끝내 안 언다** — 그 하나가 경계를 말한다.
  for (let i = 0; i < F.length; i++) {
    const f = F[i];
    const d = Math.hypot(f.ux - IZM_AT[0], f.uy - IZM_AT[1]);
    const inside = d < IZM_R;
    if (B.inHit && inside) {
      // ⭐ 가운데에 가까울수록 빨리 언다 — 한 화면에 **세 단계**가 같이 보인다
      IZchill(f, dt * RATE * (1.20 - .55 * (d / IZM_R)));
      if (!st.ev["frz" + i] && f.frz) st.ev["frz" + i] = tau;   // 뒤집힌 시각
    }
    // ⭐⭐ L3~ — 판이 꺼져도 **안 풀린다**. L1·L2 는 풀린다.
    // ⚠️⚠️ [IZthaw] 만 부르면 **아무 일도 안 일어난다** — 그 함수는 「언 놈은
    //   안 녹는다」가 계약이라(`if (!f.frz)`) 이미 얼어붙은 놈에게는 무효다.
    //   ⇒ L1·L2 는 **빙결 자체를 푼다.** 이것이 L2↔L3 을 가르는 사건이고,
    //     소멸·종료 **두 마디에 걸쳐** 보인다(그래서 사다리가 한 위상에만
    //     갇히지 않는다 — 이 칸이 처음에 .0012 로 나온 원인이 그것이었다).
    if (!KEEP && !B.inHit && !B.inCast && !B.inGrow) {
      f.frz = 0;
      f.pv = Math.max(0, f.pv - dt * 2.2);
    }
    f.hit = Math.max(0, f.hit - dt * 5);
  }
  // ⭐ L4~ — 다 언 놈에게서 **냉기가 곁으로 번진다**(시너지가 판 밖으로 나간다)
  if (SPREAD && B.inHit) for (const a of F) {
    if (!a.frz) continue;
    for (const b of F) {
      if (b === a || b.frz) continue;
      if (Math.hypot(b.ux - a.ux, b.uy - a.uy) > IZM_NEAR) continue;
      IZchill(b, dt * RATE * .55);
    }
  }
  IZstand(F, SC, wob, z);

  // ══ 그리기 ═══════════════════════════════════════════════════════════════
  // ㉠ 시전 — 발밑 마법진 + **서리 실금**이 방사로 뻗는다. 「여기가 언다」
  if (B.inCast) {
    IZcastFx(c, cx, cy, B.cast, SC, .90, 23.7);
    const g = IZss(B.cast);
    // ⭐⭐⭐ **굳을 자리 예고** — 시전이 레벨을 읽는 유일한 항이다.
    // ⚠️⚠️ 같은 자로 여섯을 재 보니 **빙 여섯 전부** 시전 마디의 레벨 인접차가
    //   **.0000~.0015** 였다(빙벽조차 .0008~.0015). 곧 「레벨을 올렸는데 시전은
    //   한 화소도 안 바뀐다」가 이 장의 **공통 결함**이다. 이 칸에서 먼저 메운다.
    // ⚠️ 예고는 **판이 아니다** — 테도 살도 안 그린다. 굳을 넓이만 미리 앉힌다.
    //   같은 √ 를 쓰므로 예고의 **넓이가 곧 레벨**이고, 발현에서 그 자리가
    //   그대로 굳는다(예고가 거짓말을 안 한다).
    if (SOLID > .02) {
      // ⚠️ 테는 **끝 반지름에 고정**이고 채움만 자란다 — 그것이 예고의 문법이다
      //   (「여기까지 굳는다」가 먼저 서고, 채워지는 것이 진행이다).
      const pf = R * Math.sqrt(SOLID);
      const T0 = toneOf("frost");
      IBrim(c, jagPoly(cx, cy, pf, 12, 4.3, 1.05, IZM_SQ), "frost", .46 * g * z, 1.0 * SC);
      fillPoly(c, jagPoly(cx, cy, pf * .55 * g, 12, 4.3, 1.05, IZM_SQ),
        A(mixHex(T0[0], T0[1], .34), .34 * g * z));
    }
    // 방사로 뻗는 서리 실금 — **굳을수록 촘촘하고 멀리 간다**
    const NL = 7 + Math.round(SOLID * 7);
    for (let j = 0; j < NL; j++) {
      const a0 = (j + .5) / NL * TAU + 1.1 + CROT;
      const r0 = R * (.30 + .60 * g) * (.7 + .5 * hash(j * 3.7)) * (.86 + .26 * SOLID);
      IBline(c, [[cx, cy],
        [cx + Math.cos(a0) * r0, cy + Math.sin(a0) * r0 * IZM_SQ]],
        1.0 * SC, "frost", .46 * g * z, 0);
    }
    // ⭐⭐ **모여드는 서리 알갱이** — 밖에서 안으로. ⚠️ **가산이다.**
    //   염에서 「불씨가 모여든다」가 전부 채우기라 **시전 마디 0.0%** 가 난 사고가
    //   있었다. 「모여드는 것」은 **빛**이지 바닥이 아니다 — 이 칸은 바닥 판이라
    //   발현이 낮게 나오는 것이 맞지만, **시전까지 0 이면 그건 색종이다.**
    // ⚠️ 알갱이를 **크게** 잡는다(3.4~6.2칸) — 1.6칸으로는 화면에서 티끌이라
    //   「모여든다」가 안 읽힌다. 조각이라 면적은 여전히 작다.
    const NG = 12 + Math.round(SOLID * 8);
    gAdd(c, (cc) => { for (let j = 0; j < NG; j++) {
      const a0 = (j + .5) / NG * TAU + .35 + CROT;
      const rr2 = R * (1.25 - .95 * g) * (.75 + .45 * hash(j * 6.7));
      IBshard(cc, cx + Math.cos(a0) * rr2, cy + Math.sin(a0) * rr2 * IZM_SQ,
        (3.4 + 2.8 * hash(j * 2.3)) * SC, a0, "frost", g * .82 * z, .46);
      IBflake(cc, cx + Math.cos(a0) * rr2, cy + Math.sin(a0) * rr2 * IZM_SQ,
        (2.6 + 1.6 * hash(j * 8.1)) * SC, a0 * .5, "frost", g * .60 * z, .8 * SC, IZM_SQ);
    } });
  }

  // ── ㉡ 생성 앞머리 — 🔴 **씨앗이 날아간다.** ㉰ 머리·몸통·꼬리가 여기 선다
  // ⚠️⚠️ 사용자가 「**사거리 있는 장판**」이라 했다 ⇒ **날아가는 동안**이 있어야
  //   한다. 비면 「그냥 저기서 깔렸다」가 되어 사거리가 그림에 안 남는다.
  if (B.inGrow && seedU < 1) {
    const e = IZss(seedU);
    const sx2 = cx + (mx - cx) * e, sy2 = cy + (my - cy) * e - 22 * SC * Math.sin(Math.PI * e);
    // 꼬리 — **선이 아니라 반짝이**(이 파일의 규율)
    gAdd(c, (cc) => { for (let j = 1; j <= IZM_TRAIL; j++) {
      const q = IZcl(e - j * .10);
      const qx = cx + (mx - cx) * q, qy = cy + (my - cy) * q - 22 * SC * Math.sin(Math.PI * q);
      IBspark(cc, qx, qy, IZM_SEED * SC * (1 - j / (IZM_TRAIL + 1)) * .8, "frost",
        (1 - j / (IZM_TRAIL + 1)) * .70 * z, j);
    } });
    // 머리 — 육각 결정 하나. 몸통은 면 셋
    IZprism3(c, sx2, sy2 + IZM_SEED * SC, -Math.PI / 2, IZM_SEED * 1.8 * SC, IZM_SEED * .8 * SC,
      3.1, .92 * z, { far: .30, tip: .18 });
    IBflake(c, sx2, sy2, IZM_SEED * 1.25 * SC, e * 5.0, "snow", .86 * z, 1.0 * SC, 1);
    gAdd(c, (cc) => IBspark(cc, sx2, sy2, IZM_SEED * 1.5 * SC, "snow", .80 * z, 0));
    // 닿을 자리에 **낮은 그림자** — 「여기 깔린다」. 느린 장판이라 예고가 맞다
    IBroot(c, mx, my, R * .30 * e, "frost", .34 * e * z, IZM_SQ);
  }

  if (open > .02) {
    const rr = R * open;
    // ⭐⭐⭐ **생성 — 판은 「커지는 원」이 아니라 「뻗는 가지」로 열린다.**
    // 🔴 레퍼런스(atoptics 「Windscreen frost」 · Wikipedia 「Dendrite (crystal)」):
    //   서리는 면이 균일하게 번지는 것이 아니라 **가지를 친다**(dendritic).
    //   그리고 「핵이 드문드문할수록 한 덩이가 크게」 자란다. ⇒ 판이 열리는
    //   동안 **가지가 먼저 뻗고 그 사이가 나중에 메워지는** 것이 실물이다.
    // ⚠️⚠️ 계량이 같은 자리를 가리켰다 — **생성 마디의 레벨 인접차가
    //   .0012~.0029** 로 사실상 레벨을 안 읽고 있었다(견줌: 빙벽 .0129~.0262).
    //   속심만으로는 그 마디에 실을 잉크가 없다. ⇒ **가지 수와 뻗는 길이**를
    //   굳음에 실어 그 마디를 채운다 — 그림으로도 맞고 수로도 맞는 항이다.
    // ⚠️ 전부 **획**이라 칠하는 면적이 거의 안 는다(가지는 선이다).
    if (B.inGrow && SOLID > .02) {
      IZfern(c, mx, my, R * (.42 + .48 * Math.sqrt(SOLID)),
        3 + Math.round(SOLID * 7), IZss(B.grow), SC, .70 * z, CFRN, IZM_SQ);
    }
    // ㉧ **접지 발광** — 판이 바닥에 앉는다. 없으면 떠 있는 무늬가 된다
    IBroot(c, mx, my, rr * 1.06, "frost", .30 * z, IZM_SQ);
    // ⭐⭐ **굳은 속심** — 축(굳음)이 **면으로** 서는 자리. 여기가 레벨이다.
    // ⚠️ 가산 한 겹을 얹는다 — 얼음은 빛을 통과시키는 물건이라 굳은 자리가
    //   **밝아져야** 「두꺼워졌다」로 읽힌다(덮어 칠하면 한계가 그 색이다).
    if (solid > .02) {
      // ⚠️ **`rr` 가 아니라 `R` 로 잰다** — 속심은 판이 열리는 것과 **따로**
      //   굳는다. ⭐ 생성 동안에는 속심이 **테보다 밖에 있을 수 있다** — 그것이
      //   이 스킬의 그림이다: **속심이 먼저 굳어 있고, 판의 테가 그 밖으로
      //   벌어져 나간다**(「안에서 밖으로 열린다」의 실체). 반대로 그리면 테가
      //   속심을 끌고 가는 꼴이 되어 「굳는다」가 아니라 「커진다」가 된다.
      const sr = R * solid;
      const SP = jagPoly(mx, my, sr, 12, 4.3, 1.05, IZM_SQ);
      const T = toneOf("frost");
      // ══ 🔴🔴 **물을 걷었다** (2026-08-29 사용자 판정) ═══════════════════
      // > 「서리밭의 경우에도 **물 같은 게** 있던데 **물 말고 다른 거 안 되나?**
      //    **퀄리티 좀 올려 주면** 좋겠는데」
      // ⚠️⚠️ **원인이 이 세 줄이었고, 이 장이 스스로 금지해 둔 것이었다.**
      //   참고장 **빙-5**: 「얼어붙는 면을 파랗게 **채우면 물웅덩이**가 된다.
      //   그리고 채우면 그 순간 **장판(빙판)과 화면에서 겹친다**」
      //   ⇒ 매끈한 청색 면 한 장 + 그 위 시안 가산 = **정확히 물웅덩이**다.
      //     제 규칙을 제가 어겼다.
      // ⭐⭐ **면 하나를 결정 밭으로 바꾼다** — 마른 육각 조각이 바닥을 덮는다.
      //   넓이(=사다리의 축)는 그대로 산다: 조각 수를 **넓이에 비례**시킨다.
      //   ⇒ 축을 안 건드리면서 **물기가 사라지고 밀도가 오른다**(퀄리티).
      // ⚠️ 바탕은 **아주 옅게**만 깐다 — 아예 없으면 조각이 허공에 뜬다.
      fillPoly(c, SP, A(mixHex(T[0], T[1], .30), .22 * z));
      const NF = 5 + Math.round(38 * solid * solid);
      for (let j = 0; j < NF; j++) {
        const a0 = j * 2.39996 + 1.1;                       // 황금각 — 고르게 덮인다
        const d0 = sr * Math.sqrt((j + .5) / NF) * .96;
        const fx2 = mx + Math.cos(a0) * d0, fy2 = my + Math.sin(a0) * d0 * IZM_SQ;
        const fr = sr * (.15 + .10 * hash(j * 4.7)) * (1 - .35 * d0 / (sr + .001));
        const HX = IZpoly(fx2, fy2, fr, 6, j * .9, IZM_SQ);
        fillPoly(c, HX, A(mixHex(T[1], "#DCEFFF", .34), (.34 + .22 * hash(j * 8.3)) * z));
        IBrim(c, HX, "snow", .30 * z, .7 * SC);
      }
      // ⭐ 밝은 것은 **조각의 테와 겹치는 자리**에만 — 넓은 청색 겹을 안 쓴다
      gAdd(c, (cc) => { for (let j = 0; j < Math.min(NF, 14); j++) {
        const a0 = j * 2.39996 + 1.1;
        const d0 = sr * Math.sqrt((j + .5) / NF) * .96;
        IBspark(cc, mx + Math.cos(a0) * d0, my + Math.sin(a0) * d0 * IZM_SQ,
          sr * .12, "snow", .40 * z, a0);
      } });
      IBrim(c, SP, "snow", .58 * z, 1.2 * SC);
      // ⭐⭐ **면 쪼개기** — 굳은 속심이 **한 장이 아니라 켜켜이 언 판**이다.
      // 🔴 갈무리로 보니 L4·L5 에서 속심이 **평평한 덩어리**로 읽혔다 — 넓어지기만
      //   하고 안이 비어 있었다. 2D→3D 여덟 조항의 ㉠ 이 정확히 이 자리다.
      // ⚠️ 실물 얼음 셰이더도 같은 말을 한다 — 「**노멀 두 겹** + 이방성 노이즈를
      //   스페큘러로 lerp 하면 하이라이트가 도드라진다」(80.lv 「Ice Spikes VFX
      //   Production」). 우리에겐 셰이더가 없으니 **금 셋과 밝은 면 하나**로 낸다.
      // ⚠️ 금은 **획**, 밝은 면은 **작은 조각**이라 칠하는 면적이 거의 안 는다.
      for (let j = 0; j < 3; j++) {
        const b0 = .5 + CROT + j * 1.05, b1 = b0 + 2.1;
        IBline(c, [[mx + Math.cos(b0) * sr * .94, my + Math.sin(b0) * sr * .94 * IZM_SQ],
                   [mx + Math.cos(b1) * sr * .94, my + Math.sin(b1) * sr * .94 * IZM_SQ]],
          .9 * SC, "snow", .40 * z, 0);
      }
      // 쪼갠 면 하나만 **밝다** — 다 밝히면 흰 덩어리가 되고 쪼갠 뜻이 사라진다
      // ⚠️ **이 면만 회차를 안 탄다**(`CROT` 없음) — 넓은 밝은 면을 회차마다
      //   옮기면 그건 「결이 다르다」가 아니라 **넓이가 다르다**로 읽힌다.
      gAdd(c, (cc) => fillPoly(cc, [
        [mx + Math.cos(.5) * sr * .94, my + Math.sin(.5) * sr * .94 * IZM_SQ],
        [mx + Math.cos(2.6) * sr * .94, my + Math.sin(2.6) * sr * .94 * IZM_SQ],
        [mx + Math.cos(1.55) * sr * .34, my + Math.sin(1.55) * sr * .34 * IZM_SQ]],
        A("#DFF2FF", .16 * z)));
      // ㉦ **떠 있는 조각** — 굳은 자리 위에 뜬다. 「지금 막 굳었다」
      // ⚠️⚠️ **가산이다.** 눈금이 둘이라는 규약이 여기서 갈린다 — **바닥 판은
      //   면**이지만 **그 위에 뜬 것은 빛**이다. 조각을 덮어 칠하면 굳은 면과
      //   같은 층으로 뭉쳐 「뜬 것」이 아니라 「무늬」가 된다.
      gAdd(c, (cc) => { for (let j = 0; j < IZM_FLOAT; j++) {
        const a0 = (j + .5) / IZM_FLOAT * TAU + 2.3 + CROT;
        const ph = (tau / IZM_PER * 2 + hash(j * 5.1)) % 1;
        IBshard(cc, mx + Math.cos(a0) * sr * (.35 + .50 * hash(j * 7.7)),
          my + Math.sin(a0) * sr * (.35 + .50 * hash(j * 2.9)) * IZM_SQ - (3 + 7 * ph) * SC,
          (2.2 + 1.4 * hash(j * 9.3)) * SC, a0, "frost", (1 - ph) * .70 * z, .46);
      } });
    }
    // ── 판의 세 겹 — 바깥 12각 테(제일 밝다) · 안 6각 · 결정 살 여섯 ────────
    // ⚠️ **화살을 한 획도 안 그린다** — 방향은 빙판의 말이다.
    IBrim(c, IZpoly(mx, my, rr, 12, tp * .05 + CROT, IZM_SQ), "frost", .86 * z, 1.7 * SC);
    IBrim(c, IZpoly(mx, my, rr * .68, IZM_SIG, -tp * .04 + CROT, IZM_SQ), "frost", .56 * z, 1.2 * SC);
    // ⭐ **굳은 만큼 테가 두꺼워진다** — 축(굳음)이 판이 서 있는 **네 마디 내내**
    //   보이게 하는 항이다. ⚠️ 굳은 속심은 발현에 몰려 있어, 그것만으로는 사다리가
    //   한 위상에 갇힌다(실측으로 겪었다). 싼 잉크(테)로 그 틈을 메운다.
    if (SOLID > .02) {
      IBrim(c, IZpoly(mx, my, rr * (.80 + .16 * SOLID), 12, tp * .05 + .26 + CROT, IZM_SQ),
        "snow", (.30 + .40 * SOLID) * z, (.9 + 1.4 * SOLID) * SC);
      for (let j = 0; j < IZM_SIG; j++) {
        const a0 = (j + .5) / IZM_SIG * TAU - tp * .04 + CROT;
        IBflake(c, mx + Math.cos(a0) * rr * (.48 + .34 * SOLID),
          my + Math.sin(a0) * rr * (.48 + .34 * SOLID) * IZM_SQ,
          (3.0 + 3.4 * SOLID) * SC, a0 * .4, "frost", (.34 + .34 * SOLID) * z, .8 * SC, IZM_SQ);
      }
    }
    for (let j = 0; j < IZM_SIG; j++) {
      const a0 = j / IZM_SIG * TAU + tp * .05 + CROT;
      IBline(c, [[mx + Math.cos(a0) * rr * .26, my + Math.sin(a0) * rr * .26 * IZM_SQ],
                 [mx + Math.cos(a0) * rr * .97, my + Math.sin(a0) * rr * .97 * IZM_SQ]],
        1.1 * SC, "frost", .50 * z, 0);
      // 살 끝의 육각 문장 — 판이 「결정 격자」라는 유일한 획
      IBflake(c, mx + Math.cos(a0) * rr * .84, my + Math.sin(a0) * rr * .84 * IZM_SQ,
        4.4 * SC, a0 * .5, "frost", .62 * z, .9 * SC, IZM_SQ);
    }
    // ㉣ 소멸 — **가장자리부터 갈라진다.** 빙판은 테가 깨지고 이건 **금이 간다**
    if (crack > 0) for (let j = 0; j < 11; j++) {
      const a0 = (j + .5) / 11 * TAU + .4 + CROT;
      const v = IZcl(crack * 1.6 - hash(j * 4.9) * .5);
      if (v <= 0) continue;
      IBline(c, [[mx + Math.cos(a0) * rr * (1 - v * .78), my + Math.sin(a0) * rr * (1 - v * .78) * IZM_SQ],
                 [mx + Math.cos(a0 + .18) * rr, my + Math.sin(a0 + .18) * rr * IZM_SQ]],
        1.2 * SC, "frost", (1 - crack * .5) * .66 * z, 0);
      // ⚠️ 갈라진 틈에서 **빛이 샌다**(가산) — 소멸이 「면이 옅어지는 것」으로
      //   끝나면 그 마디가 색종이가 된다. 부서짐은 빛이다.
      gAdd(c, (cc) => IBspark(cc, mx + Math.cos(a0) * rr * (1 - v * .40),
        my + Math.sin(a0) * rr * (1 - v * .40) * IZM_SQ,
        (4.6 - 3.0 * v) * SC, "frost", (1 - v) * .74 * z, a0));
      if (!st.ev["ck" + j] && v > .5) { st.ev["ck" + j] = 1;
        IZchip(st, mx + Math.cos(a0) * rr, my + Math.sin(a0) * rr * IZM_SQ, j * 6.1, 2,
          { b: tau, a: a0, spread: .9, v: 20, vr: 14, r: 1.4, rr: 1.1, life: .34, g: 60 });
      }
    }
    // ⭐⭐⭐ **동심 금** — 방사 금을 **가로질러 잇는다**. (레퍼런스: 유리·얼음
    //   파괴는 방사 금이 **먼저**, 동심 호가 **나중**에 그것들을 가로지른다 —
    //   forensicfield / SWGMAT 「Glass Fractures」의 radial ↔ concentric.)
    // ⚠️ 앞 판은 방사 금 열하나뿐이라 **부챗살**로 보였다. 「깨졌다」로 읽히는
    //   것은 방사가 아니라 **두 계열이 교차하는 격자**다.
    // ⚠️ 동심이 **늦게** 뜬다(`crack` 의 뒤 절반) — 그 순서가 곧 파괴의 순서다.
    //   그리고 이것이 **깨트리기가 부를 자리**의 예고이기도 하다.
    // ⚠️ 전부 **획**이라 칠하는 면적이 안 는다 — 화려함을 면적으로 사지 않는다.
    if (crack > .34) for (let ri = 0; ri < 2; ri++) {
      const w = IZcl((crack - .34 - ri * .18) / .34);
      if (w <= 0) continue;
      const cr = rr * (.52 + .30 * ri);
      const seg = 11, span = TAU * (.42 + .34 * w);
      const a1 = .4 + ri * 1.7 + CROT;
      for (let j = 0; j < seg; j++) {
        const b0 = a1 + span * (j / seg), b1 = a1 + span * ((j + 1) / seg);
        const wob = 1 + .10 * (hash(j * 3.3 + ri) - .5);
        IBline(c, [[mx + Math.cos(b0) * cr * wob, my + Math.sin(b0) * cr * wob * IZM_SQ],
                   [mx + Math.cos(b1) * cr * wob, my + Math.sin(b1) * cr * wob * IZM_SQ]],
          1.0 * SC, "frost", w * (1 - crack * .40) * .58 * z, 0);
      }
    }
  }

  // ── ⭐⭐⭐ **차오름과 뒤집힘** — 이 칸의 전부다 ──────────────────────────
  // ⚠️ 적 표식(성에 → 빙결 → 도장)은 [IZmarks] 가 **다섯 칸과 같은 그림**으로
  //   그린다. 여기서 더하는 것은 **이 칸에만 있는 두 획**이다:
  //     ㉠ **발치부터 자라는 결정 기둥** — 「차오르는 중」의 그림
  //     ㉡ **갇힌 빛** — 「다 얼었다」의 그림. 둘이 **다른 그림**이라야 뒤집힌다
  for (let i = 0; i < F.length; i++) {
    const f = F[i];
    const fx = cx + f.ox + f.kx, fy = cy + f.oy + f.ky;
    const w = IZcl(f.pv / IZF_ON);                     // 0 → 1 차오름
    if (w <= .02) continue;
    if (!f.frz) {
      // ㉠ **차오르는 중** — 발치에서 결정이 자란다. 높이가 곧 「얼마나」다
      // ⭐ **핵에서 자란다**(레퍼런스: atoptics 「Windscreen frost」 — 핵이 드문
      //   드문 있을수록 **한 덩이가 크게** 자란다. 균일하게 흩뿌리면 그건 서리가
      //   아니라 **칠**이다). ⇒ 기둥을 발치 원에 고르게 두지 않고 **핵 둘**에
      //   몰아 붙인다 — 각도를 핵 쪽으로 당긴다.
      const nu = i * 2.1;                       // 이 적의 핵 위상
      for (let j = 0; j < IZM_COL; j++) {
        const ev = (j + .5) / IZM_COL * TAU + i;
        const nk = nu + (j % 2) * Math.PI;      // 핵 둘 — 반대편에 하나씩
        const a0 = ev + (nk - ev) * .55;        // 핵 쪽으로 당긴다
        const d0 = f.r * (.55 + .40 * hash(i * 3.1 + j));
        const hh = IZM_COLH * SC * w * (.55 + .60 * hash(j * 5.3));
        const px = fx + Math.cos(a0) * d0, py = fy + f.r * .62 + Math.sin(a0) * d0 * IZM_SQ;
        IZprism3(c, px, py,
          -Math.PI / 2 + (hash(i + j * 2.7) - .5) * .5,
          hh, 2.0 * SC, i * 7.1 + j * 3.3, .88 * w * z, { far: .28, tip: .18 });
        // ⭐⭐ **자라는 끝이 제일 밝다** — 얼음은 매끈한 면이 아니라 **모서리에서**
        //   제일 빨리 자란다(같은 레퍼런스: 「growth proceeds fastest at edges」).
        //   ⇒ 앞머리에 가산 점 하나. **면적이 안 느는 밀도**가 여기서 나온다.
        gAdd(c, (cc) => IBspark(cc, px, py - hh,
          (1.6 + 1.4 * w) * SC, "snow", w * w * .80 * z, a0));
      }
      // ㉤ 밑동의 **들쭉날쭉한 흰 테** — 「바닥에서 올라왔다」
      IBrim(c, jagPoly(fx, fy + f.r * .66, f.r * (.7 + .5 * w), 9, i * 5.7, 1.14, IZM_SQ * .7),
        "snow", .52 * w * z, 1.0 * SC);
    } else {
      // ㉡ ⭐⭐ **뒤집혔다** — 「이제 치면 깨진다」가 화면의 말이 되는 자리.
      //   ⚠️ 차오름과 **다른 획**을 쓴다. 같은 도형이 진해지기만 하면 뒤집힘이 아니다.
      const since = IZcl((tau - (st.ev["frz" + i] || tau)) / .34);
      // ① 윤곽이 또렷해진다 — 몸을 감싼 육각 껍질
      IBrim(c, IZpoly(fx, fy, f.r * 1.32, 6, i * .7, .96), "frost", .92 * z, 1.6 * SC);
      // ② **안에서 빛이 갇힌다**(가산) — 껍질 속이 밝다. 깨질 것의 신호다
      gAdd(c, (cc) => fillPoly(cc, IZpoly(fx, fy, f.r * 1.16, 6, i * .7, .96),
        A("#BFE6FF", (.16 + .10 * Math.sin(tp * 2 + i)) * z)));
      // ②-b ⭐⭐ **굴절** — 속이 **밀려** 보인다. 실물 빙결 셰이더가 `_FrozenAmount`
      //   로 올리는 세 항이 **굴절 · 림 · 반투과**인데(robertrumney/frozen-shader-2D:
      //   `refractedUV = uv + normal.xy * _Refraction`), 우리에게 림과 반투과는
      //   있었고 **굴절만 없었다**. 캔버스는 몸을 다시 못 뜨므로 **어긋난 겹**으로
      //   같은 말을 한다 — 안쪽 윤곽 하나를 옆으로 밀어 그린다.
      // ⚠️ 획이라 면적이 안 는다. 그런데 이 한 줄이 「유리 속에 있다」를 만든다.
      IBrim(c, IZpoly(fx + 1.5 * SC, fy - 1.1 * SC, f.r * .92, 6, i * .7 + .18, .96),
        "snow", .44 * z, .9 * SC);
      // ③ 뒤집히는 **그 순간** 한 번만 — 조각이 위로 튄다(사방 폭발이 아니다)
      // ⚠️⚠️ **가산이다** — 뒤집히는 순간의 조각은 **빛**이지 바닥이 아니다.
      if (since < 1) gAdd(c, (cc) => { for (let j = 0; j < 5; j++) {
        const a0 = -Math.PI / 2 + (j - 2) * .30;
        const dd = f.r * (.4 + 1.5 * since);
        IBshard(cc, fx + Math.cos(a0) * dd, fy + Math.sin(a0) * dd * .8,
          (2.6 - 1.2 * since) * SC, a0, "frost", (1 - since) * .82 * z, .46);
      } });
      // ④ 도장은 [IZmarks] 가 찍는다 — L5 는 **두 배**라 멀리서도 골라진다
      if (SEALS > 1) IZseal(c, fx, fy, f.r * 1.5, SC, .70 * z);
    }
  }

  // ㉤ 종료 — 굳은 자국이 **서리 가지**로 남았다가 김으로. 소멸과 다른 그림이다
  if (B.inRest) {
    // ⭐ **굳은 자국** — 레벨이 높을수록 넓게 남는다. 사다리가 종료에도 선다.
    if (SOLID > .02) {
      // ⚠️ 여기도 √ 다 — 남는 자국의 **넓이**가 굳음에 비례해야 사다리가 종료
      //   마디까지 선다(반지름에 그대로 곱하면 아랫칸이 얇아진다).
      const sr2 = R * Math.sqrt(SOLID) * (1 - .45 * IZss(B.rest));
      IBroot(c, mx, my, sr2 * .9, "frost", (1 - B.rest) * .34 * z, IZM_SQ);
      IBrim(c, jagPoly(mx, my, sr2, 11, 8.7, 1.06, IZM_SQ), "snow",
        (1 - B.rest) * .52 * z, 1.1 * SC);
    }
    IZrestFx(c, mx, my, B.rest, R * .62, SC, z, 27.1);
    IZfern(c, mx, my, R * (.55 + .40 * SOLID), 7, IZss(B.rest), SC,
      (1 - B.rest) * .66 * z, CFRN + 2.4, IZM_SQ);
  }

  IZchips(c, st, tau, SC, z);
  IZmarks(c, tp, cx, cy, F, SC, z);
  hero(c, th, cx, cy);
},

// ── ⑤ 얼음창 ──────────────────────────────────────────────────────────────
// ⭐⭐⭐ **연출은 사용자가 통째로 줬다**(2026-08-29). 예시가 아니라 **사양**이다:
//   > 「**캐릭터 머리 위에 동그란 구 같은 형태로 별빛 에너지를 모으는 느낌**의
//   >  연출을 하고 **구가 살짝 커지면서(아공간이 열리는 느낌)** 그곳에서 창이
//   >  **'쇠붙이'쪽부터 길게 뽑아져 나오고**, 창이 다 뽑혀 나오면 **한 박자 쉬고**
//   >  적들 위치로 **빠르고 길게 날리는** 거임」
// 🔴🔴 **바닥 마법진을 걷었다.** 사용자가 이유를 정확히 댔다 — 「**장판은 바닥에
//   깔리는 거니까**」 거기서 나오면 **바닥에서 뽑는 것**이 되고, 공중에서 나오는
//   것으로 안 읽힌다. ⇒ 진 대신 **머리 위의 구**다.
//   ⭐ 규약으로 세운다 — **「바닥 진은 바닥에서 일어나는 일에만 깐다」**
//     진이 맞는 자리: 바닥에서 솟는 것 · 떨어질 자리를 예고하는 것 · 깔리는 것
//     진이 틀린 자리: **공중에서 나오는 것** · 몸에 붙어 따라다니는 것 ·
//                     **빠르게 나가는 것**(빙추에서 같은 날 걷었다)
// ⚠️ 구는 **공중**이다 ⇒ 2D 에서 높이를 내는 것은 **발치 그림자**뿐이다(㉧).
//   본체가 그림자와 만나면 「닿았다」로 읽히므로 **떨어뜨려** 그린다.
IZspear(c, t, dt, W, H, st) {
  const cx = W / 2, cy = H / 2, SC = Math.min(W, H) / 238;
  const F = IZfoes(st, SC, IZK_FOE);
  const u = saw(t, IZK_PER), tau = u * IZK_PER;
  if (IZwrap(st, u)) for (const f of F) { f.pv = 0; f.frz = 0; }
  const z = IZz(tau, IZK_PER, IZK_B[4]);
  const tp = tau * TAU / IZK_PER, th = tau * (TAU * 2 / 2.2) / IZK_PER;
  const wob = TAU * 2 * tau / IZK_PER;
  const B = IZbeat(tau, IZK_B);
  const SZ = IZK_SIZE[LV - 1], CRK = IZK_CRACK[LV - 1], OPN = IZK_OPEN[LV - 1];
  const FRS = IZK_FROST[LV - 1], RIS = IZK_RISE[LV - 1];


  // ── 🔴🔴 **발현 안이 넷이다 — 옆으로(천천히) → 뒤로 당김 → 발사 → 여운**
  // ⚠️⚠️ **창은 한 번도 사라지지 않는다.** 뽑힌 창이 그대로 **옮겨지고 ·
  //   당겨지고 · 날아간다.** ⇒ 자리를 「**손잡이(밑동) 한 점**」으로만 다루고
  //   창은 언제나 `손잡이 → 손잡이 + 방향×길이` 로 그린다. 마디마다 따로
  //   좌표를 잡으면 경계에서 **튀고 끊긴다**(앞 판이 그랬다).
  const hitT = tau - B.t1;
  const mvR  = B.inHit ? IZcl(hitT / IZK_MOVE) : (B.inCast || B.inGrow ? 0 : 1);
  const dwR  = B.inHit ? IZcl((hitT - IZK_MOVE) / IZK_DRAW) : (B.inCast || B.inGrow ? 0 : 1);
  /// 🔴 뺀 끝에서의 **멈춤** — `dwR` 이 1 이 되고 `flyR` 이 시작하기 전 0.12초
  const hldR = B.inHit ? IZcl((hitT - IZK_MOVE - IZK_DRAW) / IZK_HOLD)
    : (B.inCast || B.inGrow ? 0 : 1);
  const flyR = B.inHit ? IZcl((hitT - IZK_MOVE - IZK_DRAW - IZK_HOLD) / IZK_FLYT)
    : (B.inCast || B.inGrow ? 0 : 1);
  /// 창이 **끝(날)부터** 뽑혀 나온 몫 — 생성의 `.15~.72` 안에 **1.00 에 닿는다**.
  const em = B.inCast ? 0 : B.inGrow ? IZss(IZcl((B.grow - .15) / .57)) : 1;
  // 자리 셋
  const hx = cx + IZK_FROM[0] * SC, hy = cy + IZK_FROM[1] * SC;   // 머리 위 구
  const sx = cx + IZK_SIDE[0] * SC, sy = cy + IZK_SIDE[1] * SC;   // 몸 옆
  const ax0 = cx + IZK_AT[0] * SC, ay0 = cy + IZK_AT[1] * SC;     // 박히는 끝
  const len = IZK_LEN * (1 + (SZ - 1) * .34) * SC;
  /// 겨누는 쪽 — **옆자리에서 표적으로**. 뽑힐 때는 위를 본다.
  const aimX = ax0 - sx, aimY = ay0 - sy, aimL = Math.hypot(aimX, aimY);
  const ux = aimX / aimL, uy = aimY / aimL;
  const upX = 0, upY = -1;                                        // 뽑힐 때의 방향
  /// ㉠ **옆 이동은 천천히** — 부드럽게 들어가고 부드럽게 선다
  const mv = IZss(mvR);
  /// ㉡ **뒤로 당김** — 갔다가 튕겨 나간다(당김이 끝나면 0 으로 안 돌아온다)
  const pull = IZss(dwR) * IZK_PULL * SC;
  /// ㉣ 🔴 **「팍」은 급가속이다.** 등속(1.0)이면 미끄러지는 것으로 읽힌다.
  /// ⚠️ `f⁴` 이라 **끝 속도 ÷ 평균 속도 = 4.0배**다(채찍이 15.5배였고, 그건
  ///   끝이 채찍처럼 휘는 스킬이라 더 극단이 맞았다. 이 칸은 **곧게** 나간다).
  const fe = flyR * flyR * flyR * flyR;
  // 방향은 **뽑힐 때 위 → 옆으로 가며 겨눔으로** 돌아간다
  const dxx = upX + (ux - upX) * mv, dyy = upY + (uy - upY) * mv;
  const dl = Math.hypot(dxx, dyy) || 1;
  const dX = dxx / dl, dY = dyy / dl;
  // 손잡이 자리 — 구 → 옆(천천히) → 뒤로 당김 → 표적(빠르게)
  const gHomeX = hx, gHomeY = hy;
  const gSideX = sx - dX * pull, gSideY = sy - dY * pull;
  const gEndX = ax0 - ux * len, gEndY = ay0 - uy * len;
  const gripX = flyR > 0 ? gSideX + (gEndX - gSideX) * fe : gHomeX + (gSideX - gHomeX) * mv;
  const gripY = flyR > 0 ? gSideY + (gEndY - gSideY) * fe : gHomeY + (gSideY - gHomeY) * mv;
  // 꽂힌 뒤 흔들린다
  const shk = (B.inFade || B.inRest)
    ? Math.exp(-(tau - B.t2) / IZK_SHAKE) * Math.sin((tau - B.t2) * 42) * .075 : 0;
  const ca = Math.cos(shk), sa = Math.sin(shk);
  const rX = dX * ca - dY * sa, rY = dX * sa + dY * ca;
  // ── 🔴🔴 **박힌다** — 닿는 순간부터 창끝이 바닥선 아래로 들어간다 ────────
  /// 닿는 시각. `flyR` 이 1 에 닿는 그 자리다.
  const tLand = B.t1 + IZK_MOVE + IZK_DRAW + IZK_HOLD + IZK_FLYT;
  /// **꽂혔나** — 발현 마디의 착지 뒤 · 소멸 · 종료. 그 전에는 하나도 안 잘린다.
  const LAND = (B.inHit && flyR >= 1) || B.inFade || B.inRest;
  /// 박힌 몫(창 길이의 비). ⚠️ **닿는 그 프레임에 이미 [IZK_SINK0] 만큼** 들어가
  ///   있다 — 0 에서 시작하면 「닿았는데 안 잘린 프레임」이 하나 생긴다.
  const sunk = LAND ? IZK_DEEP[LV - 1] *
    (IZK_SINK0 + (1 - IZK_SINK0) * IZss(IZcl((tau - tLand) / IZK_SINKT))) : 0;
  const dp = len * sunk;                      // 바닥선 아래로 들어간 길이
  /// 🔴 **흔들림의 축은 꽂힌 점**이다 — 박힌 자리는 한 점도 안 움직이고
  ///   창의 **위쪽(손잡이)만** 흔들린다. 손잡이를 축으로 두면 잘린 자리가
  ///   같이 흔들려 「박혔다」가 도로 「놓였다」가 된다.
  const tipX = LAND ? ax0 + rX * dp : gripX + rX * len * (B.inGrow ? em : 1);
  const tipY = LAND ? ay0 + rY * dp : gripY + rY * len * (B.inGrow ? em : 1);
  const btX = LAND ? ax0 - rX * (len - dp) : gripX;
  const btY = LAND ? ay0 - rY * (len - dp) : gripY;
  /// 🔴 **바닥선을 따라 자른다** — 창 축이 아니다(㉢). 꽂힌 점을 지나는 가로선
  ///   위쪽(화면에서 더 먼 쪽)은 **땅속**이라 한 획도 안 그린다.
  /// ⚠️ `clip` 을 쓰는 까닭: [IZpike] 는 면 · 테 · 금 · 기포(가산) · 앞날 · 미늘 ·
  ///   밑동 가시 · 칼받침 **여덟 항**이라 획마다 자르면 여덟을 다 고쳐야 하고,
  ///   가산 패스([gAdd])가 그 밖으로 샌다. 창 한 자루라 클립이 싸다.
  const underGround = (fn) => {
    c.save(); c.beginPath(); c.rect(0, ay0, W, Math.max(0, H - ay0)); c.clip();
    try { fn(); } finally { c.restore(); }
  };
  /// ㉢ **발치 그림자** — 보이는 자루 밑에 **눌린 면**. 이것이 없으면 「공중에
  ///   떠 있는 것」과 안 갈린다. ⚠️⚠️ **면으로 칠한다** — 검정을 가산으로
  ///   칠하면 아무 일도 안 일어난다(이 저장소가 두 번 겪은 자리다).
  /// ⚠️ 자루의 **땅 위 그림자**라 세로가 [LX3SQT] 로 눌린다 — 자루 자체는 서고
  ///   그림자는 눕는다(이 칸이 `mixed` 인 까닭 그대로다).
  /// ⚠️⚠️ **[ribbonPoly] 로 냈다가 실측 0 이 나왔다** — 그 함수의 폭 포락선이
  ///   `sin(π·u)^.42` 라 **점을 둘만 주면 양끝이 곧 전부**여서 폭이 0.30 배 →
  ///   0 으로 스러진다(잰 값: 「바탕보다 어두운 화소 **0개**」). ⇒ 아홉 점을
  ///   손으로 뜨고 포락선도 **양 끝만 짧게 무디게** 잡는다.
  const plantShadow = (a) => {
    if (a <= .02 || !LAND) return;
    const L = (len - dp) * IZK_SHL;
    const bx = ax0, by = ay0 + 1.4 * SC;
    const ex = ax0 - rX * L, ey = ay0 - rY * L * LX3SQT + 2.4 * SC;
    const dx = ex - bx, dy = ey - by, dl = Math.hypot(dx, dy) || 1;
    const nx = -dy / dl, ny = dx / dl, N = 8, PA = [], PB = [];
    for (let i = 0; i <= N; i++) {
      const q = i / N;
      const env = Math.min(1, q / .18) * Math.min(1, (1 - q) / .14);
      const w = (IZK_SHW0 + (IZK_SHW1 - IZK_SHW0) * q) * SZ * SC * env;
      PA.push([bx + dx * q + nx * w, by + dy * q + ny * w]);
      PB.push([bx + dx * q - nx * w, by + dy * q - ny * w]);
    }
    fillPoly(c, PA.concat(PB.reverse()), A("#020306", .80 * a));
  };
  /// ㉡ 🔴 **밑동에 얇고 밝은 테** — 「여기가 지면이다」를 말한다. **넷 중
  ///   제일 큰 한 항**이고, 없으면 잘린 창이 그냥 **짧은 창**으로 읽힌다.
  /// ⚠️ 크기가 **바닥선에서의 창 반폭**([IZpikeW])에서 나온다 — 고정 크기로 두면
  ///   L1 에서 접시가 되고 L5 에서 안 보인다. 깊이가 깊을수록 창이 굵은
  ///   자리에서 잘리므로 **테도 같이 커진다**(레벨이 여기서도 읽힌다).
  /// ㉣ 그리고 **밀려난 부스러기** — 박히며 뜯겨 나온 것이 그 자리에 남는다.
  const plantLip = (a) => {
    if (a <= .02 || !LAND) return;
    const rr = IZpikeW(sunk, SZ, SC) * IZK_LIP + IZK_LIP0 * SZ * SC;
    /// 🔴 **뚫린 구멍** — 창이 들어간 자리는 **어둡다**. 잘린 자루가 이 어둠
    ///   **안으로** 끝나야 「가려졌다」가 되고, 밝은 테만 있으면 「얹혔다」가 된다.
    /// ⚠️ 어둠은 **면**이다(가산이 아니다). 그리고 바탕이 검은 칸이라 어둠이
    ///   힘을 쓰는 자리는 **밝은 테 안쪽**뿐이다 — 그래서 여기 둔다.
    const hr = IZpikeW(sunk, SZ, SC) * 1.6 + 1.6 * SZ * SC;
    fillPoly(c, jagPoly(ax0, ay0, rr, 9, 4.7, 1.16, LX3SQT * .82), A("#DCEFFF", .50 * a));
    fillPoly(c, jagPoly(ax0, ay0, hr, 7, 1.9, 1.10, LX3SQT * .82), A("#03050C", .92 * a));
    IBrim(c, jagPoly(ax0, ay0, hr, 7, 1.9, 1.10, LX3SQT * .82), "snow", .96 * a, .8 * SC);
    IBrim(c, jagPoly(ax0, ay0, rr * 1.24, 9, 4.7, 1.16, LX3SQT * .82),
      "snow", .92 * a, .9 * SC);
    for (let j = 0; j < IZK_GRIT; j++) {
      const a0 = (j + .5) / IZK_GRIT * TAU + 1.9;
      const d0 = rr * (1.4 + 1.6 * hash(j * 3.7 + 2.1));
      IBshard(c, ax0 + Math.cos(a0) * d0, ay0 + Math.sin(a0) * d0 * LX3SQT,
        (1.5 + 1.6 * hash(j * 5.3)) * SC * SZ, a0 + .8, "frost", .62 * a, .6);
    }
  };
  /// 🔴 **꽂힌 창 한 자루** — 바닥선 아래는 안 그린다(㉠). 그림자 → 창 → 테
  ///   차례라야 「그림자 위에 창이 서고 그 창이 테를 뚫고 들어간다」가 된다.
  const plantPike = (a) => {
    plantShadow(a);
    underGround(() => IZpike(c, btX, btY, tipX, tipY, SZ, SC, a, 9.1,
      { em: 1, open: OPN ? 1 : 0 }));
  };
  /// 🔴 **훑는 띠** — 창이 지나간 **직선 전체**가 한 번에 쓸린다.
  const swW = IZK_SW * SZ * SC;

  // ── 맞는다 — 🔴 **판정은 창의 폭이 아니라 「띠의 폭」이다**
  if (B.inHit && flyR >= 1) for (let i = 0; i < F.length; i++) {
    const f = F[i], px2 = cx + f.ux * SC, py2 = cy + f.uy * SC;
    const bx0 = gSideX + rX * len, by0 = gSideY + rY * len;
    const bl = Math.hypot(ax0 - bx0, ay0 - by0) || 1;
    const t2 = ((px2 - bx0) * ux + (py2 - by0) * uy) / bl;   // 띠 위 진행
    const dd = Math.abs((px2 - bx0) * -uy + (py2 - by0) * ux);
    if (t2 < -.05 || t2 > 1.15 || dd > swW) continue;
    IZchill(f, dt * 5.0); f.hit = 1;
    if (!st.ev["h" + i]) { st.ev["h" + i] = 1;
      IZchip(st, px2, py2, i * 4.7, 4,
        { b: tau, a: -Math.PI / 2, spread: 1.2, v: 34, vr: 24, r: 1.4, rr: 1.1,
          life: .36, g: 150 }); }
  }
  for (const f of F) f.hit = Math.max(0, f.hit - dt * 4);
  IZstand(F, SC, wob, z);

  // ══ 그리기 ═══════════════════════════════════════════════════════════════
  // ㉠ 시전 — 🔴 **머리 위에 동그란 구.** 별빛이 모여든다. 마법진은 **없다**
  if (B.inCast || (B.inGrow && em < 1)) {
    const g = B.inCast ? IZss(B.cast) : 1;
    const grow = B.inGrow ? IZss(IZcl(B.grow / .30)) : 0;   // 아공간이 열린다
    const orb = IZK_ORB * (1 + (SZ - 1) * .5) * SC * (.35 + .65 * g) * (1 + (IZK_ORB2 - 1) * grow);
    // ㉧ **발치 그림자** — 2D 에서 「공중에 있다」를 내는 유일한 획
    IBroot(c, hx, cy - 6 * SC, orb * 1.15, "frost", .26 * z, .34);
    // 구 — 안이 비치고 테가 밝다. ⚠️ 꽉 찬 흰 공이면 「빛덩이」가 되어 아공간이 안 된다
    // ⚠️ 창이 나오기 시작하면 **채움을 걷는다** — 꽉 찬 공이 창을 덮어
    //   「구 안에 갇힌」 그림이 됐다(갈무리 판정). 열린 아공간은 **고리**다.
    const solidOrb = 1 - IZcl(em * 2.2);
    if (solidOrb > .02) fillPoly(c, IZpoly(hx, hy, orb, 12, tp * .3, 1),
      A(mixHex(toneOf("frost")[0], toneOf("frost")[1], .40), .46 * solidOrb * z));
    IBrim(c, IZpoly(hx, hy, orb, 12, tp * .3, 1), "snow", .84 * z, 1.3 * SC);
    IBrim(c, IZpoly(hx, hy, orb * (.62 + .22 * grow), 6, -tp * .5, 1), "frost", .60 * z, 1.0 * SC);
    gAdd(c, (cc) => IBroot(cc, hx, hy, orb * (.55 + .45 * grow), "frost",
      .40 * (1 - IZcl(em * 1.6)) * z, 1));
    // 별빛이 **모여든다** — 밖에서 안으로. ⚠️ 무의 「별빛자리」와 다르다:
    //   그쪽은 별을 **잇는 것**이고 이쪽은 한 점으로 **빨려드는 것**이다
    gAdd(c, (cc) => { for (let j = 0; j < IZK_MOTE; j++) {
      const a0 = (j + .5) / IZK_MOTE * TAU + tp * .6;
      const d0 = orb * (3.2 - 2.3 * g) * (.75 + .45 * hash(j * 3.1));
      IBspark(cc, hx + Math.cos(a0) * d0, hy + Math.sin(a0) * d0 * .82,
        (2.2 + 2.0 * hash(j * 5.7)) * SC * SZ, "snow", .74 * g * z, a0);
      IBline(cc, [[hx + Math.cos(a0) * d0 * 1.5, hy + Math.sin(a0) * d0 * 1.5 * .82],
                  [hx + Math.cos(a0) * d0, hy + Math.sin(a0) * d0 * .82]],
        .8 * SC, "frost", .34 * g * z, 1);
    } });
  }
  // ㉡ 생성 — 🔴 **창이 「쇠붙이(날)」 쪽부터 길게 뽑혀 나온다**
  if (B.inGrow && em > .01) {
    // 🔴 **끝이 구에서 앞으로 나아간다.** 아직 안 나온 뒷부분은 구 **안**에 있다
    //   (`em` 이 끝에서부터의 몫이라 그 뒤는 안 그려진다) — 그것이 「뽑는다」다.
    // ⚠️ 앞 판은 끝을 구에 **고정**하고 자루를 뒤로 늘렸다 — 갈무리로 보니
    //   **창이 구 뒤에 매달린** 꼴이었다. 나오는 것이 아니라 자라는 것이었다.
    const tX = hx + ux * len * em, tY = hy + uy * len * em;
    IZpike(c, tX - ux * len, tY - uy * len, tX, tY, SZ, SC, .94 * z, 9.1,
      { em: em, open: OPN ? em * .5 : 0 });
    // 뽑혀 나오는 **입**에서 조각이 튄다 — 「빠져나온다」가 여기서 읽힌다
    gAdd(c, (cc) => { for (let j = 0; j < 5; j++) {
      const a0 = Math.atan2(-uy, -ux) + (j - 2) * .34;
      const d0 = IZK_ORB * SZ * SC * (.8 + .9 * hash(j * 2.7));
      IBshard(cc, hx + Math.cos(a0) * d0, hy + Math.sin(a0) * d0 * .8,
        (2.2 + 1.8 * hash(j * 6.1)) * SC * SZ, a0, "frost", .70 * em * z, .5);
    } });
  }
  // ㉢ 발현 — **멈춤 → 빠르고 길게 → 넓은 띠가 직선을 초토화**
  if (B.inHit) {
    // ① 🔴 **한 박자 쉼** — 다 뽑힌 창이 **멈춰 있다**. 이 정지가 사건이다
    if (flyR <= 0) {
      // ㉠㉡ **든다 → 뺀다** — 창이 눕고, 몸보다 뒤로 물러난다
      IZpike(c, btX, btY, tipX, tipY, SZ, SC, .96 * z, 9.1, { em: 1, open: OPN ? 1 : 0 });
      // 멈춘 동안 **떨림만** 있다 — 완전히 정지하면 죽은 그림이 된다
      // 아공간이 닫힌다 — 창이 옆으로 나가는 동안
      gAdd(c, (cc) => IBspark(cc, hx, hy, IZK_ORB * SZ * SC * (.8 - .5 * mvR),
        "snow", (1 - mvR) * .60 * z, 0));
      // 🔴 **뺀 끝에서 멈춘다** — 그 정지가 「팍」을 만든다. 힘이 모이는 표시
      if (hldR > 0 && flyR <= 0) gAdd(c, (cc) => IBspark(cc, btX, btY,
        (7 + 5 * Math.sin(tau * 30)) * SZ * SC, "snow", .70 * z, 0));
    }
    if (flyR >= 1) {
      // ② 🔴 **훑는 띠** — 창의 폭보다 **넓게**, 줄의 **처음부터 끝까지 한 번에**
      // ⚠️⚠️ 창을 따라 앞으로 자라지 **않는다** — 지나간 순간 **그 줄 전체**가
      //   쓸린다. 그것이 「초토화」다.
      // ⚠️ **날아가는 동안에는 안 그린다**(`flyR >= 1`) — 갈무리로 보니 창이
      //   아직 출발도 안 했는데 띠가 먼저 서 있었다. 띠는 **자국**이지 예고가
      //   아니다(그리고 이 칸은 「빠르게 나가는 것」이라 예고를 안 깐다).
      const sf = IZcl((hitT - IZK_MOVE - IZK_DRAW - IZK_HOLD - IZK_FLYT) / .20);   // 띠가 삭는 몫
      const aL = 1 - sf * .55;
      const nx = -uy, ny = ux;
      // ══ 🔴🔴 **띠는 「도형」이 아니라 「지나간 자국」이다** ═══════════════
      // 사용자 판정: 「시바 **피해 범위를 누가 파리채처럼 그리드 형태로**
      //   저런 식으로 구현해」
      // ⚠️⚠️ 앞 판은 띠에 **또렷한 테 + 나란한 금 일곱**을 그렸다. 가로(테)와
      //   세로(금)가 만나 **격자**가 됐고, **가는 자루 + 넓은 격자 = 파리채**다.
      //   ⇒ **격자 · 그물 · 모눈은 이 저장소에서 「범위」의 언어가 아니다.**
      //     범위는 **쓸린 자국**으로 낸다. 넷을 지킨다:
      //     ㉠ **한 방향으로만** 흐른다(가로줄이 없다)
      //     ㉡ **가장자리가 뜯겨 있다**(또렷한 직선이면 오려 붙인 것이 된다)
      //     ㉢ **가운데가 밝고 바깥이 옅다**(균일하면 판때기다)
      //     ㉣ **뒤에서부터 삭는다**(계속 남으면 장판이 된다)
      // ⚠️ 마름모 금은 **날에만** 있다 — 날은 손바닥만 한 면이고 거기 몇 줄이다.
      const NB = 12;
      const bvx = ax0 - gSideX - rX * len, bvy = ay0 - gSideY - rY * len;
      const eg = (side) => { const P2 = [];
        for (let i = 0; i <= NB; i++) { const q = i / NB;
          const w = swW * (.62 + .46 * hash(i * 2.7 + (side > 0 ? 0 : 11.3)));
          P2.push([gSideX + rX * len + bvx * q + nx * w * side,
                   gSideY + rY * len + bvy * q + ny * w * side]); }
        return P2; };
      const BAND = eg(1).concat(eg(-1).reverse());
      // ㉡ 뜯긴 가장자리 · ㉢ 균일하지 않은 속
      fillPoly(c, BAND, A(mixHex(toneOf("frost")[0], toneOf("frost")[1], .32), .22 * aL * z));
      // ㉢ **한가운데가 밝다** — 창이 지나간 심
      const CORE = eg(.34).concat(eg(-.34).reverse());
      fillPoly(c, CORE, A(mixHex(toneOf("frost")[1], "#DCEFFF", .30), .26 * aL * z));
      gAdd(c, (cc) => fillPoly(cc, CORE, A("#BFE6FF", .10 * aL * z)));
      // ㉠ **진행 방향으로만 흐르는 결** — 토막이라 가로줄이 안 생긴다
      // ㉣ **뒤에서부터 삭는다** — 뒤쪽 토막이 먼저 옅어진다
      for (let j = 0; j < 11; j++) {
        const off = (hash(j * 3.1) - .5) * 1.9 * swW;
        const q0 = hash(j * 5.9) * .55, q1 = Math.min(1, q0 + .24 + .34 * hash(j * 7.3));
        const back = 1 - q0;                       // 뒤일수록 먼저 삭는다
        const aa = aL * IZcl(1.35 - back * sf * 1.9);
        if (aa <= .02) continue;
        IBline(c, [[gSideX + rX * len + bvx * q0 + nx * off, gSideY + rY * len + bvy * q0 + ny * off],
                   [gSideX + rX * len + bvx * q1 + nx * off, gSideY + rY * len + bvy * q1 + ny * off]],
          (.8 + .8 * (1 - Math.abs(off) / swW)) * SC, "frost", .40 * aa * z, 0);
      }
      // 잔상 — **빠르다**를 만드는 항
      for (let j = 1; j <= IZK_GHOST; j++) {
        const q = fe - j * .12;
        if (q <= 0) continue;
        const gx = gSideX + (gEndX - gSideX) * q, gy = gSideY + (gEndY - gSideY) * q;
        IZpike(c, gx, gy, gx + rX * len, gy + rY * len, SZ * (1 - j * .05), SC,
          (1 - j / (IZK_GHOST + 1)) * .38 * z, 9.1, { em: 1 });
      }
    }
    // 🔴🔴 **꽂힌 창은 「닿는 그 프레임」부터 여기 서 있다.**
    // ⚠️⚠️ 앞 판은 착지 뒤 **0.20초 동안 창 본체를 안 그렸다** — 잔상 넷만
    //   그리고 소멸 마디에 가서야 다시 세웠다. 그 사이 화면에는 **띠와 잔상뿐**
    //   이라 「무엇이 꽂혔는지」가 없었고, 그것 자체가 「꽂힌 느낌이 없다」의
    //   한 몫이었다. ⇒ 착지 프레임부터 **잘린 창**이 선다(그래야 「닿는 프레임 −
    //   잘리기 시작하는 프레임 = 0」이 잴 수 있는 말이 된다).
    if (flyR >= 1) plantPike(.96 * z);
    if (flyR >= 1 && !st.ev.land) { st.ev.land = 1;
      IZchip(st, ax0, ay0, 21.3, 7,
        { b: tau, a: -Math.PI / 2, spread: 2.4, v: 42, vr: 30, r: 1.4, rr: 1.1,
          life: .40, g: 120 }); }
    if (flyR >= 1) plantLip(.96 * z);
    if (flyR >= 1) {
      const s0 = IZcl((hitT - IZK_MOVE - IZK_DRAW - IZK_HOLD - IZK_FLYT) / .14);
      gAdd(c, (cc) => IBspark(cc, ax0, ay0, 26 * SZ * SC * (1 - s0), "snow",
        (1 - s0) * .92 * z, 0));
      IBroot(c, ax0, ay0, 20 * SZ * SC * (.5 + .8 * s0), "frost", (1 - s0) * .50 * z, LX3SQT);
    }
  }
  // ㉣ 소멸 — 🔴 **꽂힌 채 남는다.** 빙추(지나간다)와 갈리는 자리다
  if (B.inFade || B.inRest) {
    const fade = B.inFade ? 1 : (1 - IZss(B.rest));
    // 훑은 자국이 **바닥에 남아** 삭는다 — 「초토화」의 잔상
    // ⚠️ 여기도 **테를 안 그린다**(격자 사고와 같은 자리) — 흐르는 결만 남긴다.
    const nx = -uy, ny = ux, aw = swW * (1 - .30 * (1 - fade));
    for (let j = 0; j < 7; j++) {
      const off = (hash(j * 4.7) - .5) * 1.7 * aw;
      const q0 = hash(j * 8.1) * .5, q1 = Math.min(1, q0 + .30 + .30 * hash(j * 2.3));
      const bx2 = ax0 - gSideX - rX * len, by2 = ay0 - gSideY - rY * len;
      IBline(c, [[gSideX + rX * len + bx2 * q0 + nx * off, gSideY + rY * len + by2 * q0 + ny * off],
                 [gSideX + rX * len + bx2 * q1 + nx * off, gSideY + rY * len + by2 * q1 + ny * off]],
        .8 * SC, "frost", .26 * fade * z, 0);
    }
    // 🔴 **잘린 채 서 있다** — 바닥선 아래(창끝)는 한 획도 안 그린다.
    plantPike(.92 * fade * z);
    IBrim(c, jagPoly(ax0, ay0, 13 * SZ * SC, 9, 3.3, 1.12, LX3SQT * .8),
      "snow", .66 * fade * z, 1.1 * SC);
    IBroot(c, ax0, ay0, 17 * SZ * SC, "frost", .34 * fade * z, LX3SQT);
    // ⚠️ **테는 자국보다 뒤에** 온다 — 위의 넓은 자국(13칸 · 17칸)이 테를 덮으면
    //   「지면」이 아니라 「터진 자리」로만 읽힌다. 테가 제일 위에 서야 한다.
    plantLip(fade * z);
    if (CRK) for (let j = 0; j < 9; j++) {
      const a0 = (j + .5) / 9 * TAU + .6;
      const rr2 = 24 * SZ * SC * (.5 + .6 * hash(j * 5.7)) * (B.inFade ? IZss(B.fade) : 1);
      IBline(c, [[ax0, ay0], [ax0 + Math.cos(a0) * rr2, ay0 + Math.sin(a0) * rr2 * LX3SQT]],
        .9 * SC, "frost", .34 * fade * z, 0);
    }
    if (FRS) {
      const fr = 30 * SZ * SC * (B.inFade ? IZss(B.fade) : 1);
      IBrim(c, IZpoly(ax0, ay0, fr, 12, tp * .04, LX3SQT), "frost", .34 * fade * z, 1.0 * SC);
      // ⚠️ 가지를 **줄였다**(6 → 4, 알파 .52 → .34) — 갈무리로 보니 L4·L5 에서
      //   금 · 가지 · 조각 · 섬광이 한꺼번에 흰 덩어리로 뭉쳤다.
      IZfern(c, ax0, ay0, fr * 1.05, 4, B.inFade ? IZss(B.fade) : 1, SC, .34 * fade * z, 13.7, LX3SQT);
    }
    if (RIS && B.inFade)
      IZcolumn(c, ax0, ay0, IZss(B.fade), 30 * SZ * SC, 8 * SC, SC, .92 * z, 17.9);
  }
  // ㉤ 종료 — 삭아 부서진다
  if (B.inRest) {
    IZrestFx(c, ax0, ay0, B.rest, 24 * SZ * SC, SC, z, 19.3);
    if (!st.ev.brk) { st.ev.brk = 1;
      IZchip(st, (btX + tipX) * .5, (btY + tipY) * .5, 27.7, 6,
        { b: tau, a: -Math.PI / 2, spread: 1.6, v: 24, vr: 20, r: 1.6, rr: 1.2,
          life: .48, g: 110 }); }
  }

  IZchips(c, st, tau, SC, z);
  IZmarks(c, tp, cx, cy, F, SC, z);
  hero(c, th, cx, cy);
},

});

// ══════════════════════════════════════════════════════════════════════════
// ⑤ 엉김 `iceclump` — **가까이 선 둘이 얼음으로 이어진다**   ⭐ 새로 낸 하나
// ══════════════════════════════════════════════════════════════════════════
// ⭐ 왜 이것을 냈나 — 빙에 **없던 동사**라서다. 지금 빙이 하는 것은 밀다(파문 ·
//   빙판 · 빙벽) · 막다(빙벽) · 굳히다(결빙) · 때리다(서릿발 ·
//   서리결정 · 우박) · 깨다(깨뜨리기) **다섯**인데, **잇다**가 없다.
//   ⚠️ 여섯이었던 것이 다섯이 됐다 — 「**쌓다**」(얼음 무지)가 폐기로 비었고,
//     「굳히다」도 상고대가 빠져 **결빙 하나**만 남았다.
//   그리고 잇는 것은 깨뜨리기의 밥이 된다 — 이어 놓고 깨면 둘이 같이
//   깨지므로, 새 칸 하나가 **이미 있는 칸을 살린다.**
// 면 = **선다**(upright) — 다리가 두 몸을 잇는 높이에 있지 바닥에 있지 않다.
// 항 넷 ─ 덩어리: 마디로 이어진 다리 / 층: 마디마다 몸·조각·테 /
//         불티: 이음매에서 튀는 조각 / 잔상: 끊긴 다리의 토막
// ── ⭐⭐ 다섯 마디 (2026-08-28 사용자 판정) ───────────────────────────────
//   > 「**엉김** — 나쁘진 않은데 **스킬 발동은 어떻게 하는 거임? 스킬 시전하는
//   >  애니메이션이 없어 보이는데**」
// 정확한 지적이다 — 앞 판은 주기 0.00초에 다리가 **이미 자라기 시작한다.**
// 시전이 0 이라 「누가 이걸 켰나」가 화면에 한 프레임도 없었다.
//   시전 0.34  몸에서 냉기가 모이고, 이을 **두 몸 사이에 씨앗 셋**이 떠오른다
//   생성 0.30  씨앗이 이어지며 다리가 **가운데부터** 자란다([IZL_LINK])
//   발현 1.70  다리가 서 있다(당김 · 사슬)
//   소멸 0.66  금 → 끊김 → 토막
//   종료 0.60  서리 자국이 스러진다([IZrestFx])
//   합 3.60 = 주기 ✓
const IZL_B = [.34, .30, 1.70, .66, .60];
const IZL_PER = 3.6;          // 3.0 → 3.6 (시전과 종료를 사 온 값)
/// 시전 때 두 몸 사이에 떠오르는 **씨앗** 수. ⚠️ 이것이 「무엇이 곧 이어지나」를
/// 미리 말한다 — 다리가 설 자리에 점이 먼저 서야 「시전」이 된다.
const IZL_SEED0 = 3;
const IZL_LINK = .30;         // 이어진다(= 생성 마디)
/// 버틴다 — 뒤쪽 0.50초에 금이 간다.
/// ⚠️ 처음 1.60 이었는데 다리가 **주기의 67% 만** 서 있어, 갈무리를 찍으면
///   다섯 칸이 다 빈 순간이 잦았다(죽은 시간 0.53초 = 18%). 1.90 으로 늘리면
///   .24+1.90+.18+.45 = 2.77 이라 죽은 시간이 **0.23초(7.7%)** 로 준다.
const IZL_HOLD = 1.70;        // = 발현 마디
const IZL_SNAP = .22;         // 끊긴다(소멸 앞머리)
const IZL_REST = .44;         // 토막이 스러진다(소멸 뒷머리)
const IZL_HOLD5 = .62;        // ⚠️ L5 만 짧다 — 한 주기에 **두 번** 잇기 때문이다
const IZL_CRACK = .50;        // 끊기기 전 금이 가는 구간
const IZL_SEG = 5;            // 다리의 마디 수
/// L2 부터 서로 당겨지는 거리(238칸). ⚠️ 처음 7 로 뒀더니 L1 과 잘 안 갈렸다
/// (실측 거리 0.083) — 몸 지름(18)의 절반도 안 움직이면 「당긴다」가 안 읽힌다.
/// 14 는 다리 길이(≈50)의 28% 라 **다리가 눈에 띄게 짧아진다.**
const IZL_PULL = 14;
const IZL_FOE = [[-58, -52, 9], [-12, -70, 9], [36, -46, 9], [70, -84, 9]];
/// 레벨마다 잇는 짝. **L1 은 한 줄, L3 부터 사슬이 된다.**
const IZL_PAIR = [[[0, 1]], [[0, 1]], [[0, 1], [1, 2]], [[0, 1], [1, 2]],
                  [[0, 1], [1, 2], [2, 3]]];
// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐ **2026-08-28 사용자 판정 — 이어지는 것을 화려하게**
//
//   > 「**엉김** → 연결되는 효과를 좀 더 **얼음과 서리, 얼음빔, 얼음결정**
//   >  아무튼간 **화려한 얼음 효과들이 다 섞인** 화려한 느낌을 추가」
//
// 앞 판은 「얼음 다리」 **하나**였다 — 마디 다섯 + 가는 심 하나. 갈무리로 보면
// 적 둘 사이의 **점선**이고, 그것이 「엉겼다」로 안 읽혔다.
//
// ── ⚠️⚠️ 겹을 늘리되 **실루엣은 하나**여야 한다 ─────────────────────────
// 다른 갈래가 「가는 획 여럿 = 거미줄」로 첫 판을 통째로 버린 전례가 있다.
// 그래서 규칙을 **수 하나로** 못 박는다:
//   ⇒ **더해지는 모든 획이 축선에서 [IZL_SLEEVE] 안에 든다.** 축 밖으로
//     뻗는 획은 한 줄도 없다. 겹은 **축을 따라** 쌓이지 옆으로 안 퍼진다.
// 이 규칙 아래 다섯 겹을 얹는다(사용자가 부른 넷이 다 든다):
//   ㉠ **얼음빔** — 축을 따르는 굵은 심 + 흰 속심                (얼음빔)
//   ㉡ **얼음**   — 마디 결정 다섯. 앞 판보다 굵다               (얼음)
//   ㉢ **서리**   — 축을 감싸는 소매 발광 셋 + 냉기 한 자락       (서리)
//   ㉣ **결정**   — 축 위 마디에 앉는 육각 문장 둘                (얼음결정)
//   ㉤ **불티**   — 축을 따라 흐르는 반짝이. 「살아 있다」를 만든다
const IZL_SLEEVE = 8;         // 축에서 벗어나도 되는 최대(238칸) — 몸 반지름 미만
const IZL_SEEDS = 3;          // 소매 발광 수
/// 축을 따라 흐르는 반짝이 수 · **한 주기에 흐르는 바퀴 수**(정수라야 이어진다).
const IZL_GLINT = 3, IZL_GLT = 2;
/// 주기 처음에 얼어 있는가 — **엉김의 재료는 언 놈이다**(빙의 축 ③).
/// ⚠️ 넷째만 안 얼었다. L4 의 사건(「끊길 때 곁까지 굳는다」)이 저놈을 얼리고,
///   L5 는 그렇게 언 넷째를 **두 번째 이음**에서 사슬에 넣는다 — 사건이 잇는다.
const IZL_FRZ0 = [1, 1, 1, 0];
/// 끊길 때 냉기가 닿는 거리(238칸). 적2(36,−46) ↔ 적3(70,−84) 이 **51** 이라
/// 56 이면 문다 — L4 의 「끊길 때 굳는다」가 **넷째를 얼려** L5 의 사슬을 만든다.
/// ⚠️ 무대 위 실제 거리를 재서 고른 값이다. [IZS_NEAR] 이 52 로는 한 번도 안
///   터졌던 전례가 이 파일에 이미 적혀 있다 — 문턱은 무대에 맞춘다.
const IZL_NEAR = 56;

// ══════════════════════════════════════════════════════════════════════════
Object.assign(FX, {

// ── ① 빙판 ────────────────────────────────────────────────────────────────
IZrink(c, t, dt, W, H, st) {
  const cx = W / 2, cy = H / 2, SC = Math.min(W, H) / 238;
  const F = IZfoes(st, SC, IZR_FOE);
  const u = saw(t, IZR_PER), tau = u * IZR_PER;
  IZwrap(st, u);
  // ⚠️ 꼬리 램프는 **종료 마디 길이**로 잡는다 — 소멸(부서짐)까지 램프에
  //   걸리면 제일 볼 만한 마디가 반쯤 지워진다.
  const z = IZz(tau, IZR_PER, IZR_B[4]);
  const tp = tau * TAU / IZR_PER, th = tau * (TAU * 2 / 2.2) / IZR_PER;
  const wob = TAU * 2 * tau / IZR_PER;

  // 레벨 — **칸마다 사건 하나**. 크기는 다섯 칸이 같다.
  const TWO = atL(4), CRACK = atL(2), LIP = atL(3), SPIN = (LV === 5);
  const P = TWO ? IZR_TWO : IZR_ONE;
  const RR = (TWO ? 44 : IZR_R);
  // ⭐⭐ **다섯 마디** — 시전 → 생성(빛이 날아간다) → 발현 → 소멸 → 종료
  const B = IZbeat(tau, IZR_B);
  const fly = B.grow;                       // 빛덩이가 날아간 정도(0→1)
  //   `g` 마법진이 깔려 있는 정도(0→1→0). **발현 앞머리에서 펼쳐진다**
  const g = B.inCast || B.inGrow ? 0
          : (tau < B.t1 + IZR_UP ? IZss((tau - B.t1) / IZR_UP)
          : Math.max(0, 1 - IZseg(tau, B.t2, B.t3 - .04)));

  // ── 미끄러진다 — 판 안에 든 적이 바깥으로(L5 는 테를 따라) 밀린다 ───────
  for (const f of F) {
    let best = -1, bq = 9e9;
    for (let i = 0; i < P.length; i++) {
      const dx = f.ux + f.sx - P[i][0], dy = f.uy + f.sy - P[i][1];
      const q = Math.hypot(dx / RR, dy / (RR * IZR_SQ));
      if (q < bq) { bq = q; best = i; }
    }
    if (best < 0 || g < .5) continue;
    const dx = f.ux + f.sx - P[best][0], dy = f.uy + f.sy - P[best][1];
    const a = Math.atan2(dy / IZR_SQ, dx);
    // ⚠️ **턱**(L3~) — 테를 넘으려던 놈이 한 번 걸린다. 걸린 놈은 안 나간다.
    if (bq >= 1) { if (LIP) st.ev["trip" + F.indexOf(f)] = 1; continue; }
    // 금 위(0.34~0.78)는 더 빠르다 — L2 의 사건이 여기다.
    const fast = CRACK && bq > .34 && bq < .78;
    const v = (fast ? IZR_SPD2 : IZR_SPD) * dt;
    if (SPIN) { f.sx += -Math.sin(a) * v; f.sy += Math.cos(a) * v * IZR_SQ; }
    else { f.sx += Math.cos(a) * v; f.sy += Math.sin(a) * v * IZR_SQ; }
    // ⭐ **얼린다** — 빙의 축 ①. 판 위에 선 만큼 차고, 문턱을 넘으면 언다.
    IZchill(f, dt * IZR_FRZ);
    // 불티 — 밟는 자리에서 부스러기가 튄다(주기당 여섯 번, 시각이 표에서 나온다)
    const slot = Math.floor(tau / (IZR_PER / 6));
    const key = "chip" + F.indexOf(f) + "_" + slot;
    if (!st.ev[key]) { st.ev[key] = 1;
      IZchip(st, cx + (f.ux + f.sx) * SC, cy + (f.uy + f.sy) * SC + f.r * .6,
        F.indexOf(f) * 9.1 + slot * 3.3, 3,
        { b: tau, v: 26, vr: 20, r: 1.2, rr: 1.0, life: .34, g: 120 }); }
  }
  for (const f of F) f.hit = Math.max(0, f.hit - dt * 5);
  IZstand(F, SC, wob, z);

  // ── ㉣ 소멸 — 테가 **깨지며** 조각이 난다 (그냥 옅어지지 않는다) ──────────
  {
    const t3 = B.t2;
    if (tau >= t3 && !st.ev.gone) { st.ev.gone = 1;
      for (let i = 0; i < P.length; i++) {
        const px = cx + P[i][0] * SC, py = cy + P[i][1] * SC;
        for (let j = 0; j < 8; j++) {
          const a0 = (j + .5) / 8 * TAU;
          IZchip(st, px + Math.cos(a0) * RR * .8 * SC,
            py + Math.sin(a0) * RR * .8 * IZR_SQ * SC, i * 31.1 + j * 4.7, 1,
            { b: tau, a: a0, spread: .5, v: 22, vr: 14, r: 1.8, rr: 1.4,
              life: .40, g: 40 });
        }
      }
    }
  }

  // ══ 그리기 ═══════════════════════════════════════════════════════════════
  // ── ㉠ 시전 — 몸에서 냉기가 **모인다**. 「곧 온다」를 말하는 마디
  if (B.inCast) IZcastFx(c, cx, cy, B.cast, SC, 1, 3.1);
  // ── ㉡ 생성 — ⭐ **빛덩이가 날아가 자리에 꽂힌다**
  // ⚠️⚠️ 2026-08-28 사용자 판정: 「**스파이더맨 거미줄 날리듯이 날리지 말고**
  //   투사체나 **빛 그 자체를 날리는** 게 좋아 보임」. 앞 판은 몸에서 코어까지
  //   `IBline` 을 그었고 그것이 **거미줄**로 읽혔다 ⇒ **선을 지웠다.**
  //   꼬리는 그리는 것이 아니라 **뒤에 남는 반짝이**다([IZR_TRAIL]).
  if (B.inGrow) for (let i = 0; i < P.length; i++) {
    const sx = cx + P[i][0] * SC, sy = cy + P[i][1] * SC;
    const a = Math.atan2(P[i][1], P[i][0]);
    const ox = cx + Math.cos(a) * 18 * SC, oy = cy + Math.sin(a) * 18 * SC;
    const v = IZss(fly);
    const at = (w) => [ox + (sx - ox) * w,
      oy + (sy - oy) * w - Math.sin(Math.PI * w) * IZR_ARC * SC];
    const [x, y] = at(v);
    // 지목 — 닿기 전에 **자리가 먼저 보인다**
    IBroot(c, sx, sy, RR * SC * (.22 + .34 * fly), "frost", .34 * fly, IZR_SQ);
    IBrim(c, jagPoly(sx, sy, RR * SC * (.20 + .30 * fly), 9, 2.7 + i, 1.04, IZR_SQ),
      "frost", .46 * fly, 1.3 * SC);
    // 꼬리 — **점점이 남는 반짝이.** 선이 아니라 지나온 자리에 흩어진 것이다
    for (let j = 1; j <= IZR_TRAIL; j++) {
      const w = v - j * .085;
      if (w <= 0) continue;
      const [qx, qy] = at(w);
      IBspark(c, qx + (hash(i * 3.3 + j) - .5) * 5 * SC, qy + (hash(i * 7.7 + j) - .5) * 5 * SC,
        (3.4 - j * .45) * SC, "frost", (1 - j / (IZR_TRAIL + 1)) * .70, a + j);
    }
    // ⭐⭐ **빛 그 자체** — 2026-08-28 4차에 [IZbolt] 로 갈았다.
    //   앞 판은 발광 두 겹 + 결정 하나뿐이라 **덩어리 하나**였다. 투사체는
    //   **머리 · 몸통 · 꼬리 셋**으로 갈려야 하고, 머리에는 **문양**이 있어야
    //   그 스킬의 것이 된다(빙은 육각 결정). 꼬인 리본 둘 + 곧은 속도선 셋이
    //   붙고 색이 둘(`frost` + `snow`)이 된다.
    //   ⚠️ 꼬리는 여전히 **그리는 선이 아니다** — 가늘어지며 흩어지는 조각이다
    //     (「거미줄」 반려의 교훈은 그대로 지킨다).
    const ba = Math.atan2(y - oy, x - ox);
    // ⚠️⚠️ **도착 직전에는 커져야 한다.** 앞 판은 `(1 - .14*v)` 라 진행할수록
    //   14% 줄었다 — 원근으로는 맞지만 **착탄 순간이 제일 작아** 부딪힌 느낌이
    //   죽었다(사용자 「스티커가 날아가는 느낌」의 셋째 원인).
    //   ⇒ 앞 80% 는 그대로 줄고, **마지막 20% 에서 1.25배로 부푼다.**
    //     「멀어진다」가 「**다가온다**」로 뒤집히는 자리다.
    const near = IZcl((v - .80) / .20);
    // ⭐ **닿는 순간 눌린다**(스쿼시) — 부딪힌 것은 모양이 변한다. 나아가는
    //   축으로 납작해지고 옆으로 퍼진다. 이 한 항이 「스티커」를 「덩어리」로 만든다.
    const sq = IZss(IZcl((v - .88) / .12));
    c.save();
    c.translate(x, y); c.rotate(ba);
    c.scale(1 - .38 * sq, 1 + .34 * sq);
    c.rotate(-ba); c.translate(-x, -y);
    IZbolt(c, x, y, ba, IZR_BOLT * SC * (1 - .14 * v) * (1 + .25 * IZss(near)),
      IZR_BOLT * SC * 5.4, SC, .95, i * 6.1);
    c.restore();
  }
  // ── ⭐⭐⭐ ㉠ **착탄** — 빛덩이가 꽂히는 순간 **터진다** ─────────────────
  // ⚠️⚠️ 앞 판에는 이 블록이 **통째로 없었다.** 함수 전체에서 [IZchain] 도
  //   [IZboom] 도 한 번도 안 불렀다 — 파문 · 깨뜨리기 · 우박은 다 부르는데
  //   빙판만 빠져 있었다. 그래서 빛덩이가 도착하면 **그냥 마법진으로 바뀌었고**,
  //   도착을 알리는 사건이 하나도 없어 「스티커가 날아가는 느낌」이 됐다
  //   (2026-08-28 사용자 판정의 첫째 원인).
  // ⚠️ **작게** 터진다 — 여기가 크면 깨뜨리기(터뜨리는 자리)와 겹친다.
  //   빙판의 사건은 「터졌다」가 아니라 「**꽂혔다**」다.
  // ⚠️⚠️ **2026-08-28 7차 — 타격감이 두 번째로 반려됐다.** 6차에 [IZchain] 을
  //   넣었는데 「깨뜨리기와 겹친다」는 이유로 **일부러 작게**(판의 34%) 만들었고,
  //   그 결과 **타격이 안 보이게** 됐다.
  // ⭐ 답은 「크게」가 아니라 **「종류를 다르게」**다. 이 칸의 사건은 스스로 적어
  //   둔 대로 **「터졌다」가 아니라 「꽂혔다」**다 ⇒ **꽂힘의 언어로 세게** 만든다.
  //   그러면 깨뜨리기와 안 겹친다 — 저쪽은 **터짐**의 언어(다섯 겹 폭발)다.
  for (let i = 0; i < P.length; i++) {
    const s = tau - B.t1;
    if (s <= 0 || s > 1.10) continue;
    const px = cx + P[i][0] * SC, py = cy + P[i][1] * SC;
    // ① ⭐ **바닥이 방사로 갈라진다** — 「꽂혔다」의 제일 강한 신호. 길고 여러 갈래
    {
      const g = IZcl(s / .26);
      for (let j = 0; j < IZR_CRK; j++) {
        const a0 = (j + .5) / IZR_CRK * TAU + i * .7;
        const L = RR * SC * (.34 + .62 * hash(i * 7.3 + j * 2.9)) * IZss(g);
        // 금은 한 번 꺾인다 — 곧은 금은 「빛줄기」로 읽힌다
        const mx = px + Math.cos(a0) * L * .55, my = py + Math.sin(a0) * L * .55 * IZR_SQ;
        const a1 = a0 + (hash(i * 3.1 + j) - .5) * .5;
        IBline(c, [[px, py], [mx, my],
                   [mx + Math.cos(a1) * L * .45, my + Math.sin(a1) * L * .45 * IZR_SQ]],
          (1.6 - j * .04) * SC, "frost", (1 - IZcl((s - .26) / .5)) * .82 * z, 0);
      }
    }
    // ② **아주 얇고 빠른 충격 고리** — 넓지만 **얇아서 싸다**
    {
      const g = IZcl(s / .22);
      if (g < 1) IBrim(c, jagPoly(px, py, RR * SC * (.2 + 1.15 * IZss(g)), 15,
        i * 5.3, 1.03, IZR_SQ), "frost", (1 - g) * .90 * z, 1.0 * SC);
    }
    // ③ **밑동 서리 스커트** — 낮게 옆으로 밀린다. 무게를 만드는 항
    {
      const g = IZcl(s / .34);
      IBroot(c, px, py, RR * SC * (.16 + .40 * IZss(g)), "frost",
        (1 - g) * .52 * z, IZR_SQ * .48);
      IBrim(c, jagPoly(px, py, RR * SC * (.14 + .36 * IZss(g)), 13, i * 9.7, 1.10,
        IZR_SQ * .48), "frost", (1 - g) * .64 * z, 1.3 * SC);
    }
    // ④ 작은 연쇄 하나는 남긴다 — 「꽂힘」에도 **부딪힌 순간**은 있다
    IZchain(c, px, py, s, (RR * .30 + 6) * SC, SC, .70 * z, i * 15.7, IZR_SQ);
    // ⑤ 조각 — **자리마다 시차를 두고 더 뿌린다**(앞 판은 일곱뿐이라 적었다)
    if (!st.ev["land" + i]) { st.ev["land" + i] = 1;
      for (let w = 0; w < 3; w++)
        IZchip(st, px, py, i * 21.3 + w * 6.1, IZR_LAND,
          { b: tau + w * .045, v: 30 + w * 10, vr: 26, r: 1.5 - w * .2, rr: 1.2,
            life: .42 - w * .05, g: 70 + w * 30 });
    }
  }
  // ── ⭐⭐ ② 마법진 — **펼쳐진다 → 한기가 오른다 → 결정이 빛난다** ─────────
  for (let i = 0; i < P.length; i++) {
    const px = cx + P[i][0] * SC, py = cy + P[i][1] * SC, r = RR * SC * g;
    if (r < 1) continue;
    /// 마법진이 도는 각. L5 만 돈다(`SPIN`) — 그때만 `tp` 가 들어간다.
    /// ⚠️ `tp` 는 주기당 **정확히 한 바퀴**라 이음매가 없다.
    const rot = (SPIN ? tp : 0) + i * .42;
    // ㉠-1 밑판 — 마법진이 **떠 있지 않고 바닥에 깔렸다**를 만드는 두 겹.
    //   ⚠️ 앞 판은 여기에 `IBpane`(13각을 알파 .42 로 꽉 채움)을 썼다. 그것이
    //     이 칸에서 제일 넓은 면이고 **화면을 「얼음 웅덩이」로 만든 장본인**이다.
    //     지금은 알파를 반으로 내려 **바탕**으로만 두고, 눈에 들어오는 것은
    //     위에 얹는 **획**이 되게 한다 — 면적을 안 늘리고 화려해지는 길이다.
    IBroot(c, px, py, r * 1.00, "frost", .30 * g * z, IZR_SQ);
    IBpane(c, jagPoly(px, py, r * .90, 13, 3.1 + i * 5, 1.03, IZR_SQ),
      "frost", .46 * g * z, 4.3 + i, 1.2 * SC);
    // ㉠-2 **각진 고리** — 안에서 밖으로 차례로 열린다. 이것이 「펼쳐진다」다.
    //   ⚠️ 타원이 아니라 정n각형이다 — 결빙(`IBrune`)과 갈리는 획이 이것뿐이다.
    //   ⚠️⚠️ **밝기에 층이 있어야 마법진으로 읽힌다.** 첫 판은 고리 셋 · 살 여섯 ·
    //     금 다섯 · 이빨 열둘이 **전부 같은 흰 심**이라, 크게 띄워 보니 마법진이
    //     아니라 **흰 실뭉치**였다(2026-08-28 갈무리 판정). 그래서 획마다 자리를
    //     정한다: 바깥 테가 제일 밝고(경계) · 안 고리는 절반 · 살은 그 절반.
    for (let k = 0; k < IZR_RING.length; k++) {
      const op = IZss(IZcl((g - k * IZR_RGAP) / (1 - IZR_RGAP * 2)));
      if (op < .02) continue;
      const rr = r * IZR_RING[k] * op;
      if (k === 2) {   // 바깥 테 — **경계**. 하나만 밝다
        IBrim(c, IZpoly(px, py, rr, IZR_SIG * 2, rot, IZR_SQ),
          "frost", .90 * g * z, 2.0 * SC);
      } else {         // 안 고리 둘 — 바탕. 흰 심을 안 세운다
        IBline(c, IZpoly(px, py, rr, IZR_SIG, rot + k * .52, IZR_SQ),
          1.2 * SC, "frost", (k ? .34 : .46) * g * z, 0);
      }
    }
    // ㉠-3 **결정 살** — 안 고리에서 테까지 여섯. 마법진의 결이다(가늘고 어둡다)
    for (let j = 0; j < IZR_SIG; j++) {
      const a0 = rot + j * TAU / IZR_SIG;
      IBline(c, [[px + Math.cos(a0) * r * .34, py + Math.sin(a0) * r * .34 * IZR_SQ],
                 [px + Math.cos(a0) * r * .86, py + Math.sin(a0) * r * .86 * IZR_SQ]],
        1.0 * SC, "frost", .34 * g * z, 0);
    }
    // ㉠-4 **중심 문장** — 육각 눈결정 하나. ⭐ 이 한 획이 「얼음의 마법진」을
    //   못 박는다(결빙의 잔글씨 띠 자리에 이것이 선다).
    IBflake(c, px, py, r * .30 * g, rot * .5, "frost", .78 * g * z, 1.3 * SC, IZR_SQ);
    // ㉡ **한기가 오른다** — 판 위로 솟는 김. ⭐ 위로 흐르는 것이 이 마디다
    //   ⚠️ 첫 판은 34칸짜리 곧은 선이라 **더듬이**처럼 보였다. 김은 짧고 흐리고
    //     끝이 풀려야 김이다 ⇒ 길이를 [IZR_VAPH] 로 줄이고 흰 심을 뺐다.
    //   ⚠️ 위상은 주기에서 파생하고 바퀴 수가 정수([IZR_VAPT])라 이음매가 없다.
    for (let j = 0; j < IZR_VAP; j++) {
      const ph = (tau / IZR_PER * IZR_VAPT + j / IZR_VAP) % 1;
      const a0 = j * TAU / IZR_VAP + i * 1.7;
      const d = r * (.24 + .50 * hash(j * 3.7 + i));
      const bx = px + Math.cos(a0) * d, by = py + Math.sin(a0) * d * IZR_SQ;
      const rise = ph * IZR_VAPH * SC, al = Math.sin(Math.PI * ph) * .58 * g * z;
      if (al < .02) continue;
      // 김 한 자락 — **몸통은 안개** · 그 안에 뜬 조각 하나 · 밑에 흐린 꼬리.
      //   셋이 있어야 「오른다」가 되고, 안개만 있으면 그냥 뿌옇다.
      const vx = bx + Math.sin(a0 * 2.1) * 3 * SC, vy = by - rise;
      IBmist(c, vx, vy, (7.0 + 3.0 * hash(j * 5.1)) * SC * (1 - ph * .25),
        j * 2.3 + i, al * 1.5, .9);
      IBshard(c, vx, vy, (1.8 + 1.0 * hash(j * 8.3)) * SC * (1 - ph * .5),
        a0 + ph * 1.2, "frost", al * .85, .5);
      IBline(c, [[bx, by - rise * .28], [vx, vy]],
        1.1 * SC * (1 - ph * .5), "frost", al * .40, 1);
    }
    // ㉢ **결정이 빛난다** — 안 고리 위에 결정 여섯이 서고, **차례로** 밝아진다
    //   ⚠️ 개수를 늘리는 대신 **하나가 돌아가며 밝아진다** — 면적이 안 는다.
    //   ⚠️ 자리를 두 번 옮겼다. `.66`(테 근처에 흩어짐 = 잎사귀) → `.58`(중심
    //     문장과 겹쳐 뭉개짐) → **살 끝(`.86`)**. 살이 결정에서 끝나야 마법진의
    //     결이 「무엇을 향해 뻗었나」를 말하고, 결정도 흩어진 것이 아니라
    //     **자리를 가진 것**이 된다.
    for (let j = 0; j < IZR_GEM; j++) {
      const a0 = rot + j * TAU / IZR_GEM;
      const d = r * .86;
      const gx = px + Math.cos(a0) * d, gy = py + Math.sin(a0) * d * IZR_SQ;
      // 숨 — 주기당 정수 바퀴(`tp`)라 이음매가 없다. 위상이 결정마다 어긋난다
      const br = .52 + .48 * Math.sin(tp - j * TAU / IZR_GEM);
      const rr = (7.0 + 3.4 * br) * SC * g;
      IBroot(c, gx, gy, rr * 1.7, "frost", (.20 + .34 * br) * g * z, .40);
      ICiceBody(c, tp, gx, gy - rr * .34, rr, a0, j * 4.7 + i * 9.1, "frost",
        (.60 + .38 * br) * g * z,
        { arms: 6, branch: .16, wid: .26, tap: .50, core: .58, vary: .24, turn: 0 });
      if (br > .80) IBspark(c, gx, gy - rr * .60, rr * 1.0, "frost",
        (br - .80) * 5 * g * z, a0 + .4);
    }
    // ③ 금 — L2 의 사건. 심에서 **안 고리까지** 다섯 줄. 곁가지가 난다
    // ⚠️ 금은 「빨라지는 자리」를 말하는 유일한 획이다. 테까지 그으면 고리와
    //   섞여 실뭉치가 되므로 **안 고리 안**에서 끝낸다.
    if (CRACK) for (let j = 0; j < 5; j++) {
      const a0 = j * TAU / 5 + i * .7 + .4 + (SPIN ? tp : 0);
      const pt = [];
      for (let s = 0; s <= 4; s++) {
        const d = r * (.14 + .13 * s), a1 = a0 + (hash(j * 4.7 + s * 2.3) - .5) * .55;
        pt.push([px + Math.cos(a1) * d, py + Math.sin(a1) * d * IZR_SQ]);
      }
      IBline(c, pt, 1.8 * SC, "frost", .62 * g * z, 0);
      // 곁가지 — 금이 갈라진다. 「빨라지는 띠」가 면으로 읽히게 하는 층
      const m = Math.floor(pt.length / 2), a2 = a0 + (hash(j * 9.1) - .5) * 1.6;
      IBline(c, [pt[m], [pt[m][0] + Math.cos(a2) * r * .16,
                         pt[m][1] + Math.sin(a2) * r * .16 * IZR_SQ]],
        1.2 * SC, "frost", .44 * g * z, 0);
    }
    // ④ 턱 — L3 의 사건. 테에 **결정 이빨**이 서서 「걸린다」가 보인다
    //   ⚠️ 이빨은 **바깥으로만** 선다 — 안쪽으로 그으면 살·금과 겹쳐 실뭉치가 된다.
    if (LIP) for (let j = 0; j < IZR_SIG * 2; j++) {
      const a0 = rot + (j + .5) * TAU / (IZR_SIG * 2);
      const tx = px + Math.cos(a0) * r * .94, ty = py + Math.sin(a0) * r * .94 * IZR_SQ;
      IBneedle(c, tx, ty, a0, r * .13, r * .045, j * 3.1 + i,
        "frost", .78 * g * z, { tip: .22, slant: .5, mos: 1, w: .9 * SC });
    }
    // ⑤ 도는 흐름 — L5 의 사건. 밀리는 방향이 바깥이 아니라 **테를 따라** 돈다
    if (SPIN) for (let j = 0; j < 5; j++) {
      const a0 = tp + j * TAU / 5, pt = [];
      for (let s = 0; s <= 4; s++) {
        const a1 = a0 + s * .13, d = r * (.52 + .06 * s);
        pt.push([px + Math.cos(a1) * d, py + Math.sin(a1) * d * IZR_SQ]);
      }
      IBline(c, pt, 1.7 * SC, "frost", .55 * g * z, 0);
    }
  }
  // ⑥ 잔상 — **미끄러진 자국.** 밟은 자리에서 지금 자리까지 흰 선이 남는다
  for (const f of F) {
    const d = Math.hypot(f.sx, f.sy); if (d < 2) continue;
    IBline(c, [[cx + f.ux * SC, cy + f.uy * SC],
               [cx + (f.ux + f.sx) * SC, cy + (f.uy + f.sy) * SC]],
      2.0 * SC, "frost", Math.min(1, d / 14) * .42 * z, 0);
  }
  // ⑦ 걸려 넘어진 자국 — 턱에 걸린 놈 발밑의 짧은 호
  if (LIP) for (let i = 0; i < F.length; i++) if (st.ev["trip" + i]) {
    const f = F[i];
    IBrim(c, jagPoly(cx + f.ox, cy + f.oy + f.r * .7, f.r * .9, 7, 5.1, 1.02, .40),
      "frost", .50 * z, 1.8 * SC);
  }
  // ── ㉤ 종료 — 마지막 자국이 스러진다. **소멸과 다른 그림**이다(조각이 없다)
  if (B.inRest) for (let i = 0; i < P.length; i++)
    IZrestFx(c, cx + P[i][0] * SC, cy + P[i][1] * SC, B.rest, RR * SC * .82,
      SC, 1, 4.7 + i * 3.3);
  IZchips(c, st, tau, SC, z);
  IZmarks(c, tp, cx, cy, F, SC, z);
  hero(c, th, cx, cy);
},

// ── ③ 우박 ────────────────────────────────────────────────────────────────
IZhail(c, t, dt, W, H, st) {
  const cx = W / 2, cy = H / 2, SC = Math.min(W, H) / 238;
  const F = IZfoes(st, SC, IZH_FOE);
  const u = saw(t, IZH_PER), tau = u * IZH_PER;
  IZwrap(st, u);
  const z = IZz(tau, IZH_PER, IZH_B[4]);
  const tp = tau * TAU / IZH_PER, th = tau * (TAU * 2 / 2.2) / IZH_PER;
  const wob = TAU * 2 * tau / IZH_PER;
  // ⭐⭐ 다섯 마디 — 시전 → 생성(예고가 퍼진다) → 발현(쏟아진다) → 소멸 → 종료
  const B = IZbeat(tau, IZH_B);

  // 레벨 — 수(L2) · 튀는 조각(L3) · 큰 알(L4) · 마당 한 장(L5)
  const N = IZH_N[LV - 1];
  const BIG = IZH_BIG[LV - 1];
  const SPLIT = atL(3), SHEET = (LV === 5);
  const spot = (i) => [-88 + 176 * hash(i * 4.3 + 1.1), -100 + 120 * hash(i * 6.7 + 2.9)];

  // ── ㉠ 시전 — 머리 위에 **냉기 구름 고리**가 모인다. 「하늘이 준비한다」
  if (B.inCast) {
    IZcastFx(c, cx, cy, B.cast, SC, 1, 5.7);
    const m = IZss(B.cast);
    IBrim(c, jagPoly(cx, cy - 96 * SC, 92 * SC * (1.25 - .35 * m), 15, 8.3, 1.03, .30),
      "frost", .40 * m, 1.5 * SC);
    for (let j = 0; j < 5; j++) {
      const a0 = (j + .5) / 5 * TAU;
      IBmist(c, cx + Math.cos(a0) * 62 * SC, cy - 96 * SC + Math.sin(a0) * 20 * SC,
        (14 + 6 * hash(j * 3.7)) * SC * m, j * 2.9, .50 * m, .8);
    }
  }
  // ── ㉡ 생성 — 예고가 **마당에 쫙 퍼지고** 하늘에서 **알이 맺힌다**
  // 🔴🔴 **사용자 판정(2026-08-29)**: 「우박이 다 떨어지고 나서 갑자기 **뭐 이상한
  //   게 생겼다가 사라지는**?? 이거 확인 한번 해 봐라」
  // ⚠️⚠️ **원인은 이 마디였다** — 화면을 0.05초마다 훑어 찾았다.
  //   이 마디가 **눈에 보이는 화소 31개**(열두 칸 중 꼴찌)였고, 그래서 주기
  //   **0.40~1.15초 0.75초 동안 화면이 통째로 비었다**(주기의 18%).
  //   ⇒ 그 빈 창에 **적 인형만 남는다.** `vfx.js` 의 [drawFoes] 는 서리가 걷히면
  //     몸을 `#16101C`(거의 검정)로 칠하고 눈만 `#FF2D55` 로 남긴다 — 그것이
  //     사용자가 본 「톱니 테두리에 빨간 눈 둘」이다.
  //   🔴 **적은 안 고친다** — [drawFoes] 는 전 속성 공용이고 잘못한 것이 없다.
  //     **빈 마디를 세우는 것**이 고침이다.
  // ⚠️ 앞 판이 아주 안 그린 것은 아니다 — [IBroot] 부드러운 발광을 N 개 깔았다.
  //   그런데 그건 **연해서 안 걸린다**(알파 .34 의 방사 그라디언트). 「그렸다」와
  //   「보인다」는 다르다 — **문턱을 정해 재야** 그 둘이 갈린다.
  if (B.inGrow) {
    const m = IZss(B.grow);
    for (let i = 0; i < N; i++) {
      const [ux, uy] = spot(i);
      const R = IZH_R * (i < BIG ? IZH_BIGR : 1);
      const w = IZcl(m * 2.2 - i / N * 1.2);
      if (w < .02) continue;
      const gx = cx + ux * SC, gy = cy + uy * SC;
      IBroot(c, gx, gy, R * SC * (.4 + .7 * w), "frost", .34 * w, .40);
      // ⭐ **각진 예고 테** — 발광이 아니라 **획**이라 눈에 걸린다. 그리고
      //   오므라들며 「곧 여기」를 말한다(발현의 겨눔 테와 같은 말을 미리 한다).
      IBrim(c, jagPoly(gx, gy, R * SC * (2.1 - .9 * w), 7, i * 1.9, 1.05, .40),
        "frost", .52 * w, 1.1 * SC);
    }
    // ⭐⭐ **하늘에서 알이 맺힌다** — 「생성 = 공격이 닿기 전」의 정의 그대로다.
    //   앞 판은 이 마디에 **투사체가 아예 없어서** 「예고만 있고 물건이 없는」
    //   마디였다. 알이 구름 고리에 맺혔다가 다음 마디에 떨어지면 이어진다.
    // ⚠️ 하늘 알은 **작고 여럿**이다 — 넓은 겹을 안 쓴다.
    const NS = Math.min(N, 10 + Math.round(N * .18));
    for (let j = 0; j < NS; j++) {
      const a0 = (j + .5) / NS * TAU;
      const rx = (34 + 52 * hash(j * 5.1)) * SC, ry = 17 * SC;
      const bx = cx + Math.cos(a0) * rx, by = cy - 96 * SC + Math.sin(a0) * ry;
      const g = IZcl(m * 1.9 - j / NS * .9);
      if (g < .02) continue;
      const br = IZH_R * SC * (.30 + .62 * g);
      IBshard(c, bx, by, br, a0 * .4, "frost", .88 * g, 1);
      IBflake(c, bx, by, br * 1.15, a0 * .7, "frost", .62 * g, .8 * SC, 1);
      gAdd(c, (cc) => IBspark(cc, bx, by, br * .9, "snow", .60 * g, a0));
    }
    // 구름 고리가 **버티고 있다** — 시전에서 모인 것이 사라지지 않는다
    IBrim(c, jagPoly(cx, cy - 96 * SC, 92 * SC * (.90 + .06 * m), 15, 8.3, 1.03, .30),
      "frost", .34, 1.3 * SC);
  }
  // ⭐⭐ **아직 안 떨어진 알은 하늘에 남아 있다** — 발현 앞머리를 잇는 자리다.
  // ⚠️⚠️ 생성을 채우고 다시 재니 빈 창이 0.75 → 0.45초로 줄었을 뿐 **안 없어졌다**.
  //   남은 자리는 **발현 앞머리**였다 — 첫 알이 태어나는 것이 `t1`(0.70)인데
  //   닿는 것은 `TELE+FALL`(0.52) 뒤인 **1.22초**라, 그 사이에 하늘도 비고 땅도
  //   아직 안 맞았다. ⇒ **기다리는 알을 하늘에 그대로 둔다.** 쏟아지는 동안
  //   구름이 **비어 가는 것**이 보여야 「하늘에서 온다」가 끝까지 산다.
  if (B.inHit) {
    const doneN = IZcl((tau - B.t1) / IZH_SPREAD);   // 얼마나 나갔나
    const NS = Math.min(N, 10 + Math.round(N * .18));
    const left = 1 - doneN;
    if (left > .02) {
      for (let j = 0; j < NS; j++) {
        const a0 = (j + .5) / NS * TAU;
        const g = IZcl(left * 1.6 - j / NS * .6);
        if (g < .02) continue;
        const rx = (34 + 52 * hash(j * 5.1)) * SC, ry = 17 * SC;
        const bx = cx + Math.cos(a0) * rx, by = cy - 96 * SC + Math.sin(a0) * ry;
        const br = IZH_R * SC * (.30 + .62 * g);
        IBshard(c, bx, by, br, a0 * .4 + tp * .2, "frost", .82 * g * z, 1);
        IBflake(c, bx, by, br * 1.15, a0 * .7, "frost", .56 * g * z, .8 * SC, 1);
      }
      IBrim(c, jagPoly(cx, cy - 96 * SC, 92 * SC * (.90 + .10 * left), 15, 8.3, 1.03, .30),
        "frost", .30 * left * z, 1.3 * SC);
    }
  }

  let live = 0;
  for (let i = 0; i < N; i++) {
    const born = B.t1 + i / N * IZH_SPREAD, s = tau - born;
    if (s < 0) continue;
    const big = i < BIG, R = IZH_R * (big ? IZH_BIGR : 1);
    const [ux, uy] = spot(i);
    const x = cx + ux * SC, y = cy + uy * SC;
    const tImp = IZH_TELE + IZH_FALL;
    // ① 예고 — **바닥 그림자.** 결빙의 포탈과 갈리는 자리가 여기다
    if (s < tImp) {
      const m = IZcl(s / IZH_TELE);
      IBroot(c, x, y, R * SC * (.5 + .9 * m), "frost", .40 * m * z, .40);
      // 겨눔 테 — 예고가 **오므라든다**. 「곧 온다」를 말하는 유일한 획이다
      IBrim(c, jagPoly(x, y, R * SC * (1.9 - 1.0 * m), 7, i * 1.9, 1.05, .40),
        "frost", .42 * m * z, 1.1 * SC);
    }
    // ② 알이 떨어진다 — **낙하 빔**이 꼬리를 만든다
    // ⚠️ 앞 판의 꼬리는 알 지름의 2.6배라 화면에서 안 보였다 — 「떨어진다」가
    //   「생겼다」로 읽혔다. [IZH_BEAM] 으로 늘리고 흰 속심을 한 겹 더 얹는다.
    if (s >= IZH_TELE && s < tImp) {
      const v = IZcl((s - IZH_TELE) / IZH_FALL), yy = y - (1 - v * v) * 150 * SC;
      // ⚠️ 넓은 획 하나로 그으면 **흰 막대**가 된다(첫 판이 그랬다). 꼬리는
      //   **짧고 굵은 것 + 길고 가는 것** 둘로 나눠야 「빠르게 지나갔다」가 된다.
      IBline(c, [[x, yy - R * SC * IZH_BEAM * .34], [x, yy]], R * SC * .30, "frost",
        .30 * z, 1);
      IBline(c, [[x, yy - R * SC * IZH_BEAM], [x, yy]], R * SC * .10, "frost",
        .64 * z, 0);
      ICiceBody(c, tp, x, yy, R * SC, 0, i * 3.1, "frost", .95 * z,
        { arms: 6, branch: .10, wid: .34, tap: .40, core: .70, vary: .18, turn: 0 });
      // ⭐ **알의 속심** — [ICiceBody] 는 덮어 칠하기라 알 여럿이 겹쳐도 안
      //   밝아진다. 가산 반짝이 하나를 심으면 마당에 알이 스물둘 떨어질 때
      //   **겹치는 자리가 살아난다** — 「우박이 쏟아진다」가 되는 자리다.
      //   ⚠️ 작고 여럿이다(반지름이 알의 반). 넓은 블룸을 알마다 깔면 그날로
      //     비싼 잉크가 스물두 겹이 된다.
      IBspark(c, x, yy, R * SC * .52, "frost", .70 * z, tp + i);
      if (big) IZseal(c, x, yy, R * SC * .62, SC, .55 * z);
      live++;
    }
    // ③ 깨진다 — **얼음 폭발**([IZboom])이 여기서 난다. 깨뜨리기와 **같은 함수**다
    if (s >= tImp && s < tImp + IZH_BRK + .16) {
      const v = IZcl((s - tImp) / (IZH_BRK + .16));
      // ⭐⭐ 「터지고 터지는」 — 낱개 착탄도 **한 번 펑이 아니다**([IZchain]).
      //   알이 서른~여든여덟 개라 시차 셋이 서로 어긋나며 마당 전체가 계속 터진다
      IZchain(c, x, y, s - tImp, R * SC * (big ? 2.6 : 1.7), SC,
        (big ? 1 : .78) * z, i * 2.3, .52);
      if (!st.ev["brk" + i]) { st.ev["brk" + i] = 1;
        IZchip(st, x, y, i * 11.3, SPLIT ? 8 : 5,
          { b: tImp + born, v: SPLIT ? 46 : 24, vr: SPLIT ? 34 : 18,
            r: 1.4, rr: 1.2, life: .40, g: SPLIT ? 60 : 150 });
        // ⭐ **얼린다** — 빙의 축 ①. 알 하나가 스치면 몫이 차고, 세 번이면 언다.
        //   ⚠️ 이것이 우박을 「비가 온다」에서 **「깨뜨리기의 밥을 만든다」**로
        //     바꾸는 한 줄이다(사용자: 「빙결 효과 — 깨트리기와 연쇄 작용」).
        for (const f of F)
          if (Math.hypot(f.ux - ux, f.uy - uy) - f.ru < IZH_NEAR * (big ? 1.5 : 1)) {
            f.hit = 1; IZchill(f, IZH_FRZ * (big ? 1.6 : 1));
          }
        // L3 — 옆으로 튄 조각이 **더 멀리 있는** 놈까지 스친다
        if (SPLIT) for (const f of F)
          if (Math.hypot(f.ux - ux, f.uy - uy) - f.ru < 34) {
            f.hit = 1; IZchill(f, .22);
          }
      }
    }
    // ④ 잔상 — **미끄러운 자국.** 큰 알은 크고 오래 남는다
    // ⚠️ 처음엔 알파 .30 의 발광 하나였는데 **화면에서 거의 안 보였다** — 한
    //   주기의 대부분을 자국이 차지하는데 그 자국이 안 보이면 칸이 빈 것과
    //   같다(갈무리로 확인). ⇒ 진하기를 올리고 **바닥에 언 조각을 얹었다.**
    if (s >= tImp) {
      const w = IZcl((s - tImp) / (IZH_MARK * (big ? 1.5 : 1)));
      if (w < 1) {
        const rr = R * SC * (1.9 + .6 * w);
        IBroot(c, x, y, rr, "frost", .46 * (1 - w) * z, .40);
        IBrim(c, jagPoly(x, y, rr * .92, 11, i * 5.7, 1.02, .40), "frost",
          .52 * (1 - w) * z, 1.5 * SC);
        // 자국에 남은 얼음 조각 셋 — 「젖었다」가 아니라 **「얼었다」**로 읽힌다
        for (let q = 0; q < 3; q++) {
          const a0 = (q + .5) / 3 * TAU + i;
          IBshard(c, x + Math.cos(a0) * rr * .52, y + Math.sin(a0) * rr * .52 * .40,
            (1.6 + 1.0 * hash(i * 3.1 + q)) * SC, a0, "frost",
            (1 - w) * .70 * z, .48);
        }
      }
    }
  }
  // ⑤ 마당 한 장 — L5 의 사건. 자국들이 이어져 **한 장**이 된다
  if (SHEET) {
    const m = IZss(IZseg(tau, B.t1 + IZH_SPREAD * .30, B.t1 + IZH_SPREAD * .75))
            * (1 - IZseg(tau, B.t2, B.t3));
    IBroot(c, cx, cy - 44 * SC, 104 * SC, "frost", .16 * m * z, .44);
    IBrim(c, jagPoly(cx, cy - 44 * SC, 100 * SC, 17, 9.3, 1.02, .44), "frost",
      .26 * m * z, 1.4 * SC);
  }
  // ── ㉤ 종료 — 마당에 김만 남는다. **소멸(부서짐)과 다른 그림**이다
  if (B.inRest) IZrestFx(c, cx, cy - 44 * SC, B.rest, 74 * SC, SC, 1, 2.9);
  // ⚠️ **언 놈은 안 녹는다**([IZthaw]) — 그래야 「깨뜨리기의 밥」이 주기 내내 남는다.
  for (const f of F) { IZthaw(f, dt * .5); f.hit = Math.max(0, f.hit - dt * 5); }
  IZstand(F, SC, wob, z);
  IZchips(c, st, tau, SC, z);
  IZmarks(c, tp, cx, cy, F, SC, z);
  hero(c, th, cx, cy);
  void live;
},

// ── ⑤ 깨뜨리기 ────────────────────────────────────────────────────────────
IZshatter(c, t, dt, W, H, st) {
  const cx = W / 2, cy = H / 2, SC = Math.min(W, H) / 238;
  const F = IZfoes(st, SC, IZS_FOE);
  const u = saw(t, IZS_PER), tau = u * IZS_PER;
  if (IZwrap(st, u)) for (let i = 0; i < F.length; i++) F[i].frz = IZS_FRZ0[i];
  for (let i = 0; i < F.length; i++) if (F[i].frz) F[i].pv = 2.4;
  const z = IZz(tau, IZS_PER, IZS_B[4]);
  const tp = tau * TAU / IZS_PER, th = tau * (TAU * 2 / 2.2) / IZS_PER;
  const wob = TAU * 2 * tau / IZS_PER;

  // 레벨 — 남는 조각(L2) · 연쇄(L3) · 곁을 굳힘(L4) · 셋을 한 번에 + 고리(L5)
  const KEEP = atL(2), CHAIN = atL(3), CHILL = atL(4), THREE = (LV === 5);
  const TGT = THREE ? [0, 2, 3] : [0];
  // ⭐⭐ 다섯 마디 — 시전 → 생성(고드름이 난다) → 발현(폭발) → 소멸 → 종료
  const B = IZbeat(tau, IZS_B);
  const tHit = B.t1;

  // ── ⭐⭐⭐ **얼음정령이 시전한다**(2026-08-28 9차) ──────────────────────
  // 사용자: 「깨트리기도 **'빙정령'이 시전하는 걸로**」.
  // ⚠️⚠️ **정령은 캐릭터당 하나**라 엉김과 **같은 상수**를 쓴다([IZE_ORB] ·
  //   [IZE_R] · [IZE_FORM] · [IZpose]). 칸마다 손으로 쓰면 **화면에 정령이 둘로
  //   보인다** — 두 칸이 같은 개체라는 것이 그림으로 읽혀야 한다.
  // ⚠️ 자세는 **깨뜨리기의 것**이다([IZ_BREAK]) — 조각이 앞으로 한 줄로 모여
  //   쐐기가 되고 몸이 더 기운다. 엉김(두 갈래로 벌어짐)과 **다른 그림**이라야
  //   「지금 무엇을 한다」가 읽힌다.
  // ⚠️⚠️ **그림 자체는 한 획도 안 건드렸다** — 이 칸은 합격 받은 칸이다.
  //   바뀐 것은 **시전자가 어디인가** 하나뿐이다.
  // ⚠️⚠️⚠️ **시전자를 옮기는 일은 마디 하나가 아니라 다섯 항이다**(2026-08-28 10차).
  //   9차는 [IZcastFx] 한 줄만 정령으로 옮기고 **궤적을 안 옮겼다** — 그래서
  //   마법진만 정령 발치에 서고 **고드름은 캐릭터에서 날아갔다**(사용자가 짚었다).
  //   옮겨야 하는 항은 이 다섯이고, 하나라도 남으면 캐릭터가 다시 시전자가 된다:
  //     ① **각** `a`      — 정령 → 표적 (캐릭터 → 표적이 아니다)
  //     ② **거리** `d`    — 정령 → 표적
  //     ③ **날의 자리**   — 총구 [IZS_MUZ] 에서 표적까지, 원점이 `SPX`·`SPY`
  //     ④ **뒤 반짝이**   — 같은 궤적 위에 남으므로 같은 원점
  //     ⑤ **베인 선**     — 자국이 가리키는 쪽이 곧 「누가 쐈나」다
  //   ⚠️ 속도선 · 앞끝 심은 `nx`·`ny` 에 매달려 있어 ③ 을 고치면 같이 따라온다.
  const [SPX, SPY] = IZspiritAt(u, cx, cy, SC);
  const AIM = B.inCast ? IZss(B.cast)
    : (tau < B.t3 ? 1 : 1 - IZss(IZseg(tau, B.t3, B.t4)));
  const SPFACE = (() => {
    const f0 = F[TGT[0]];
    return Math.atan2(cy + f0.uy * SC - SPY, cx + f0.ux * SC - SPX);
  })();

  for (const f of F) f.hit = Math.max(0, f.hit - dt * 6);
  // ── ㉠ 시전 — **정령 발치**에서 냉기와 마법진이 난다(캐릭터가 아니다)
  if (B.inCast) IZcastFx(c, SPX, SPY, B.cast, SC, 1, 7.9);

  // ── 깨진다 — 시각이 오면 표적이 조각난다 ────────────────────────────────
  for (let ti = 0; ti < TGT.length; ti++) {
    const idx = TGT[ti], f = F[idx];
    if (tau < tHit) continue;
    const key = "brk" + idx;
    if (!st.ev[key]) { st.ev[key] = 1;
      f.hit = 1; f.frz = 0; f.pv = 0;
      IZchip(st, cx + f.ux * SC, cy + f.uy * SC, idx * 17.3, IZS_CHIP,
        { b: tHit, v: 44, vr: 34, r: 1.8, rr: 1.6, life: IZS_FRAG, g: 70 });
      // 스플래시 — **바닥으로 낮게** 흩어지는 한 벌. 위로 튀는 조각과 **면이
      // 달라야** 겹이 겹으로 읽힌다(중력이 크고 느리다)
      IZchip(st, cx + f.ux * SC, cy + f.uy * SC + f.r * .6, idx * 29.7, 7,
        { b: tHit, v: 22, vr: 16, r: 2.4, rr: 1.8, life: IZS_FRAG * 1.3, g: 24 });
      // L3 — **연쇄.** 곁의 언 놈이 0.12초 뒤에 같이 깨진다
      if (CHAIN) for (let j = 0; j < F.length; j++) {
        const g2 = F[j];
        if (j === idx || !g2.frz) continue;
        if (Math.hypot(g2.ux - f.ux, g2.uy - f.uy) > IZS_NEAR) continue;
        st.ev["ch" + j] = tHit + IZS_CHAIN;
        st.ev["cf" + j] = idx;          // 어디서 옮겨 붙었나 — 빔이 이 값을 읽는다
      }
      // L4 — 깨는 냉기가 **안 언 놈을 굳힌다**. 다음 깨뜨림의 밥이 된다
      if (CHILL) for (let j = 0; j < F.length; j++) {
        const g2 = F[j];
        if (g2.frz || Math.hypot(g2.ux - f.ux, g2.uy - f.uy) > IZS_NEAR) continue;
        g2.frz = 1; g2.pv = 2.4;
      }
    }
  }
  // 연쇄로 깨지는 놈 — 시각이 되면 조각난다
  for (let j = 0; j < F.length; j++) {
    const at = st.ev["ch" + j];
    if (!at || st.ev["chd" + j] || tau < at) continue;
    st.ev["chd" + j] = 1;
    F[j].frz = 0; F[j].pv = 0; F[j].hit = 1;
    IZchip(st, cx + F[j].ux * SC, cy + F[j].uy * SC, j * 23.9, IZS_CHIP2,
      { b: at, v: 40, vr: 30, r: 1.6, rr: 1.4, life: IZS_FRAG, g: 70 });
    IZchip(st, cx + F[j].ux * SC, cy + F[j].uy * SC + F[j].r * .6, j * 31.1, 5,
      { b: at, v: 20, vr: 14, r: 2.2, rr: 1.6, life: IZS_FRAG * 1.3, g: 24 });
  }
  IZstand(F, SC, wob, z);

  // ══ 그리기 ═══════════════════════════════════════════════════════════════
  for (let ti = 0; ti < TGT.length; ti++) {
    const idx = TGT[ti], f = F[idx];
    const tx = cx + f.ux * SC, ty = cy + f.uy * SC;
    // ⚠️⚠️ **각도도 거리도 정령에서 잰다.** 앞 판은 `atan2(f.uy, f.ux)` 라
    //   **캐릭터 원점**에서 잰 각이었고, 그래서 고드름이 정령을 지나쳐 캐릭터에서
    //   날아갔다. 시전자가 옮겨 가면 **궤적의 원점도 같이** 옮겨 가야 한다.
    // ⚠️ 정령이 표적 코앞으로 떠올 수도 있으므로 하한을 둔다 — 안 두면 `dd` 가
    //   총구보다 짧아져 날이 **뒤로** 난다.
    const a = Math.atan2(ty - SPY, tx - SPX);
    const d = Math.max(IZS_MUZ + 8, Math.hypot(tx - SPX, ty - SPY) / SC);
    // ① 겨눔 — 언 놈 위에 표식이 뜬다. **고를 수 있다**가 여기서 읽힌다
    if (B.inCast) {
      const m = IZcl(B.cast * 1.4);
      IBflake(c, tx, ty - f.r * 1.4, f.r * (.5 + .4 * m), tp * .05, "frost", .8 * m * z, 1.0 * SC);
      // 겨눔 테 — 표적 발밑에서 **오므라든다**. 「이 놈이다」를 못 박는 획
      IBrim(c, jagPoly(tx, ty, f.r * (2.4 - 1.2 * m), 9, idx * 2.9, 1.04, .48),
        "frost", (.24 + .40 * m) * z, 1.2 * SC);
    }
    // ② ㉡ 생성 — ⭐ **3D 고드름이 난다.** 작고 촘촘하고 면이 보인다
    // ⚠️ 2026-08-28 사용자 판정: 「투사체 고드름 같은 걸 좀 더 **3D로** 표현하고
    //   퀄리티도 높게. 깨트리는 **고드름 사이즈가 너무 크고** 조악해 보임」
    //   ⇒ 크기를 26→17 · 5.2→3.4 로 줄이고, **프리즘 셋을 겹쳐** 모서리 면을
    //     만들고, 앞끝 심과 뒤 반짝이로 **밀도가 크기를 대신하게** 했다.
    if (B.inGrow) {
      const v = IZcl(B.grow), dd = IZS_MUZ + (d - IZS_MUZ) * v * v;
      // ⚠️⚠️ **정령의 총구에서 난다** — `cx`·`cy` 가 아니라 `SPX`·`SPY` 다.
      const nx = SPX + Math.cos(a) * dd * SC, ny = SPY + Math.sin(a) * dd * SC;
      // ㉠ 겹 셋 — 각을 조금씩 어긋내면 **면**이 생겨 납작한 것이 입체로 읽힌다.
      //   뒤쪽 겹일수록 어둡고 작다(빛이 앞면에서만 꺾인다).
      // ⚠️⚠️ **2026-08-28 4차 — 겹 셋을 [IZprism3] 로 갈았다.** 앞 판은 겹마다
      //   `IBneedle` 하나였고 그것은 **한 색으로 칠한 면**이라, 셋을 겹쳐도
      //   「종잇조각 셋」이었다. 입체는 모양이 아니라 **면마다 다른 밝기**에서
      //   난다 ⇒ 겹 하나가 다시 **면 셋**(밝은 면 · 흰 심 · 그늘 면)으로 갈려
      //   고드름 하나에 **아홉 면**이 선다. ⚠️ **면적은 안 늘었다** — 같은
      //   픽셀을 몇 색으로 나눠 칠할 뿐이다.
      // ⚠️ 뒤 겹은 `far` 로 **희끄무레하게** 민다(대기 원근) — 그것이 깊이다.
      for (let q = IZS_FACET - 1; q >= 0; q--) {
        const off = (q - (IZS_FACET - 1) / 2) * IZS_FTILT;
        const sh = 1 - q * .13;
        IZprism3(c, nx - Math.sin(a) * q * 1.5 * SC, ny + Math.cos(a) * q * 1.5 * SC,
          a + off, IZS_LEN * SC * sh, IZS_W * SC * sh, idx * 3.7 + q * 5.1,
          (q === 0 ? .95 : .70 - q * .10) * z, { far: q * .34, tip: .16 });
      }
      // ⭐ **곧은 속도선 셋** — 투사체 문법 ⑤. 꼬인 것만 있으면 느려 보인다
      for (let q = 0; q < 3; q++) {
        const o = (q - 1) * IZS_W * SC * .70;
        IBline(c, [[nx - Math.sin(a) * o, ny + Math.cos(a) * o],
                   [nx - Math.cos(a) * IZS_LEN * SC * (1.5 + .5 * hash(idx + q)) - Math.sin(a) * o,
                    ny - Math.sin(a) * IZS_LEN * SC * (1.5 + .5 * hash(idx + q)) + Math.cos(a) * o]],
          .8 * SC, "frost", (.44 - q * .06) * v * z, 0);
      }
      // ㉡ 앞끝 심 — 뾰족한 쪽이 제일 밝다. 「어디로 가는가」가 여기 있다
      IBspark(c, nx + Math.cos(a) * IZS_LEN * SC * .9,
        ny + Math.sin(a) * IZS_LEN * SC * .9, IZS_W * SC * 2.0, "frost", .92 * z, a);
      // ㉢ 뒤 반짝이 — **밀도.** 선을 안 그린다(거미줄이 되므로)
      for (let j = 1; j <= 3; j++) {
        const w = v - j * .10;
        if (w <= 0) continue;
        const bd = IZS_MUZ + (d - IZS_MUZ) * w * w;
        IBspark(c, SPX + Math.cos(a) * bd * SC + (hash(idx + j) - .5) * 4 * SC,
          SPY + Math.sin(a) * bd * SC + (hash(idx * 3 + j) - .5) * 4 * SC,
          (2.6 - j * .5) * SC, "frost", (1 - j / 4) * .62 * z, a + j);
      }
    }
    // ③ 깨짐 — ⭐ **얼음 폭발 + 스플래시**([IZboom]). 이 칸이 빙의 터뜨리는
    //   자리라 제일 화려해야 한다(2026-08-28 사용자 판정). 앞 판은 흰 고리
    //   하나 + 반짝이 셋이라 「터졌다」가 아니라 「사라졌다」로 보였다.
    if (tau >= tHit && tau < tHit + IZS_BOOM) {
      const v = IZcl((tau - tHit) / IZS_BOOM);
      // ⭐⭐ 사용자: 「**터지고 터지는**」 ⇒ 한 번이 아니라 **시차를 둔 셋**이다
      //   (중심 0.00 → 고리 0.08 → 바깥 파편 0.18). [IZchain] 이 그 시차를 쥔다.
      IZchain(c, tx, ty, tau - tHit, IZS_BR * SC, SC, z, idx * 4.3, .86);
      // ⭐ 솟은 것 아래엔 **부서진 것이 깔린다** — 큰 뼈대 셋에 파편이 매달린다
      if (v < .74) IZbones(c, tx, ty + f.r * .34, -Math.PI / 2 + (idx - 1) * .34,
        IZS_BR * SC * (.44 + .40 * v), 2.4 * SC, SC, (1 - v) * .82 * z,
        idx * 9.7, 3, 5);
      // 반짝이 — 폭발이 삼키지 못한 마지막 겹
      for (let j = 0; j < 5; j++) {
        const a0 = (j + .5) / 5 * TAU + idx;
        const d = f.r * (1.1 + 1.5 * v);
        IBspark(c, tx + Math.cos(a0) * d, ty + Math.sin(a0) * d * .86,
          (2.6 + 1.8 * hash(idx * 5.1 + j)) * SC * (1 - v * .4), "frost",
          (1 - v) * .92 * z, tp + j);
      }
    }
    // ④ 잔상 — **베인 선.** 날이 지나온 자리에 남는다
    // ⚠️⚠️ 이 선이 **어디서 시작하나**가 곧 「누가 쐈나」다. 앞 판은 캐릭터
    //   총구에서 표적까지 그어져, 고드름을 정령으로 옮겨도 **자국이 캐릭터를
    //   가리켰다.** 시전자를 옮길 때 제일 놓치기 쉬운 항이 이것이다.
    if (tau >= tHit) {
      const v = IZcl((tau - tHit) / IZS_SCAR);
      IBline(c, [[SPX + Math.cos(a) * IZS_MUZ * SC, SPY + Math.sin(a) * IZS_MUZ * SC],
                 [tx, ty]], 2.2 * SC, "frost", (1 - v) * .40 * z, 1);
    }
    // ⑤ ㉣ **소멸** — 폭발이 꺼진 뒤 남는 얼음 웅덩이와 잔해.
    //   ⚠️ 다섯 칸이 **전부** 쓴다(L2 의 「남은 조각」과 다르다 — 그건 사건이고
    //     이건 잔상이다). 이 두 겹이 없으면 이 칸은 주기의 절반이 빈 화면이다.
    if (tau >= B.t2) {
      const v = IZcl((tau - B.t2) / (B.t3 - B.t2));
      IBroot(c, tx, ty + f.r * .3, IZS_BR * SC * (.62 + .30 * v), "frost",
        (1 - v) * .34 * z, .38);
      IBrim(c, jagPoly(tx, ty + f.r * .3, IZS_BR * SC * (.54 + .28 * v), 11,
        idx * 6.9, 1.04, .38), "frost", (1 - v) * .46 * z, 1.3 * SC);
    }
    // ⑥ ㉤ **종료** — 웅덩이마저 김으로 흩어진다. 소멸과 **다른 그림**이다
    if (B.inRest) IZrestFx(c, tx, ty + f.r * .3, B.rest, IZS_BR * SC * .70,
      SC, z, idx * 3.7 + 1.9);
  }
  // ── ⭐ 연쇄 — **옮겨 붙는 것이 보여야 연쇄다** ────────────────────────────
  // ⚠️ 앞 판은 「0.12초 뒤에 저쪽도 터진다」뿐이라, 갈무리에서는 **폭발 둘이
  //   그냥 따로 난 것**으로 보였다. 이어 주는 획(얼음 빔)과 저쪽의 폭발을
  //   같이 그려야 「연쇄」가 화면의 말이 된다.
  if (CHAIN) for (let j = 0; j < F.length; j++) {
    const at = st.ev["ch" + j];
    if (!at) continue;
    const src = F[st.ev["cf" + j]], dst = F[j];
    const sx = cx + src.ux * SC, sy = cy + src.uy * SC;
    const dx2 = cx + dst.ux * SC, dy2 = cy + dst.uy * SC;
    // 빔 — 깬 자리에서 다음 놈으로 **자라 나간다**. 마디마다 결정이 붙는다
    const bs = tau - (at - IZS_CHAIN);
    if (bs > 0 && bs < IZS_CHAIN + IZS_BEAMW) {
      const grow = IZcl(bs / IZS_CHAIN), fade = 1 - IZcl((bs - IZS_CHAIN) / IZS_BEAMW);
      const ex = sx + (dx2 - sx) * grow, ey = sy + (dy2 - sy) * grow;
      IBline(c, [[sx, sy], [ex, ey]], 3.4 * SC, "frost", .55 * fade * z, 1);
      IBline(c, [[sx, sy], [ex, ey]], 1.3 * SC, "frost", .95 * fade * z, 0);
      const ang = Math.atan2(dy2 - sy, dx2 - sx);
      for (let q = 0; q < 3; q++) {
        const w0 = (q + .5) / 3 * grow;
        ICiceBody(c, tp, sx + (dx2 - sx) * w0, sy + (dy2 - sy) * w0,
          5.0 * SC * fade, ang, j * 6.7 + q * 3.1, "frost", .85 * fade * z,
          { arms: 6, branch: .14, wid: .28, tap: .55, core: .58, vary: .26, turn: 0 });
      }
    }
    // 옮겨 붙은 폭발 — **주된 폭발보다 한 단 작다.** 같으면 「둘이 동시에」가 된다
    if (tau >= at && tau < at + IZS_BOOM + .30)
      IZchain(c, dx2, dy2, tau - at, IZS_BR * SC * .82, SC, .86 * z, j * 8.9, .86);
    // 터진 자리 — 옮겨 붙은 쪽도 주기 끝까지 자국을 남긴다
    if (tau >= at + IZS_BOOM * .6) {
      const v = IZcl((tau - at - IZS_BOOM * .6) / (B.t3 - at - IZS_BOOM * .6));
      IBroot(c, dx2, dy2 + dst.r * .3, IZS_BR * SC * (.50 + .26 * v), "frost",
        (1 - v) * .26 * z, .38);
      IBrim(c, jagPoly(dx2, dy2 + dst.r * .3, IZS_BR * SC * (.44 + .24 * v), 9,
        j * 5.1, 1.04, .38), "frost", (1 - v) * .36 * z, 1.2 * SC);
    }
  }
  // ── ⭐ 곁이 언다 — L4 의 사건. 깨는 냉기가 **밖으로 한 번 퍼진다** ────────
  // ⚠️ 상태만 바꾸고 획을 안 그리면 「레벨을 올렸는데 아무 일도 안 일어난다」가
  //   된다 — 언 놈에게 도장([IZseal])이 앉는 것과 **그 냉기가 어디서 왔는지**가
  //   둘 다 보여야 사건이다.
  if (CHILL && tau >= tHit && tau < tHit + .40) {
    const v = IZcl((tau - tHit) / .40);
    for (let ti = 0; ti < TGT.length; ti++) {
      const f = F[TGT[ti]];
      IBrim(c, jagPoly(cx + f.ux * SC, cy + f.uy * SC, IZS_NEAR * SC * IZss(v),
        17, 4.9 + ti, 1.02, .52), "frost", (1 - v) * .38 * z, 1.2 * SC);
    }
  }
  // ⑤ 서리 고리 — L5 의 사건. 깨진 자리에 남아 **그 안이 계속 언다**
  if (THREE && tau >= tHit) {
    for (let ti = 0; ti < TGT.length; ti++) {
      const f = F[TGT[ti]];
      const v = IZcl((tau - tHit) / (B.t4 - tHit - .1));
      IBrim(c, jagPoly(cx + f.ux * SC, cy + f.uy * SC, 34 * SC * (.5 + .5 * IZss(v * 3)),
        13, 7.7 + ti, 1.02, .42), "frost", (1 - v * .6) * .55 * z, 1.6 * SC);
    }
  }
  // ⑥ 남은 조각 — L2 의 사건. 바닥에 **깔려** 그 자리를 지나는 것을 문다
  // ⚠️ 처음엔 마름모 여섯을 흩기만 했다 — 화면에서 L1 과 **거의 안 갈렸다**.
  //   조각이 「남았다」로 읽히려면 **바닥에 놓인 것**이라야 해서 접지 발광과
  //   눌린 테를 같이 깐다(빙판이 판을 앉히는 것과 같은 세 겹이다).
  if (KEEP && tau >= tHit + IZS_FRAG * .6) {
    const v = IZcl((tau - tHit - IZS_FRAG * .6) / (B.t4 - tHit - IZS_FRAG * .6 - .04));
    const f = F[TGT[0]];
    const bx = cx + f.ux * SC, by = cy + f.uy * SC;
    IBroot(c, bx, by, 40 * SC, "frost", (1 - v) * .44 * z, .42);
    IBrim(c, jagPoly(bx, by, 36 * SC, 11, 3.9, 1.04, .42), "frost",
      (1 - v) * .62 * z, 1.7 * SC);
    for (let j = 0; j < 12; j++) {
      const a0 = (j + .5) / 12 * TAU + 1.1, d = 18 + 14 * hash(j * 2.7);
      IBshard(c, bx + Math.cos(a0) * d * SC, by + Math.sin(a0) * d * .5 * SC,
        (3.2 + 2.0 * hash(j * 6.7)) * SC, a0, "frost", (1 - v) * .92 * z, .46);
    }
    // ⭐ **바닥에 꽂힌 파편 넷** — 깔린 조각을 「밟으면 물린다」로 만드는 실루엣.
    // ⚠️ 마름모만 흩으면 L1 의 폭발 잔해와 안 갈린다(실측 화소거리 0.0044).
    //   서 있는 것이 하나라도 있어야 「남았다」가 「터졌다」와 다른 그림이 된다.
    for (let j = 0; j < 6; j++) {
      const a0 = (j + .5) / 6 * TAU + .6, d = 12 + 9 * hash(j * 8.3);
      IBneedle(c, bx + Math.cos(a0) * d * SC, by + Math.sin(a0) * d * .5 * SC,
        -Math.PI / 2 + (hash(j * 4.1) - .5) * .8, (14 + 7 * hash(j * 9.7)) * SC,
        3.0 * SC, j * 7.3, "frost", (1 - v) * .94 * z,
        { tip: .20, slant: .55, mos: 1, w: 1.2 * SC });
    }
  }
  IZchips(c, st, tau, SC, z);
  IZmarks(c, tp, cx, cy, F, SC, z);
  // ⭐⭐⭐ **정령** — 캐릭터보다 뒤에. 다섯 마디 **전부**에서 그린다(안 사라진다)
  IZdepth(c, SPY, cy, (cc) =>
    IZspirit(cc, SPX, SPY, tau * 2.2, AIM, SPFACE, SC, .96, 12.7, null, IZ_BREAK));
  hero(c, th, cx, cy);
},

// ── ⑤ 엉김 ────────────────────────────────────────────────────────────────
IZclump(c, t, dt, W, H, st) {
  const cx = W / 2, cy = H / 2, SC = Math.min(W, H) / 238;
  const F = IZfoes(st, SC, IZL_FOE);
  const u = saw(t, IZL_PER), tau = u * IZL_PER;
  // ⭐ **엉김의 재료는 언 놈이다**(빙의 축 ③) — 주기 처음에 셋이 얼어 있다.
  //   넷째는 L4 의 사건이 얼리고, L5 는 그 넷째를 두 번째 이음에서 사슬에 넣는다.
  if (IZwrap(st, u)) for (let i = 0; i < F.length; i++) F[i].frz = IZL_FRZ0[i];
  for (let i = 0; i < F.length; i++) if (F[i].frz) F[i].pv = IZF_MAX;
  const z = IZz(tau, IZL_PER, IZL_B[4]);
  const tp = tau * TAU / IZL_PER, th = tau * (TAU * 2 / 2.2) / IZL_PER;
  const wob = TAU * 2 * tau / IZL_PER;
  // ⭐⭐ 다섯 마디 — 시전 → 생성(다리가 자란다) → 발현 → 소멸 → 종료
  const B = IZbeat(tau, IZL_B);

  // ── ⭐⭐⭐ **얼음정령** — 이 칸에만 있는 개체 ────────────────────────────
  // ⚠️⚠️ **계약 ㉠ — 캐릭터는 이 스킬을 한 항도 안 그린다.**
  //   사용자: 「정령만 써야 해. **캐릭터는 같이 안 쏴.**」
  //   ⇒ 아래에서 `cx`·`cy` 를 **그리기 좌표로 쓰지 않는다.** 그 둘이 나오는
  //     자리는 셋뿐이고 셋 다 이 스킬의 그림이 아니다:
  //       · `IZspiritAt(u, cx, cy, …)` — 정령이 도는 **중심**(그리지 않는다)
  //       · `IZmarks(…, cx, cy, …)`    — **적 좌표의 원점**(적에 붙는 표식이다)
  //       · `hero(c, th, cx, cy)`      — 무대의 **몸 자체**
  //   ⚠️ 획을 더할 때 `cx + …` 로 자리를 잡고 싶어지면 **그 자리는 `SPX`·`SPY`**다.
  // ⚠️ **안 사라진다.** 다섯 마디 어디에서도 지우지 않는다 — 스킬을 배우면
  //   계속 있는 것이라 「쉬는 동안의 그림」이 이 칸의 절반이다.
  const [SPX, SPY, SPA] = IZspiritAt(u, cx, cy, SC);
  /// 겨누는 자세인가(0 떠돎 ↔ 1 겨눔). 시전에서 자세를 잡고 소멸에서 푼다.
  /// ⚠️ **떠돎과 겨눔이 다른 그림**이라야 「자아」가 보인다 — 자세가 하나면
  ///   그냥 떠다니는 장식이다.
  const AIM = B.inCast ? IZss(B.cast)
    : (tau < B.t3 ? 1 : 1 - IZss(IZseg(tau, B.t3, B.t4)));
  /// 겨누는 각 — 이을 두 몸의 가운데를 본다.
  const SPFACE = (() => {
    // ⚠️ `AGAIN` 은 **아래에서** 선언된다 — 즉시 실행이라 여기서 읽으면 TDZ 다.
    const p = ((LV === 5) ? [[0, 1], [1, 2]] : IZL_PAIR[LV - 1])[0];
    const a = F[p[0]], b = F[p[1]];
    return Math.atan2((a.uy + b.uy) / 2 * SC + cy - SPY,
                      (a.ux + b.ux) / 2 * SC + cx - SPX);
  })();
  void SPA;

  // 레벨 — 당김(L2) · 사슬(L3) · 끊길 때 굳음(L4) · 다시 이어짐(L5)
  const PULL = atL(2), SNAPFRZ = atL(4), AGAIN = (LV === 5);
  const HOLD = AGAIN ? IZL_HOLD5 : IZL_HOLD;
  const one = IZL_LINK + HOLD + IZL_SNAP;
  const rounds = AGAIN ? [B.t0, B.t0 + one + .08] : [B.t0];
  /// ⭐ L5 는 **두 번째 이음에서 사슬이 하나 는다** — 첫 이음의 끊김이 넷째를
  ///   얼렸기 때문이다(사건이 사건을 낳는다). L1~L4 는 표 그대로.
  const pairsOf = (ri) => (AGAIN && ri === 0) ? [[0, 1], [1, 2]] : IZL_PAIR[LV - 1];

  for (const f of F) f.hit = Math.max(0, f.hit - dt * 5);

  // ── ㉠ **시전** — ⭐ 2026-08-28 사용자 판정이 없다고 지적한 바로 그 마디.
  //   몸에서 냉기가 모이고, **이을 두 몸 사이에 씨앗이 떠오른다** — 다리가 설
  //   자리에 점이 먼저 서야 「이 스킬을 켰다」가 화면에 있다.
  if (B.inCast) {
    // ⚠️⚠️ **캐릭터가 아니라 정령이 시전한다**(2026-08-28 6차 사용자 아이디어).
    //   「캐릭터 주변에는 이미 너무 많은 오라들과 스킬들이 존재해서 조금
    //   분리하는 연출이 필요할 것 같아」 ⇒ 냉기도 마법진도 **정령 발치**에서 난다.
    //   ⚠️ `noSigil` 을 안 준다 — [IZcastFx] 안의 [IZsigil] 이 그대로 서는데,
    //     **자리만 정령으로 옮겨졌다**. 그것이 이 재설계의 전부다.
    IZcastFx(c, SPX, SPY, B.cast, SC, 1, 9.1);
    const m = IZss(B.cast);
    for (const p of pairsOf(0)) {
      const a = F[p[0]], b = F[p[1]];
      const ax = cx + a.ux * SC, ay = cy + a.uy * SC;
      const bx = cx + b.ux * SC, by = cy + b.uy * SC;
      for (let j = 0; j < IZL_SEED0; j++) {
        const w0 = (j + .5) / IZL_SEED0;
        const px = ax + (bx - ax) * w0, py = ay + (by - ay) * w0;
        // 씨앗 — 아래에서 떠올라 축 위에 선다. **아직 안 이어져 있다**
        const rise = (1 - m) * 9 * SC;
        IBroot(c, px, py + rise, (5 + 4 * m) * SC, "frost", .40 * m, .9);
        IBflake(c, px, py + rise, (3.4 + 3.0 * m) * SC, j * .7, "frost",
          .80 * m, .9 * SC, .94);
      }
    }
  }

  for (let ri = 0; ri < rounds.length; ri++) {
    const pairs = pairsOf(ri);
    const s = tau - rounds[ri];
    if (s < 0) continue;
    const link = IZcl(s / IZL_LINK);
    const hold = IZseg(s, IZL_LINK, IZL_LINK + HOLD);
    const snap = IZseg(s, IZL_LINK + HOLD, one);
    const rest = IZseg(s, one, one + IZL_REST);
    // ── 당긴다 — L2 의 사건. 이어진 둘이 서로 끌려 붙는다
    if (PULL && s >= IZL_LINK && s < IZL_LINK + HOLD) for (const p of pairs) {
      const a = F[p[0]], b = F[p[1]];
      const dx = b.ux - a.ux, dy = b.uy - a.uy, d = Math.hypot(dx, dy) || 1;
      const step = IZL_PULL / HOLD * dt;
      a.sx += dx / d * step; a.sy += dy / d * step;
      b.sx -= dx / d * step; b.sy -= dy / d * step;
    }
    // ── 끊긴다 — L4 는 그 순간 이음매가 터져 **둘 다 굳는다**
    const keyS = "snap" + ri;
    if (snap > 0 && !st.ev[keyS]) { st.ev[keyS] = 1;
      for (const p of pairs) for (const pi of p) {
        const f = F[pi];
        f.hit = 1;
        if (SNAPFRZ) {
          IZchill(f, IZF_MAX);
          // ⭐ 이음매가 터진 냉기는 **곁까지 닿는다** — 그것이 넷째를 얼려
          //   L5 의 두 번째 사슬을 만든다(사건이 사건을 낳는다).
          for (const g2 of F)
            if (Math.hypot(g2.ux - f.ux, g2.uy - f.uy) < IZL_NEAR) IZchill(g2, IZF_MAX);
        }
        IZchip(st, cx + (f.ux + f.sx) * SC, cy + (f.uy + f.sy) * SC,
          pi * 19.3 + ri * 7.1, 6,
          { b: rounds[ri] + IZL_LINK + HOLD, v: 34, vr: 24, r: 1.5, rr: 1.2,
            life: .40, g: 90 });
      }
    }
    if (rest >= 1) continue;

    // ══ 그리기 — 다리 ═══════════════════════════════════════════════════
    for (let pj = 0; pj < pairs.length; pj++) {
      const p = pairs[pj], a = F[p[0]], b = F[p[1]];
      const ax = cx + (a.ux + a.sx * z) * SC, ay = cy + (a.uy + a.sy * z) * SC;
      const bx = cx + (b.ux + b.sx * z) * SC, by = cy + (b.uy + b.sy * z) * SC;
      const ang = Math.atan2(by - ay, bx - ax);
      const alive = snap <= 0 ? link : 0;
      const gone = snap > 0 ? snap : 0;
      const LEN = Math.hypot(bx - ax, by - ay);
      const nx = -Math.sin(ang), ny = Math.cos(ang);   // 축의 법선
      // ── ㉢ **서리 소매** — 축을 감싸는 발광 셋. 다리에 **두께**를 준다
      //   ⚠️ 축에서 [IZL_SLEEVE] 안에만 선다. 이 규칙이 「거미줄」을 막는다.
      if (alive > 0) for (let i = 0; i < IZL_SEEDS; i++) {
        const w0 = (i + .5) / IZL_SEEDS;
        const px = ax + (bx - ax) * w0, py = ay + (by - ay) * w0;
        IBroot(c, px, py, (IZL_SLEEVE + 4) * SC * alive, "frost", .26 * alive * z, .82);
      }
      if (alive > .6) IBmist(c, (ax + bx) / 2, (ay + by) / 2,
        LEN * .34, pj * 3.7, .22 * alive * z, .46);
      // ── ㉠ **얼음빔** — 축을 따르는 굵은 심 + 흰 속심. 겹의 바닥이다
      if (alive > 0) {
        IBline(c, [[ax, ay], [bx, by]], 4.6 * SC * alive, "frost", .40 * alive * z, 1);
        IBline(c, [[ax, ay], [bx, by]], 1.9 * SC, "frost", .82 * alive * z, 0);
      }
      // ── ⭐⭐ **엉킴** — 사용자: 「**엉키고 돌고** 화려하게 부딪히며」
      //   (2026-08-28 4차). 곧은 심 하나는 **빔**이지 「엉김」이 아니다 ⇒ 축을
      //   **감고 도는 가닥 둘**을 얹는다. 위상이 π 어긋나 서로를 감아 지나간다.
      //   ⚠️ 진폭은 [IZL_SLEEVE] 안이다 — 넘으면 그 순간 「거미줄」이 된다.
      //   ⚠️ 도는 위상은 주기에서 파생하고 **바퀴 수가 정수**라 이음매가 없다.
      if (alive > 0) for (let b2 = 0; b2 < 2; b2++) {
        const pts = [];
        const spin = tau / IZL_PER * TAU * 2 + b2 * Math.PI + pj * .8;
        for (let i = 0; i <= 16; i++) {
          const w0 = i / 16;
          const amp = IZL_SLEEVE * .82 * SC * alive * Math.sin(w0 * Math.PI);
          const off = Math.sin(w0 * Math.PI * 3.0 + spin) * amp;
          pts.push([ax + (bx - ax) * w0 + nx * off, ay + (by - ay) * w0 + ny * off]);
        }
        IBline(c, pts, (1.5 - b2 * .35) * SC, b2 ? "snow" : "frost",
          (.72 - b2 * .16) * alive * z, 0);
      }
      // ── ㉡ **얼음** — 마디 결정. 앞 판보다 굵다(6.2 → 7.4)
      for (let i = 0; i < IZL_SEG; i++) {
        const w0 = (i + .5) / IZL_SEG;
        // 이어지는 동안 마디가 **가운데부터 바깥으로** 채워진다
        const grow = IZcl(alive * IZL_SEG - Math.abs(i - (IZL_SEG - 1) / 2) * .8);
        if (alive > 0 && grow < .02) continue;
        // 끊기면 마디가 셋으로 갈려 흩어진다 — **잔상**이 이 토막이다
        const drift = gone > 0 ? (w0 - .5) * 22 * SC * gone : 0;
        const px = ax + (bx - ax) * w0 + nx * drift;
        const py = ay + (by - ay) * w0 + ny * drift;
        const aa = (gone > 0 ? (1 - gone) * (1 - rest) : grow) * .95 * z;
        if (aa < .02) continue;
        ICiceBody(c, tp, px, py, 7.4 * SC * (gone > 0 ? 1 - gone * .4 : grow),
          ang, i * 4.3 + pj * 9.1, "frost", aa,
          { arms: 6, branch: .14, wid: .30, tap: .55, core: .60, vary: .26, turn: 0 });
        // 마디 곁의 작은 조각 — **축 위에** 앉는다(법선 몫이 소매 안이다)
        if (alive > 0 && grow > .5) IBshard(c,
          px + nx * IZL_SLEEVE * .62 * SC * (i % 2 ? 1 : -1),
          py + ny * IZL_SLEEVE * .62 * SC * (i % 2 ? 1 : -1),
          (2.2 + 1.4 * hash(i * 5.3 + pj)) * SC, ang + 1.1, "frost", aa * .8, .5);
      }
      // ── ㉣ **얼음결정** — 축 위 마디 둘에 앉는 육각 문장
      if (alive > .5) for (let i = 0; i < 2; i++) {
        const w0 = .32 + .36 * i;
        IBflake(c, ax + (bx - ax) * w0, ay + (by - ay) * w0,
          (IZL_SLEEVE + 1) * SC * alive, ang * .5 + i * .6, "frost",
          .60 * alive * z, 1.0 * SC, .92);
      }
      // ── ㉤ **불티** — 축을 따라 흐르는 반짝이. 「살아 있다」를 만든다
      //   ⚠️ 위상은 주기에서 파생하고 바퀴 수가 정수([IZL_GLT])라 이음매가 없다.
      if (alive > .3) for (let i = 0; i < IZL_GLINT; i++) {
        const ph = (tau / IZL_PER * IZL_GLT + i / IZL_GLINT + pj * .27) % 1;
        const px = ax + (bx - ax) * ph, py = ay + (by - ay) * ph;
        IBspark(c, px, py, (2.6 + 1.4 * hash(i * 7.1 + pj)) * SC,
          "frost", Math.sin(Math.PI * ph) * .85 * alive * z, ang + i);
      }
      // 이음매 덩이 — 양 끝에 **엉겨 붙은 것**. 결정 하나씩 더 얹는다
      if (alive > 0) for (let q = 0; q < 2; q++) {
        const qx = q ? bx : ax, qy = q ? by : ay;
        IBroot(c, qx, qy, 12 * SC * alive, "frost", .38 * alive * z, .8);
        ICiceBody(c, tp, qx, qy, 8.0 * SC * alive, ang + q * Math.PI,
          pj * 11.7 + q * 5.3, "frost", .80 * alive * z,
          { arms: 6, branch: .18, wid: .30, tap: .50, core: .58, vary: .28, turn: 0 });
      }
      // 금 — 끊기기 전 0.50초. 「곧 끊어진다」가 화면에 보인다
      if (hold > 0 && hold < 1 && s > IZL_LINK + HOLD - IZL_CRACK) {
        const m = IZseg(s, IZL_LINK + HOLD - IZL_CRACK, IZL_LINK + HOLD);
        for (let i = 1; i < IZL_SEG; i++) {
          const w0 = i / IZL_SEG;
          const px = ax + (bx - ax) * w0, py = ay + (by - ay) * w0;
          const gx = nx * IZL_SLEEVE * .78 * SC, gy = ny * IZL_SLEEVE * .78 * SC;
          IBline(c, [[px - gx, py - gy], [px + gx, py + gy]], 1.4 * SC,
            "frost", m * .78 * z, 0);
        }
      }
      // 끊기는 순간 — 이음매마다 **작은 폭발**. 「터져 언다」가 여기 있다
      if (gone > 0 && gone < 1) for (let q = 0; q < 2; q++)
        IZboom(c, q ? bx : ax, q ? by : ay, gone, 16 * SC, SC, .72 * z,
          pj * 3.1 + q * 6.7, .82);
      // ⭐ L4 의 사건 — **굳는 순간이 보여야 한다.** 이음매에서 냉기 고리가
      //   [IZL_NEAR] 까지 퍼지고 그 안의 몸에 도장이 크게 한 번 찍힌다.
      // ⚠️ 이것이 없으면 L3 과 L4 의 차이가 **적 하나의 표식**뿐이라 화면에서
      //   거의 안 갈린다(실측 화소거리 0.0067).
      if (SNAPFRZ && gone > 0) {
        const fz = IZcl(gone * 1.4);
        for (let q = 0; q < 2; q++) {
          const qx = q ? bx : ax, qy = q ? by : ay;
          IBrim(c, jagPoly(qx, qy, IZL_NEAR * SC * IZss(fz), 15, pj * 2.7 + q,
            1.02, .52), "frost", (1 - fz) * .46 * z, 1.4 * SC);
          IZseal(c, qx, qy, 13 * SC * (.6 + .8 * fz), SC, (1 - fz * .5) * .9 * z);
        }
      }
    }
  }
  // ── ㉤ 종료 — 끊긴 자리에 서리 자국만 남아 스러진다. **소멸과 다른 그림**이다
  if (B.inRest) for (const p of pairsOf(rounds.length - 1)) for (const pi of p) {
    const f = F[pi];
    IZrestFx(c, cx + (f.ux + f.sx * z) * SC, cy + (f.uy + f.sy * z) * SC,
      B.rest, 15 * SC, SC, 1, pi * 4.3);
  }
  IZstand(F, SC, wob, z);
  IZchips(c, st, tau, SC, z);
  IZmarks(c, tp, cx, cy, F, SC, z);
  // ⭐⭐⭐ **정령** — 캐릭터보다 **뒤에** 그린다(캐릭터가 주인공이다).
  //   ⚠️ 조건이 없다 — 다섯 마디 **전부**에서 그린다. 「안 사라진다」가 이
  //     개체의 계약이고, 쉬는 동안의 그림이 이 칸의 절반이다.
  // 🔴 **앞뒤 정렬**(2026-08-28 7차 버그 신고) — 정령이 몸보다 **아래로 가면
  //   몸 앞**에 그려야 한다. 앞 판은 늘 `hero()` 앞이라 아래로 갈 때 **깔렸다**.
  IZdepth(c, SPY, cy, (cc) => IZspirit(cc, SPX, SPY, tau * 2.2, AIM, SPFACE, SC, .96, 12.7, null, IZ_LINK));
  hero(c, th, cx, cy);
},

});

