// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐⭐ **밀도 헌장** — 화려함은 알파가 아니라 **항의 수**다   (2026-08-28 3차)
//
// 사용자: 「**화려함을 팍팍 넣어 줘**」 · 「안 넣는 이유가 혹시 뭐야? **상한이
//   걸려 있나?**」 ⇒ 실측으로 답한다: **상한이 아니다.**
//     · 삼각형 정원 `kVertexCap` 294,912 — 최악 여덟 장면에서 **버린 삼각형 0**
//     · 파티클 **면적** 상한 `maxPixelArea` = 1e9 — **사실상 무한**
//     · 파티클을 쓰는 FX 드라이버 80개 중 9개(11%) — **빙 계열은 0개**
//   ⇒ 안 넣은 것은 못 넣어서가 아니라 **안 넣어서**다. 스스로 검열하지 않는다.
//
// ── ⚠️ 진짜 예산은 하나뿐이다 — **칠하는 픽셀 면적** ─────────────────────
//   raster p95 **18.24ms**(목표 12.0) · build p95 0.49ms — **37배**.
//   GPU 가 무는 것은 **도형 개수가 아니라 면적**이다. ⇒ 잉크를 둘로 가른다:
//     · **싼 잉크(마음껏)** — 가늘고 긴 것: 파편 · 침 · 결 · 금 · 획 ·
//       파선 고리 · 눈금 띠 · 별꼴 교차선. **수백 개 겹쳐도 면적이 안 는다**
//     · **비싼 잉크(아껴서)** — 넓게 번지는 것: 큰 블룸 · 넓은 반투명 면 ·
//       큰 가산 원. **한 장면에 한두 겹만**
//   ⇒ 아래 도구 넷은 전부 **싼 잉크**로 짜였고, 비싼 잉크는 중심 코어 하나뿐이다.
//
// ── ⚠️⚠️ **밝기가 세 층이라야 한다** ─────────────────────────────────────
//   흰 코어 없이 본색만 쓰면 **항을 아무리 늘려도 「연하다」로 읽힌다** —
//   사용자가 파문에 낸 첫 지적이 정확히 그것이었다(「너무 연하고」).
//   ⇒ 거의 흰 심 / 하늘빛 몸 / 짙은 그림자 면. [IBline]·[IBcrys] 가 이미 그
//     세 층을 한 벌로 주므로 **새 칠 함수를 안 만든다**.
//
// ── 사용자 레퍼런스 넷의 해부(이 파일이 따르는 사양) ─────────────────────
//   ㉠ **얼음 소환** — ① 날카로운 파편 수백(길이·각·굵기가 제각각) ② **큰 뼈대
//      서넛**에 파편이 **매달린다**(허공에 흩뿌리지 않는다) ③ 뿌리는 굵고 끝은
//      바늘 ④ 밝기 층 셋 ⑤ 솟은 것 아래엔 반드시 **부서진 것이 깔린다**
//      ⑥ 블룸은 **코어 하나에만**                                    ⇒ [IZbones]
//   ㉡ **마법진** — ① 동심 고리 3~5(굵기가 다 다르다) ② **파선 고리**
//      ③ 눈금·룬 띠 ④ 정다각별을 **회전시켜 겹침** ⑤ 위성 원 서넛(각각 다른 기호)
//      ⑥ 중심 코어만 밝다. ⚠️ **땅에 눕는다**([LX3SQT])            ⇒ [IZsigil]
//   ㉢ **투사체** — ① 머리·몸통·꼬리 셋 ② 머리는 작고 밝고 **문양**이 있다
//      (그 문양이 스킬의 정체다) ③ 몸통은 **꼬인 리본 두세 가닥** ④ 꼬리는
//      가늘어지고 흐려지고 흩어진다 ⑤ **곧은 속도선 서넛**이 리본을 관통
//      ⑥ 색이 둘 이상                                              ⇒ [IZbolt]
//   ㉣ **다단 폭발** — 「**엉키고 돌고** 화려하게 부딪히며 **터지고 터지는**」.
//      ① 바닥 진 ② 솟는 기둥은 곧은 한 줄이 아니라 **꼬인 가닥 + 지그재그 다발**
//      ③ 밑동 **부채꼴 스커트** ④ 바닥에 갈라진 **금** ⑤ 위로 튀는 파편 수십
//      ⑥ 밝기 세 층                                     ⇒ [IZcolumn] · [IZchain]
//      ⭐ **한 번 펑 하고 끝이 아니다** — 발현 안에서 작은 터짐 서넛이
//        **시차를 두고** 일어난다(중심 → 고리 → 바깥 파편).
// ══════════════════════════════════════════════════════════════════════════

// ── ㉡ 마법진 — **여섯 항을 다 갖는다** ───────────────────────────────────
/// 동심 고리 다섯의 반지름 몫. ⚠️ **굵기가 다 달라야 한다** — 같은 굵기로
/// 다섯을 그으면 「과녁」이 되지 마법진이 안 된다(레퍼런스 ㉡-①).
const IZG_RING = [1.00, .93, .74, .60, .30];
/// 그 굵기(238칸). 바깥 굵은 테 하나 + 가는 것 넷.
const IZG_RW = [2.6, .9, 1.6, .8, 1.2];
/// ⭐⭐ 고리마다 **몇 각인가** — 참고장 「빙-1」: **얼음에는 원호를 쓰지 않는다.**
///   「얼음을 얼음으로 만드는 것은 파랑이 아니라 **각(角)**」이다.
/// ⚠️ 이 표가 없으면 마법진이 **동심원**이 되고, 그러면 결빙의 `IBrune`(동심
///   타원)과 화면에서 **같은 물건**이 된다 — 이 장이 빙판에서 이미 못 박은 규칙이다.
const IZG_NGON = [12, 12, 6, 6, 6];
/// 파선 고리의 토막 수 · 눈금 룬 띠의 획 수 · 위성 원.
const IZG_DASH = 40, IZG_TICK = 44, IZG_SAT = 4;
/// 겹치는 정다각별 — `[꼭짓점, 건너뛰기]`. 셋을 서로 다른 각으로 돌려 겹치면
/// **겹치는 자리에서 저절로 무늬가 난다**(레퍼런스 ㉡-④).
const IZG_STAR = [[3, 1], [5, 2], [8, 3]];

/// ⭐⭐ **마법진의 정본** — 시전·생성 마디가 이 한 함수를 쓴다.
/// ⚠️⚠️ **땅에 눕는다.** 눌림은 [LX3SQT](= `render/world_fold.dart` 의
///   `kFoldSquashPick`)다 — 세워 그리면 이식하는 날 통째로 다시 그린다.
/// ⚠️ 전부 **선**이다. 속을 채우면 그냥 파란 웅덩이가 된다(비싼 잉크).
///   밝은 것은 **중심 코어 하나뿐**이다(레퍼런스 ㉡-⑥).
/// `v` 0→1 그려지는 진행 · `rot` 도는 각(0 이면 안 돈다)
function IZsigil(c, x, y, r, rot, v, SC, a, seed) {
  if (!(r > 2) || a <= .01 || v <= 0) return;
  const SQ = LX3SQT;
  const P = (ang, rr) => [x + Math.cos(ang) * rr, y + Math.sin(ang) * rr * SQ];
  /// 안에서 밖으로 차례로 열린다 — `k` 가 클수록 늦다.
  const op = (k) => IZss(IZcl((v - k * .11) / .52));
  // ① 동심 고리 다섯 — 굵기가 다 다르다. **바깥 테 하나만 흰 심을 세운다**
  for (let k = 0; k < IZG_RING.length; k++) {
    const o = op(IZG_RING.length - 1 - k); if (o < .02) continue;
    const rr = r * IZG_RING[k], n = IZG_NGON[k], pts = [];
    // ⚠️ **정n각형이다**(원호 금지 · 빙-1). 안쪽 고리는 육각 — 얼음 결정의 격자
    //   그대로다. 고리마다 각을 조금씩 어긋내야 겹칠 때 무늬가 난다.
    for (let i = 0; i <= n; i++) pts.push(P(rot * .28 + k * .26 + i / n * TAU, rr));
    IBline(c, pts, IZG_RW[k] * SC, "frost", (k ? .38 : .82) * o * a, k ? 0 : 1);
  }
  // ② 파선 고리 — 실선 사이를 **조용히** 채운다. 이 겹이 밀도의 반이다
  {
    const o = op(1);
    if (o > .02) for (let i = 0; i < IZG_DASH; i++) {
      const a0 = rot * .28 + i / IZG_DASH * TAU, w = TAU / IZG_DASH * .46;
      IBline(c, [P(a0 - w, r * .845), P(a0 + w, r * .845)], .9 * SC,
        "frost", .46 * o * a, 0);
    }
  }
  // ③ 눈금·룬 띠 — 짧은 획 마흔넷. ⚠️ **길이가 제각각이라야 한다** —
  //   같으면 톱니바퀴가 되고, 제각각이라야 「글씨가 빼곡하다」가 된다
  {
    const o = op(2);
    if (o > .02) for (let i = 0; i < IZG_TICK; i++) {
      const a0 = rot * .28 + i / IZG_TICK * TAU;
      const r0 = r * .615, r1 = r * (.615 + .030 + .085 * hash(seed + i * 3.1));
      IBline(c, [P(a0, r0), P(a0, r1)], .8 * SC, "frost",
        (.34 + .40 * hash(seed + i * 5.9)) * o * a, 0);
    }
  }
  // ④ **정다각별 셋을 회전시켜 겹친다** — 겹치는 자리에서 무늬가 저절로 난다
  for (let s = 0; s < IZG_STAR.length; s++) {
    const o = op(3 - s); if (o < .02) continue;
    const [n, st] = IZG_STAR[s], rr = r * (.68 - s * .06), pts = [];
    for (let i = 0; i <= n; i++) pts.push(P(rot * (.28 + s * .21) + s * .37 + i * st * TAU / n, rr));
    IBline(c, pts, (1.0 - s * .16) * SC, "frost", (.30 + s * .10) * o * a, 0);
  }
  // ⑤ 위성 원 넷 — 큰 고리 위에 작은 원이 얹히고 **안에 각각 다른 기호**
  {
    const o = op(4);
    if (o > .02) for (let i = 0; i < IZG_SAT; i++) {
      const a0 = rot * .28 + (i + .5) / IZG_SAT * TAU;
      const [sx, sy] = P(a0, r * .845), sr = r * .105 * o;
      if (sr < .8) continue;
      const ring = [];   // ⚠️ 위성도 **육각**이다(빙-1) — 여기만 원이면 튄다
      for (let j = 0; j <= 6; j++)
        ring.push([sx + Math.cos(j / 6 * TAU) * sr, sy + Math.sin(j / 6 * TAU) * sr * SQ]);
      IBline(c, ring, .9 * SC, "frost", .58 * o * a, 0);
      // 기호 — 넷이 서로 다르다(육각 · 십자 · 삼각 · 점)
      if (i === 0) IBflake(c, sx, sy, sr * .72, 0, "frost", .62 * o * a, .8 * SC, SQ);
      else if (i === 1) IBspark(c, sx, sy, sr * .78, "frost", .58 * o * a, .4);
      else if (i === 2) IBline(c, IZpoly(sx, sy, sr * .66, 3, .7, SQ), .8 * SC,
        "frost", .58 * o * a, 0);
      else IBroot(c, sx, sy, sr * .52, "frost", .50 * o * a, SQ);
    }
  }
  // ⑥ **중심 코어 — 여기만 밝다.** 이 장면에서 비싼 잉크는 이 한 겹뿐이다
  IBroot(c, x, y, r * .17 * IZss(v), "frost", .80 * a, SQ);
  IBspark(c, x, y, r * .13 * IZss(v), "frost", .90 * a, rot * .5);
}

// ── ㉠ 큰 뼈대에 **매달린** 파편 ─────────────────────────────────────────
/// ⭐ 파편을 허공에 흩뿌리면 「지저분하다」가 되고, **뼈대에 매달면**
///   「빽빽하다」가 된다(레퍼런스 ㉠-②). 그래서 이 함수는 **뼈대를 먼저 긋고**
///   그 위에 파편을 앉힌다.
/// ⚠️ 뿌리는 굵고 끝은 **바늘**이다(㉠-③) — `tip` 이 .10 인 이유가 그것이다.
/// `n` 뼈대 수 · `m` 뼈대마다 매달리는 파편 수
function IZbones(c, x, y, ang, len, w, SC, a, seed, n, m) {
  if (!(len > 2) || a <= .01) return;
  for (let b = 0; b < n; b++) {
    // 뼈대 — 살짝 휜다. 세 토막으로 나눠 그으면 곧은 막대가 안 된다
    const ba = ang + (hash(seed + b * 4.1) - .5) * .62;
    const bl = len * (.72 + .40 * hash(seed + b * 6.7));
    const bw = w * (.78 + .46 * hash(seed + b * 8.3));
    IBneedle(c, x, y, ba, bl, bw, seed + b * 11.7, "frost", .92 * a,
      { tip: .10, slant: .42, mos: 2, w: Math.max(.6, bw * .28) });
    // 매달린 파편 — 뼈대를 따라가며 좌우로 뻗는다. **길이·각·굵기가 제각각**
    for (let j = 0; j < m; j++) {
      const u = .16 + .78 * ((j + .5) / m);
      const sd = seed + b * 21.3 + j * 3.7;
      const side = (j % 2 ? 1 : -1);
      const px = x + Math.cos(ba) * bl * u, py = y + Math.sin(ba) * bl * u;
      const sa = ba + side * (.42 + .72 * hash(sd + 1.3));
      const sl = bl * (.16 + .30 * hash(sd + 2.9)) * (1 - u * .48);
      const sw = bw * (.26 + .34 * hash(sd + 5.1));
      IBneedle(c, px, py, sa, sl, sw, sd, "frost", (.62 + .30 * hash(sd + 7.7)) * a,
        { tip: .08, slant: .34, mos: 0, w: Math.max(.45, sw * .30) });
    }
  }
  // ⑤ **솟은 것 아래엔 부서진 것이 깔린다** — 이것이 없으면 붕 떠 보인다
  for (let j = 0; j < n * 3; j++) {
    const a0 = ang + (hash(seed + j * 9.1) - .5) * 2.4;
    const d = len * (.10 + .30 * hash(seed + j * 13.3));
    IBshard(c, x + Math.cos(a0) * d, y + Math.sin(a0) * d * LX3SQT + w * .4,
      w * (.34 + .40 * hash(seed + j * 17.9)) , a0 + 1.1, "frost", .58 * a, .42);
  }
}

// ── ㉢ 투사체 — **머리 · 몸통 · 꼬리** ───────────────────────────────────
/// ⭐⭐ **한 덩어리로 그리면 조악해진다.** 사용자가 깨뜨리기 고드름에 낸
///   판정(「사이즈가 너무 크고 조악해 보임」)의 원인이 그것이다 — 크기가 아니라
///   **셋으로 안 갈린 것**이 문제였다.
/// ⚠️ 머리의 **문양이 그 스킬의 정체**다(레퍼런스 ㉢-②) — 빙은 **육각 결정**이다.
/// ⚠️ 몸통은 **꼬인 리본 둘**이다. 한 가닥이면 밧줄로 보인다(㉢-③).
/// ⚠️ 곧은 **속도선 셋**이 리본을 관통해야 빨라 보인다(㉢-⑤).
/// ⚠️ 색이 **둘 이상**이다 — 본색 `frost` + 보조 `snow` + 흰 코어(㉢-⑥).
/// `r` 머리 반지름(px) · `ang` 나아가는 각 · `tail` 꼬리 길이(px)
function IZbolt(c, x, y, ang, r, tail, SC, a, seed) {
  if (!(r > .4) || a <= .01) return;
  const cs = Math.cos(ang), sn = Math.sin(ang);
  /// 머리에서 `d` 만큼 **뒤로** · 축에서 `o` 만큼 옆으로.
  const at = (d, o) => [x - cs * d - sn * o, y - sn * d + cs * o];
  // ③ 몸통 — 꼬인 리본 둘. 서로를 감고 지나간다(위상이 π 만큼 어긋난다)
  for (let b = 0; b < 2; b++) {
    const k = b ? "snow" : "frost";           // ⑥ 색이 둘이다
    for (let s = 0; s < 5; s++) {             // ④ 다섯 토막 — 뒤로 갈수록 가늘다
      const pts = [];
      for (let i = 0; i <= 4; i++) {
        const u = (s * 4 + i) / 20;
        const wv = Math.sin(u * Math.PI * 2.6 + b * Math.PI + seed) * r * 1.05 * (1 - u * .72);
        pts.push(at(u * tail, wv));
      }
      const u0 = s / 5;
      IBline(c, pts, r * .40 * (1 - u0 * .82), k,
        (1 - u0) * (1 - u0) * .78 * a, 0);
    }
  }
  // ⑤ 곧은 속도선 셋 — 꼬인 것만 있으면 **느려 보인다**
  for (let i = 0; i < 3; i++) {
    const o = (i - 1) * r * .52, L = tail * (.52 + .30 * hash(seed + i * 3.3));
    IBline(c, [at(r * .3, o * .3), at(L, o)], r * .13, "frost",
      (.52 - i * .06) * a, 0);
  }
  // ④ 꼬리는 **흩어진다** — 굵기가 일정한 꼬리는 밧줄이다
  for (let j = 0; j < 7; j++) {
    const u = .34 + .62 * hash(seed + j * 5.7);
    const o = (hash(seed + j * 9.1) - .5) * r * 3.0 * u;
    const [px, py] = at(u * tail, o);
    IBshard(c, px, py, r * (.44 - .26 * u) * (.7 + .6 * hash(seed + j * 2.3)),
      ang + j, "frost", (1 - u) * .72 * a, .46);
  }
  // ② **머리 — 작고 아주 밝고 문양이 있다.** 빙의 문양은 육각 결정이다
  IBroot(c, x, y, r * 2.1, "frost", .42 * a, .96);          // 비싼 잉크 — 여기만
  IBroot(c, x, y, r * .86, "frost", .95 * a, .96);
  IBflake(c, x, y, r * 1.55, ang * .5, "frost", .88 * a, 1.05 * SC, .96);
  IBcrys(c, IZpoly(x, y, r * .78, 6, ang, .96), "frost", .95 * a, seed + 2.2,
    { mos: 2, w: 1.1 * SC });
  IBspark(c, x, y, r * 1.7, "frost", .92 * a, ang);
}

// ── ㉣ **터지고 터진다** — 팝 한 번이 아니다 ─────────────────────────────
/// ⭐⭐ 사용자: 「엉키고 돌고 화려하게 부딪히며 **터지고 터지는**」.
///   ⇒ 발현 안에서 작은 터짐 **셋**이 시차를 두고 난다: 중심 → 고리 → 바깥 파편.
/// ⚠️ 한 번에 다 터뜨리면 「팝」이고, 시차를 두면 「연쇄」다. 그 차이가
///   **0.08초와 0.18초** 두 값에 다 들어 있다.
const IZX_LAG = [0, .08, .18], IZX_SPAN = [.42, .52, .62];
/// `s` 터짐이 시작된 뒤 흐른 시각(초) · `R` 최대 반지름(px)
function IZchain(c, x, y, s, R, SC, a, seed, sq) {
  for (let k = 0; k < 3; k++) {
    const v = (s - IZX_LAG[k]) / IZX_SPAN[k];
    // 🔴🔴 **`v <= 0` 이 아니라 `v < 0` 이다** (2026-08-29).
    // 사용자가 염에서 찾은 결함군이 빙에도 있었다: 「**딱! 이 시점에! 약간의
    //   딜레이가 있어.** 그니까 **바로 터져야 되는데 딜레이가 있으니까 응? 하고
    //   갑자기 터지면서**」
    // ⚠️⚠️ [IZX_LAG][0] 이 **0** 이라, 닿는 그 순간의 `s = 0` 이 `v = 0` 이 되고
    //   `v <= 0` 에 걸려 **그 프레임이 통째로 건너뛰어졌다.** 곧 **닿는 프레임과
    //   터지는 프레임이 정확히 한 프레임(16.7ms) 어긋나 있었다.**
    //   ⇒ [IZboom] 은 `v < 0` 만 막으므로(그쪽은 맞았다) 여기만 고치면 된다.
    //   ⭐ 그리고 `v = 0` 이 **제일 밝은 프레임**이다([IZboom] 의 `core` 가
    //     `1 − v/.30` 이라 v=0 에서 1.0) — 닿는 순간이 곧 가장 밝은 순간이 된다.
    // ⚠️ 이 한 줄이 **서리탄 착탄 · 우박 알 깨짐 · 빙추 밑동**을 한꺼번에 고친다.
    if (v < 0 || v >= 1) continue;
    IZboom(c, x, y, v, R * (1 - k * .17), SC, a * (1 - k * .20), seed + k * 11.3, sq);
  }
}

// ── ㉣ **솟는 기둥** — 곧은 한 줄이 아니라 꼬인 다발이다 ─────────────────
/// ⭐ 레퍼런스 ㉣-②③④: **꼬인 가닥 셋 + 번개꼴 지그재그 + 밑동 부채꼴 스커트
///   + 바닥에 갈라진 금**. 넷이 다 있어야 「솟았다」로 읽힌다.
/// ⚠️ 기둥은 **선다**(안 눕는다). 스커트와 금만 눕는다 — 면이 둘이라 겹이 겹으로
///   읽힌다(같은 면에 겹치면 그냥 굵은 하나가 된다).
/// `v` 0→1 · `h` 높이(px) · `w` 반폭(px)
function IZcolumn(c, x, y, v, h, w, SC, a, seed) {
  if (v <= 0 || v >= 1 || a <= .01) return;
  const up = IZss(IZcl(v * 1.35)), fade = 1 - IZss(IZcl((v - .55) / .45));
  const A0 = a * fade, hh = h * up;
  if (hh < 1) return;
  // ④ 바닥에 갈라진 **금** — 진 바깥으로 뻗는다. 눕는다
  for (let j = 0; j < 7; j++) {
    const a0 = (j + .5) / 7 * TAU + seed;
    const L = w * (2.2 + 2.6 * hash(seed + j * 3.7)) * up;
    const mid = w * .9;
    IBline(c, [[x + Math.cos(a0) * mid, y + Math.sin(a0) * mid * LX3SQT],
               [x + Math.cos(a0 + .18) * L, y + Math.sin(a0 + .18) * L * LX3SQT]],
      1.0 * SC, "frost", .46 * A0, 0);
  }
  // ③ 밑동 **부채꼴 스커트** — 기둥과 바닥을 잇는 항. 주름져야 치마가 된다
  IBrim(c, jagPoly(x, y, w * 2.0 * up, 15, seed + 4.3, 1.14, LX3SQT),
    "frost", .56 * A0, 1.5 * SC);
  IBroot(c, x, y, w * 1.7 * up, "frost", .34 * A0, LX3SQT);
  // ② **꼬인 가닥 셋** — 서로를 감고 올라간다. 한 줄이면 「빔」이지 「기둥」이 아니다
  for (let b = 0; b < 3; b++) {
    const pts = [];
    for (let i = 0; i <= 12; i++) {
      const u = i / 12;
      const ph = u * Math.PI * 2.2 + b * TAU / 3 + seed;
      pts.push([x + Math.sin(ph) * w * (1 - u * .58), y - hh * u]);
    }
    IBline(c, pts, (1.5 - b * .28) * SC, b ? "snow" : "frost", (.72 - b * .14) * A0, 0);
  }
  // ② 번개꼴 **지그재그** 둘 — 다발을 관통한다
  for (let b = 0; b < 2; b++) {
    const pts = [];
    for (let i = 0; i <= 8; i++) {
      const u = i / 8;
      pts.push([x + (i % 2 ? 1 : -1) * w * .62 * (1 - u * .5) * (b ? -1 : 1),
                y - hh * u]);
    }
    IBline(c, pts, .9 * SC, "frost", .40 * A0, 0);
  }
  // ⑤ 위로 튀는 파편 — **수십**. 싼 잉크라 아낄 까닭이 없다
  for (let j = 0; j < 16; j++) {
    const u = hash(seed + j * 6.1);
    const yy = y - hh * u * (.3 + .8 * v);
    const xx = x + (hash(seed + j * 9.7) - .5) * w * 3.4;
    IBshard(c, xx, yy, w * (.16 + .20 * hash(seed + j * 2.9)), j * .7,
      "frost", (1 - u) * .70 * A0, .44);
  }
  // ⑥ 중심 흰 포화 — **한 겹뿐**
  IBroot(c, x, y - hh * .16, w * 1.0, "frost", .70 * A0, .90);
}

// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐⭐ **2D 로 3D 내는 법 — 여덟 조항**                      (2026-08-28 4차)
//
// 사용자: 「**2D 임에도 불구하고 3D처럼 충분히 효과를 낼 수 있을 것 같아.**
//   예시는 얼음이긴 한데, **모든 계열에 다 해당**하는 거 같아」
// ⇒ 빙만의 규칙이 아니라 **전 속성 공통 법칙**이다. 여기 도구 둘로 못 박아
//   두면 다른 속성이 그대로 가져다 쓴다.
//
//   ㉠ **면을 쪼갠다** — 결정 하나가 한 색이 아니라 **다각형 면 서넛**이고
//      면마다 밝기가 다르다. **이것 하나가 입체의 8할이다.**
//      ⭐⭐ 그리고 **공짜다** — 같은 픽셀을 몇 색으로 나눠 칠할 뿐이라
//        **면적이 안 는다.** 느는 것은 삼각형 수뿐이고 정원에 안 걸린다
//        (`kVertexCap` 294,912 · 최악 여덟 장면 **버린 삼각형 0**)
//      ⚠️ **세 단 이상**으로 나눈다 — 두 단이면 **종이접기**로 보인다
//   ㉡ **앞은 크고 뒤는 작다** — 크기가 고르면 **벽지**가 된다
//   ㉢ **뒤로 갈수록 밝고 옅다** — 대기 원근. 앞은 진하고 뒤는 희끄무레하다.
//      **면적을 안 늘린다**
//   ㉣ **앞의 것이 뒤의 것을 가린다** — 깊이의 **제일 강한 신호**이고 역시
//      **공짜다**(그리는 차례만 정하면 된다) ⇒ 뒤 → 앞 차례로 그린다
//   ㉤ **밑동에 들쭉날쭉한 흰 테** — 「**뚫고 나왔다**」를 말하는 항. 없으면
//      「바닥에 붙여 놓았다」가 된다
//   ㉥ **각도가 다 다르고 바깥일수록 눕는다** — 이 하나로 「원형으로 난 것을
//      비스듬히 본 것」이 된다. **방향은 ㉡+㉥ 이 만든다**
//   ㉦ **떨어져 나온 조각이 공중에 떠 있다** — 「지금 막 일어났다」
//   ㉧ **발치에 어두운 덩어리** — 그림자. 밝은 것만 있으면 붕 떠 보인다
//
// ⚠️ [A] 는 `#RRGGBB` 만 받는다. 면이 안 보이면 밝기가 아니라 **칠 실패**를
//   먼저 의심한다(캔버스는 잘못된 `fillStyle` 을 **조용히 무시**한다).
// ══════════════════════════════════════════════════════════════════════════
/// 면을 가르는 자리(축에서 옆으로 −1 ↔ +1). 셋으로 갈라 **밝은 면 · 흰 심 ·
/// 그늘 면**을 만든다. ⚠️ 둘로 가르면 종이접기다.
const IZ3_CUT = [-1, -.30, .28, 1];
/// 세 면의 밝기 — 위(빛 오는 쪽) · 심 · 그늘. **본색 하나로 칠하지 않는다.**
/// ⚠️⚠️ **2026-08-28 7차에 차를 벌렸다**(.34/.70/−.32 → .50/.86/−.52).
///   사용자: 「3D가 아니라 **평면처럼 보이거든?**」. 세 단을 주기만 해서는
///   모자라고 **차이가 작으면 눈이 한 면으로 뭉친다** — 얼음은 원래 면마다
///   확 다르다. 이 한 줄이 프리즘을 쓰는 **모든 칸**에 같이 먹는다.
const IZ3_MIX = [.50, .86, -.52];

/// ⭐⭐ **면이 쪼개진 결정 하나** — ㉠ 의 정본.
/// `far` 0(가깝다) ~ 1(멀다) — ㉢ 대기 원근이 여기서 든다.
function IZprism3(c, x, y, ang, len, w, seed, a, o) {
  if (!(len > 1) || !(w > .2) || a <= .01) return;
  o = o || {};
  const T = toneOf("frost"), far = IZcl(o.far || 0), tip = (o.tip == null ? .10 : o.tip);
  const cs = Math.cos(ang), sn = Math.sin(ang);
  const at = (d, off) => [x + cs * d - sn * off, y + sn * d + cs * off];
  const hw = (u) => w * (u < .18 ? (.46 + .54 * (u / .18)) : (1 + (tip - 1) * ((u - .18) / .82)));
  const US = [0, .18, .46, .74, 1];
  const AL = a * (1 - far * .34);
  // ㉣ 뒤 → 앞. 그늘 면을 먼저, 밝은 면을 나중에 — **겹침 순서가 깊이다**
  let CORE = null;
  for (let s = 2; s >= 0; s--) {
    const f0 = IZ3_CUT[s], f1 = IZ3_CUT[s + 1], P = [];
    for (const u of US) P.push(at(len * u, hw(u) * f0));
    for (let i = US.length - 1; i >= 0; i--) P.push(at(len * US[i], hw(US[i]) * f1));
    const m = IZ3_MIX[s];
    // ㉢ 먼 것은 **희끄무레하다** — 채도를 흰 쪽으로 당긴다
    let col = m >= 0 ? mixHex(T[1], "#FFFFFF", m) : mixHex(T[0], "#000000", -m);
    if (far > .01) col = mixHex(col, "#DFF3FF", far * .52);
    fillPoly(c, P, A(col, (s === 1 ? .92 : .80) * AL));
    if (s === 1) CORE = P;
  }
  // ⭐⭐⭐ **속심의 가산 겹** — 얼음이 「깎은 유리」가 되는 자리   (10차)
  // ⚠️⚠️ 여기까지는 전부 **덮어 칠하기**(source-over)라, 결정 둘이 겹쳐도
  //   **안 밝아졌다** — 그것이 곧 「속이 안 비친다」이고, 사용자가 빙에 네 번
  //   낸 지적(「너무 연하다」·「스티커」·「조악하다」)이 전부 여기로 모인다.
  //   얼음은 **빛을 통과시키고 굴절시키는 물건**이라 겹치는 데가 밝아져야 한다.
  // ⚠️ 얹는 자리는 **속심 한 면**뿐이다(폭의 29%). 세 면에 다 얹으면 결정이
  //   흰 덩어리가 되고, 무엇보다 **비싼 잉크**가 세 배가 된다.
  // ⚠️ 알파를 낮게 잡는다 — 가산은 겹칠수록 저절로 차오르므로, 한 장이 진하면
  //   둘만 겹쳐도 흰색으로 포화돼 **면 쪼개기가 통째로 사라진다.**
  if (CORE) gAdd(c, (cc) => fillPoly(cc, CORE,
    A(mixHex(T[2], "#FFFFFF", .30), .26 * AL * (1 - far * .45))));
  // 윤곽 — 실루엣 둘레가 면보다 밝다(싼 잉크)
  const OUT = [];
  for (const u of US) OUT.push(at(len * u, -hw(u)));
  for (let i = US.length - 1; i >= 0; i--) OUT.push(at(len * US[i], hw(US[i])));
  IBrim(c, OUT, "frost", AL * .92, Math.max(.5, w * .26));
  // ㉠-덤 **세로 결** — 면 위를 지나는 가는 금 둘. 면적을 안 늘리는 밀도
  //   ⭐ 엔진 이식: 이 결은 `fxNoiseVein` 한 장으로 대체된다(면에 UV 로 곱한다).
  if (!o.bare) for (let g = 0; g < 2; g++) {
    const f = -.62 + g * 1.18;
    IBline(c, [at(len * .10, hw(.10) * f), at(len * .92, hw(.92) * f)],
      Math.max(.4, w * .13), "frost", .34 * AL, 0);
  }
  // ⭐⭐⭐ **이방성 하이라이트** — 참고장 「빙-3」. 면마다 **가늘고 긴 흰
  //   삼각형 하나**를 그 면의 긴 축을 따라 얹는다.
  //   ⚠️ 결정이 입체로 읽히는 이유는 명암이 아니라 **하이라이트가 면의 방향을
  //     따라 한 줄로 눕는다**는 것이다. 면마다 각이 다르면 그것이 곧
  //     「면이 서로 다른 각도로 있다」는 정보가 된다.
  //   ⚠️ **셰이더가 필요 없다.** 참고장이 「투자 대비 이득이 제일 큰 항목」이라
  //     적은 것이 이것이고, 싼 까닭은 **가늘고 길기 때문**이다(면적이 거의 0).
  //   ⚠️ 면마다 **각을 다르게** 준다 — 같은 각이면 세 면이 한 면으로 붙어 보인다.
  //   ⚠️⚠️ **가산이라야 제 값을 한다**(10차). 앞 판은 이 삼각형도 덮어 칠하기라
  //     「흰 종이 조각을 얹은 것」이었다 — 하이라이트는 **빛**이지 색이 아니다.
  //     가산으로 얹으면 면의 밝기 위에 **더해져** 그 자리가 실제로 반짝인다.
  //   ⚠️ 가산은 흰색이 세므로 알파를 한 단 내렸다(.74/.46 → .58/.36) — 안 내리면
  //     세 면이 다 하얗게 포화돼 **면 쪼개기가 지워진다.**
  gAdd(c, (cc) => { for (let s = 0; s < 3; s++) {
    const f0 = IZ3_CUT[s], f1 = IZ3_CUT[s + 1];
    const mid = (f0 + f1) * .5;
    // 면마다 눕는 각이 다르다 — 왼면은 앞으로, 심은 축과 나란히, 그늘은 뒤로
    const skew = (s - 1) * .30;
    const u0 = .16 + s * .06, u1 = .86 - s * .05;
    const a0 = at(len * u0, hw(u0) * (mid - skew * .22));
    const a1 = at(len * u1, hw(u1) * (mid + skew * .22));
    // 가늘고 긴 **삼각형** — 뿌리 쪽이 넓고 끝이 한 점이다
    const nx = -(a1[1] - a0[1]), ny = (a1[0] - a0[0]);
    const nl = Math.hypot(nx, ny) || 1;
    const t0 = w * (.20 - s * .04) / nl;
    fillPoly(cc, [[a0[0] + nx * t0, a0[1] + ny * t0],
                  [a0[0] - nx * t0, a0[1] - ny * t0],
                  [a1[0], a1[1]]],
      A("#FFFFFF", (s === 1 ? .58 : .36 - s * .06) * AL * (1 - far * .40)));
  } });
  // ⭐ **서리 알갱이** — 참고장 「㉶ 소음은 개수가 아니라 주파수」. 면 위에
  //   아주 작은 점 넷. 엔진 이식: `fxNoiseGrainy` 를 면에 곱하면 이 줄이 없어진다.
  // ⚠️ 이것도 **가산**이다 — 알갱이는 면 위의 색점이 아니라 **빛의 티끌**이라,
  //   덮어 칠하면 결정 표면에 얼룩이 앉은 것으로 보인다.
  if (!o.bare) gAdd(c, (cc) => { for (let g = 0; g < 4; g++) {
    const uu = .22 + .62 * hash(seed + g * 6.1);
    const ff = (hash(seed + g * 9.7) - .5) * 1.5;
    const [gx, gy] = at(len * uu, hw(uu) * ff);
    const gr = Math.max(.35, w * (.10 + .08 * hash(seed + g * 3.3)));
    fillPoly(cc, [[gx - gr, gy], [gx, gy - gr], [gx + gr, gy], [gx, gy + gr]],
      A("#E8F8FF", .40 * AL));
  } });
}

/// ⭐⭐ **가시 덤불** — 여덟 조항을 한 벌로 세운다.
/// ⚠️ 이 함수가 그리는 차례가 곧 깊이다(㉣) — 뒤엣것부터 그린다. 뒤집으면
///   덤불이 **평면**으로 무너진다.
/// `n` 가시 수 · `ang` 무리가 향하는 각(방향은 ㉡+㉥ 이 만든다)
function IZthicket(c, x, y, ang, len, w, SC, a, seed, n, o) {
  if (a <= .01 || n < 1) return;
  o = o || {};
  const spread = (o.spread == null ? 1.05 : o.spread);
  const gv = (o.grow == null ? 1 : IZcl(o.grow));
  if (gv <= .01) return;
  // ㉧ **발치의 어두운 덩어리** — 제일 먼저. 밝은 것만 있으면 붕 떠 보인다
  {
    const P = [];
    for (let i = 0; i <= 12; i++) {
      const a0 = i / 12 * TAU;
      P.push([x + Math.cos(a0) * len * .46 * gv,
              y + Math.sin(a0) * len * .46 * LX3SQT * .52 * gv + w * .5]);
    }
    fillPoly(c, P, A("#08131F", .46 * a));
  }
  // 가시 — **뒤(작고 옅고 위) → 앞(크고 진하고 아래)** 차례로
  const S = [];
  for (let i = 0; i < n; i++) {
    const u = (i + .5) / n;
    const sd = seed + i * 7.3;
    // ㉥ 바깥일수록 눕는다 — 축에서 멀수록 각이 벌어진다
    const off = (u - .5) * 2;
    const sa = ang + off * spread + (hash(sd + 1.7) - .5) * .30;
    // ㉢㉡ 뒤엣것은 작고 옅다. `far` 는 축에서 먼 정도가 아니라 **깊이**다
    const far = hash(sd + 3.1);
    const sl = len * (1 - far * .52) * (.62 + .58 * hash(sd + 5.3)) * gv;
    const sw = w * (1 - far * .44) * (.70 + .52 * hash(sd + 9.1));
    // 뿌리가 조금씩 어긋난다 — 한 점에서 나면 부채가 된다
    const rx = x + (hash(sd + 11.3) - .5) * len * .42;
    const ry = y + (hash(sd + 13.7) - .5) * len * .13 * LX3SQT + far * w * .8;
    S.push({ far, sa, sl, sw, rx, ry, sd });
  }
  S.sort((p, q) => q.far - p.far);          // ㉣ 먼 것부터
  for (const s of S)
    IZprism3(c, s.rx, s.ry, s.sa, s.sl, s.sw, s.sd, a, { far: s.far, tip: .09 });
  // ㉤ **밑동의 들쭉날쭉한 흰 테** — 「뚫고 나왔다」를 말하는 유일한 항
  IBrim(c, jagPoly(x, y + w * .35, len * .40 * gv, 13, seed + 21.1, 1.16, LX3SQT * .58),
    "snow", .74 * a, 1.3 * SC);
  IBroot(c, x, y + w * .35, len * .34 * gv, "frost", .40 * a, LX3SQT * .55);
  // ㉦ **공중에 뜬 조각 넷** — 「지금 막 일어났다」
  for (let j = 0; j < 4; j++) {
    const sd = seed + j * 17.9;
    const a0 = ang + (hash(sd) - .5) * spread * 2.1;
    const d = len * (.72 + .52 * hash(sd + 2.3)) * gv;
    IBshard(c, x + Math.cos(a0) * d, y + Math.sin(a0) * d,
      w * (.42 + .40 * hash(sd + 4.7)), a0 + 1.3, "frost", .72 * a, .44);
  }
}

// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐⭐ 파문 — **다시 그렸다**                                (2026-08-28 3차)
//
// 사용자 판정: 「**너무 연하고 이펙트가 화려하지 않음, 밀도도 낮고, 텍스쳐나
//   파티클 등 스킬 디자인의 밀도도 낮음**」
// ⚠️ **알파를 올려서는 답이 안 난다.** 앞 그림(`vfx.js` 의 `FX.pulse`)이 가진
//   항은 넷뿐이었다 — 얇은 테 두 줄 · 창 열 · L5 서리 고리 · 피격 불티.
//   그래서 다섯 칸이 **굵기 차이로만** 갈렸다. ⇒ **항을 늘린다.**
//
// ── 늘린 항(앞 그림에 없던 것) ───────────────────────────────────────────
//   ① **바닥 마법진** — 시전·생성 마디의 그림([IZsigil], 여섯 항 · 눕는다)
//   ② **솟는 기둥** — 꼬인 가닥 셋 + 지그재그 + 밑동 스커트 + 바닥 금([IZcolumn])
//   ③ **파면의 성에 침** — 파면을 따라 선 결정 **서른넷**([IZprism3], 면이 셋)
//   ④ **굴절 빗금** — 파면 안쪽을 가로지르는 짧은 사선 스물둘
//   ⑤ **지나간 자리의 성에 결** — 바닥에 앉는 육각 스물여섯(눕는다)
//   ⑥ **연쇄 터짐** — 파면이 지날 때 고리 위 여섯 자리에서 **터지고 터진다**
//   ⑦ **부스러기** — 파면 앞머리에서 튀는 조각([IZchip])
//   ⑧ **소멸의 파쇄** — 최대 반경에서 테가 **깨져** 조각이 눕는다
//
// ⚠️⚠️ **고리를 두껍게 하지 않았다.** 두껍게 하면 곧장 비싼 잉크(넓은 면)이고,
//   화려함은 거기서 안 나온다. 늘린 여덟 항이 **전부 가늘고 긴 것**이다.
// ⚠️ **밝기 세 층**을 지킨다 — 흰 심 / 하늘빛 몸 / 짙은 그늘. 사용자의
//   「연하다」는 알파 문제가 아니라 **층이 하나였던** 문제다.
//
// ── ⚠️ 성장표 문구는 도감이 정본이다 ─────────────────────────────────────
// `lib/data/magic.dart` 의 다섯 줄을 **한 글자도 안 고쳤다** — 이 그림이 하는
// 일은 그 다섯 줄을 **화면에서 갈리게** 만드는 것뿐이다. 반경·폭·창 수의
// 성장축도 앞 그림의 것을 그대로 옮겼다(밸런스는 이 갈래의 몫이 아니다).
// ⚠️ **얼리지 않는다.** 표식은 `IZF_ON`(1.5) 아래에서 멈추는 **서리**뿐이고,
//   그것이 도감의 「감속 지대」다 — 빙결은 빙판 · 우박의 몫이다.
// ══════════════════════════════════════════════════════════════════════════
/// 다섯 마디 — [시전, 생성, 발현, 소멸, 종료]. 합 = 주기.
/// ⚠️ **시전·생성이 0 이면 안 되고 소멸도 0 이면 안 된다.** 앞 그림은 시전이
///   0.205초(L1)뿐이었고 소멸이 아예 없었다.
/// ⚠️⚠️ **주기가 레벨마다 는다** — 겹이 늘면 발현이 길어져야 한다.
///   첫 판은 다섯 칸이 같은 주기(3.30)였고, 그래서 **L1 은 발현 1.52초 중
///   0.86초가 빈 화면**이었다(파면이 0.66초에 죽는다). 갈무리로 실측해 잡았다.
///   ⇒ 발현은 **마지막 겹이 죽는 시각**에 맞춘다. 이것이 사용자가 허가한
///     「덜 자주, 대신 한 번을 크게」의 실체다 — L5 가 L1 보다 **32% 길다**.
const IZP_BV = [
  [.42, .34, .98, .52, .40],   // L1  주기 2.66
  [.42, .34, .98, .52, .40],   // L2  주기 2.66
  [.42, .34, .98, .52, .40],   // L3  주기 2.66
  [.42, .34, 1.22, .56, .42],  // L4  주기 2.96 — 선파가 붙는다
  [.42, .34, 1.74, .58, .44],  // L5  주기 3.52 — 종파까지 셋
];
/// 파면 최대 반지름(238칸) — 앞 그림의 성장축(반경 +46% → +32% → +26% → +19%)을
/// 이 칸의 무대에 맞춰 옮긴 것. **L2 에서 넷이 다 사정권에 든다**(도감 문구).
const IZP_R = [46, 74, 88, 100, 110];
/// 링 폭 · 창 수 · 창 길이 — 앞 그림 값 그대로.
const IZP_W = [5, 7.5, 10, 13, 16];
const IZP_SPN = [6, 7, 8, 10, 10];
const IZP_SPL = [10, 12, 14, 16, 18];
/// 본파가 최대 반경까지 가는 데 걸리는 시간(s).
const IZP_FLY = .86;
/// 겹 — `[지연(s), 속도 몫, 굵기 몫]`. ⚠️ **한 겹이 커지는 것이 아니라 여러
/// 겹이 시차로 나간다**(사용자: 「터지고 터지는」). L4 선파 · L5 종파가 도감이다.
const IZP_SET = [
  [[0, 1.00, 1.00]],
  [[0, 1.00, 1.00]],
  [[0, 1.00, 1.00]],
  [[0, 1.62, .40], [.22, 1.00, 1.00]],
  [[0, 1.62, .40], [.22, 1.00, 1.00], [.56, .74, 1.34]],
];
/// 파면에 서는 성에 침 · 굴절 빗금 · 바닥 성에 결 · 고리 위 연쇄 터짐 자리.
/// ⚠️ 전부 **싼 잉크**다 — 수를 늘려도 칠하는 면적이 거의 안 는다.
const IZP_NEEDLE = 34, IZP_GRAIN = 22, IZP_SCAR = 26, IZP_POP = 6;
/// 밀리는 몫(238칸) · 마법진 반지름(238칸) · 기둥 높이(238칸).
const IZP_KB = 13, IZP_SIG = 40, IZP_COL = 58;
/// 적 넷 — 거리가 **사다리**로 흩어져 있어야 반경이 「몇 마리를 쓸었나」로
/// 읽힌다(39.7 · 64.4 · 67.1 · 69.9). 다 같은 띠에 몰면 「전부 맞거나 전혀
/// 안 맞거나」가 되어 다섯 칸이 안 갈린다.
const IZP_FOE = [[26, -30, 9], [-52, -38, 10], [60, -30, 10], [-16, 68, 9]];
/// 감속 지대의 서리 — `IZF_ON`(1.5) 아래에서 멈춘다. **파문은 안 얼린다.**
const IZP_FRZ = 1.05;

Object.assign(FX, {
IZpulse(c, t, dt, W, H, st) {
  const cx = W / 2, cy = H / 2, SC = Math.min(W, H) / 238;
  const F = IZfoes(st, SC, IZP_FOE);
  const BV = IZP_BV[LV - 1], PER = BV[0] + BV[1] + BV[2] + BV[3] + BV[4];
  const u = saw(t, PER), tau = u * PER;
  IZwrap(st, u);
  const z = IZz(tau, PER, BV[4]);
  const tp = tau * TAU / PER, th = tau * (TAU * 2 / 2.2) / PER;
  const wob = TAU * 2 * tau / PER;
  const B = IZbeat(tau, BV);
  const RM = IZP_R[LV - 1], PW = IZP_W[LV - 1], SET = IZP_SET[LV - 1];
  const SQ = LX3SQT;

  /// 겹 `j` 의 반지름(238칸). 안 났으면 −1.
  const radOf = (j) => {
    const s = tau - B.t1 - SET[j][0];
    if (s <= 0) return -1;
    const r = RM * s * SET[j][1] / IZP_FLY;
    return r > RM * 1.06 ? -1 : r;
  };
  /// 겹 `j` 가 반지름 `r` 에 닿는 시각(초).
  const timeAt = (j, r) => B.t1 + SET[j][0] + (r / RM) * IZP_FLY / SET[j][1];

  // ── 밀린다 — **시각의 함수**라 프레임을 건너뛰어도 같은 자리다 ──────────
  for (const f of F) {
    const d = Math.hypot(f.ux, f.uy) || 1;
    let kick = 0, frost = 0;
    for (let j = 0; j < SET.length; j++) {
      if (d > RM) continue;
      const s = tau - timeAt(j, d);
      if (s <= 0) continue;
      kick += Math.max(0, 1 - s / .46) * SET[j][2];
      // 감속 지대(L5) — 종파가 지난 뒤 서리가 앉는다. **얼지는 않는다**
      if (LV === 5 && j === SET.length - 1) frost = Math.min(1, s / .55);
    }
    f.ax = f.ux / d * IZP_KB * Math.min(1.6, kick);
    f.ay = f.uy / d * IZP_KB * Math.min(1.6, kick);
    // ⚠️ 꼬리 램프를 곱한다 — 안 곱하면 주기 끝의 서리 표식이 **주기 처음에
    //   툭 사라진다**(`pvMark` 은 `z` 를 안 받는다). 이음매는 그려지는 값이
    //   **전부** 0 이 돼야 없어진다.
    f.pv = frost * IZP_FRZ * z;
    f.hit = Math.min(1, kick);
  }
  IZstand(F, SC, wob, z);

  // ── 불티 — 파면 앞머리에서 튀는 부스러기(주기당 겹마다 여섯 번) ─────────
  for (let j = 0; j < SET.length; j++) {
    const r = radOf(j); if (r < 6) continue;
    const slot = Math.floor((r / RM) * 6);
    const key = "cp" + j + "_" + slot;
    if (st.ev[key]) continue;
    st.ev[key] = 1;
    for (let m = 0; m < 5; m++) {
      const a0 = (m + .5 + slot * .37) / 5 * TAU;
      IZchip(st, cx + Math.cos(a0) * r * SC, cy + Math.sin(a0) * r * SQ * SC,
        j * 13.1 + slot * 5.3 + m * 2.7, 2,
        { b: tau, a: a0, spread: .8, v: 30, vr: 26, r: 1.3, rr: 1.2, life: .38, g: 90 });
    }
  }

  // ══ 그리기 ═══════════════════════════════════════════════════════════════
  // ── ① 바닥 마법진 — 시전에 그려지고 · 생성에 차오르고 · 발현에 스러진다
  {
    const g = B.inCast ? IZss(B.cast) * .82
      : B.inGrow ? .82 + .18 * IZss(B.grow)
      : Math.max(0, 1 - IZseg(tau, B.t1, B.t1 + .52));
    if (g > .02) IZsigil(c, cx, cy, IZP_SIG * SC, tp, g, SC, g * z, 4.1);
  }
  // ── ㉠ 시전 — 밖에서 안으로 냉기가 **모인다**(다섯 칸이 같은 그림을 쓴다)
  if (B.inCast) IZcastFx(c, cx, cy, B.cast, SC, 1, 4.1, 1);
  // ── ㉡ 생성 — ② **꼬인 다발이 솟는다.** 공격이 나가기 **전**의 그림이다
  if (B.inGrow || (B.inHit && tau < B.t1 + .30))
    IZcolumn(c, cx, cy, IZcl((tau - B.t0) / (BV[1] + .30)),
      IZP_COL * SC, 14 * SC, SC, 1, 6.7);

  // ── ⑤ 지나간 자리의 **성에 결** — 바닥에 앉는다(눕는다 · 뒤엣것은 옅다)
  for (let m = 0; m < IZP_SCAR; m++) {
    const a0 = (m + .5) / IZP_SCAR * TAU + hash(m * 3.1) * .5;
    const rr = RM * (.26 + .70 * hash(m * 5.7));
    let born = 1e9;
    for (let j = 0; j < SET.length; j++) { const q = timeAt(j, rr); if (q < born) born = q; }
    const s = tau - born;
    if (s <= 0) continue;
    const al = Math.min(1, s * 6) * Math.max(0, 1 - s / (LV === 5 ? 1.55 : .95));
    if (al < .03) continue;
    const px = cx + Math.cos(a0) * rr * SC, py = cy + Math.sin(a0) * rr * SQ * SC;
    // ㉢ 뒤(위)로 갈수록 작고 옅다 — 대기 원근은 **공짜**다
    const far = (1 - Math.sin(a0)) * .5;
    IBflake(c, px, py, (3.6 - far * 1.3) * SC, a0 * .5, "frost",
      al * (.74 - far * .26) * z, .9 * SC, SQ);
  }

  // ── ③④⑥ 파면 — 겹마다 **테 두 줄 + 성에 침 + 굴절 빗금 + 창 + 연쇄 터짐**
  for (let j = 0; j < SET.length; j++) {
    const r = radOf(j); if (r < 2) continue;
    const wm = SET[j][2], fade = Math.max(0, 1 - r / (RM * 1.02));
    const bw = (PW * wm * fade + 1.5) * .5;
    const AL = fade * z;
    /// 눌린 고리 한 줄(폴리라인). ⚠️ **타원이다** — 바닥에 깔린 원은 눕는다.
    const ring = (rr, n) => {
      const P = [];
      for (let i = 0; i <= n; i++) {
        const a0 = i / n * TAU;
        P.push([cx + Math.cos(a0) * rr * SC, cy + Math.sin(a0) * rr * SQ * SC]);
      }
      return P;
    };
    // 테 두 줄 — **속을 안 채운다**(폭은 두 줄이 벌어지는 것으로 말한다)
    // 🔴 **앞뒤로 가른다**(2026-08-28 7차) — 앞 판은 고리가 통째로 몸 뒤라
    //   **퍼지는 파면이 몸을 안 지나갔다.** 위 반은 몸 뒤, 아래 반은 몸 앞이라야
    //   「몸을 두르고 퍼진다」가 된다.
    const drawRing = (rr, n, w, al, soft) => {
      const [fa, ne] = IZhalves(cx, cy, rr * SC, SQ, n);
      IBline(c, fa, w, "frost", al, soft);
      front((cc) => IBline(cc, ne, w, "frost", al, soft));
    };
    drawRing(Math.max(1.5, r - bw), 22, 1.5 * SC, .82 * AL, 0);
    drawRing(r + bw, 24, 1.9 * SC, .95 * AL, 1);
    // ④ **굴절 빗금** — 두 줄 사이를 가로지르는 짧은 사선. 유리의 결이다
    for (let i = 0; i < IZP_GRAIN; i++) {
      const a0 = (i + .5) / IZP_GRAIN * TAU + r * .012;
      const sl = .34 + .30 * hash(i * 7.1 + j);
      const p = (rr, off) => [cx + Math.cos(a0 + off) * rr * SC,
                              cy + Math.sin(a0 + off) * rr * SQ * SC];
      IBline(c, [p(r - bw * .9, -sl * .06), p(r + bw * .9, sl * .06)], .8 * SC,
        "frost", .40 * AL * (.6 + .5 * hash(i * 3.3)), 0);
    }
    // ③ **성에 침 서른넷** — 파면 위에 선 결정. 면이 셋으로 쪼개져 있다(㉠)
    for (let i = 0; i < IZP_NEEDLE; i++) {
      const a0 = (i + .5) / IZP_NEEDLE * TAU + r * .006;
      const sd = i * 4.7 + j * 31.3;
      const ha = Math.atan2(Math.sin(a0) * SQ, Math.cos(a0));
      const x0 = cx + Math.cos(a0) * (r + bw * .5) * SC;
      const y0 = cy + Math.sin(a0) * (r + bw * .5) * SQ * SC;
      // ㉢ 위(먼 쪽)로 갈수록 작고 옅다 · ㉥ 각이 제각각이다
      const far = (1 - Math.sin(a0)) * .5;
      // 🔴 침은 **점**이라 통째로 앞뒤를 가른다(고리와 같은 규율)
      IZdepth(c, y0, cy, (cc) => IZprism3(cc, x0, y0, ha + (hash(sd) - .5) * .5,
        (3.4 + 3.2 * hash(sd + 1.9)) * wm * (1 - far * .38) * SC,
        (1.05 + .75 * hash(sd + 3.7)) * wm * (1 - far * .30) * SC,
        sd, .88 * AL, { far, tip: .08, bare: 1 }));
    }
    // 창 — 도감의 「가장자리에 창이 선다」. 침보다 길고 밝다
    const NSP = IZP_SPN[LV - 1], SPL = IZP_SPL[LV - 1];
    for (let i = 0; i < NSP; i++) {
      const a0 = i / NSP * TAU + r * .010;
      const ha = Math.atan2(Math.sin(a0) * SQ, Math.cos(a0));
      const x0 = cx + Math.cos(a0) * (r + bw) * SC, y0 = cy + Math.sin(a0) * (r + bw) * SQ * SC;
      const far = (1 - Math.sin(a0)) * .5;
      IZdepth(c, y0, cy, (cc) => IZprism3(cc, x0, y0, ha, (SPL * wm * fade * .62 + 3) * SC,
        (2.4 * wm * fade + .9) * SC, i * 9.1 + j * 17.7, .95 * AL, { far, tip: .10 }));
    }
    // ⑥ **터지고 터진다** — 고리 위 여섯 자리에서 시차로 성에가 터진다
    for (let m = 0; m < IZP_POP; m++) {
      const rb = RM * (.40 + .48 * hash(m * 11.3 + j));
      const s = tau - timeAt(j, rb);
      if (s <= 0 || s > .90) continue;
      const a0 = (m + .5) / IZP_POP * TAU + j * .41;
      IZchain(c, cx + Math.cos(a0) * rb * SC, cy + Math.sin(a0) * rb * SQ * SC,
        s, (7 + 5 * wm) * SC, SC, .82 * z, m * 5.9 + j * 23.1, SQ);
    }
  }

  // ── L5 **감속 지대** — 최대 반경에 서리 고리가 남는다(도감 그대로)
  if (atL(5) && tau > B.t1 + .30) {
    const al = Math.min(1, (tau - B.t1 - .30) * 2.2) * z
      * (1 - .72 * IZseg(tau, B.t2, B.t3));
    const P = [];
    for (let i = 0; i <= 52; i++) {
      const a0 = i / 52 * TAU;
      P.push([cx + Math.cos(a0) * RM * SC, cy + Math.sin(a0) * RM * SQ * SC]);
    }
    IBline(c, P, 1.3 * SC, "snow", .44 * al, 0);
    for (let m = 0; m < 18; m++) {
      const a0 = (m + .5) / 18 * TAU;
      IBflake(c, cx + Math.cos(a0) * RM * .96 * SC, cy + Math.sin(a0) * RM * .96 * SQ * SC,
        3.0 * SC, a0, "snow", .40 * al, .8 * SC, SQ);
    }
    // ⭐ **가장자리에서 안쪽으로** 서리가 뻗는다(빙-5) — 감속 지대를 파랗게
    //   채우면 그 순간 「얼음 웅덩이」가 되고 장판(빙판)과 화면에서 겹친다
    IZfern(c, cx, cy, RM * SC, 5, Math.min(1, (tau - B.t1 - .30) * 1.4), SC,
      .62 * al, 7.1, SQ);
  }

  // ── ㉣ 소멸 — ⑧ 테가 **깨진다.** 그냥 옅어지지 않는다
  if (tau >= B.t2) {
    if (!st.ev.brk) { st.ev.brk = 1;
      for (let m = 0; m < 20; m++) {
        const a0 = (m + .5) / 20 * TAU;
        IZchip(st, cx + Math.cos(a0) * RM * SC, cy + Math.sin(a0) * RM * SQ * SC,
          m * 6.3, 1, { b: tau, a: a0, spread: .6, v: 20, vr: 16, r: 1.9, rr: 1.5,
            life: .46, g: 40 });
      }
    }
    const v = IZseg(tau, B.t2, B.t3);
    for (let m = 0; m < 14; m++) {
      const a0 = (m + .5) / 14 * TAU + .21;
      const rr = RM * (1 - v * .10);
      const far = (1 - Math.sin(a0)) * .5;
      IZprism3(c, cx + Math.cos(a0) * rr * SC, cy + Math.sin(a0) * rr * SQ * SC,
        a0 + 1.4 + v * .8, (4.2 - v * 1.6) * SC, (1.5 - v * .5) * SC, m * 8.7,
        (1 - v) * .80 * z, { far, tip: .10, bare: 1 });
    }
  }
  // ── ㉤ 종료 — 남은 자국이 김으로 흩어진다(**소멸과 다른 그림** · 조각이 없다)
  if (B.inRest) IZrestFx(c, cx, cy, B.rest, RM * .62 * SC, SC, 1, 8.3);

  IZchips(c, st, tau, SC, z);
  IZmarks(c, tp, cx, cy, F, SC, z);
  hero(c, th, cx, cy);
},
});

// ── 검산 창구에 **뒤에 선 것**을 더한다 ───────────────────────────────────
// ⚠️⚠️ `window.IZDBG` 는 이 파일 가운데에서 만들어지는데 파문 상수와 도구 넷의
//   상수는 **그 뒤**에 선다. 객체 리터럴 안에서 읽으면 TDZ 에 걸려
//   「Cannot access 'IZP_BV' before initialization」으로 **파일이 통째로 죽는다**
//   (2026-08-28 스모크가 잡았다). 함수는 끌어올려지지만 `const` 는 아니다.
Object.assign(window.IZDBG.K, {
  IZP_BV, IZP_R, IZP_W, IZP_SPN, IZP_SPL, IZP_FLY, IZP_SET,
  IZP_NEEDLE, IZP_GRAIN, IZP_SCAR, IZP_POP, IZP_KB, IZP_SIG, IZP_COL, IZP_FRZ,
  IZG_RING, IZG_RW, IZG_DASH, IZG_TICK, IZG_SAT, IZG_STAR,
  IZ3_CUT, IZ3_MIX, IZX_LAG, IZX_SPAN,
});

// ══════════════════════════════════════════════════════════════════════════
// ⭐⭐⭐ **빙 「일반」 후보 셋** — 빈 칸을 채울 기본공격      (2026-08-28 5차)
//
// ── 왜 이 셋을 그리나 ─────────────────────────────────────────────────────
// 두 구멍이 **같은 자리**에서 만났다:
//   ① 시안 쪽 — 폐기로 빈 칸 하나가 생겼고, 그 칸의 자를 「**일반 계열 ·
//      전제 없이 서는 한 종**」으로 잡았다(빙의 일반이 둘로 내려갔고 그 둘이
//      **다 연계**라, 일반만 들고 나가면 짝이 설 때까지 아무것도 못 한다).
