//      이미 **상점 구매 배역**이라 **즉시 지급** 배역을 겸할 수 없다(한 종이 두
//      배역을 맡으면 그 구분이 빙에서 죽는다). ⇒ **빙만 상점에서 살 수 있는
//      기본공격이 0개**다. 다른 다섯 속성은 다 있다(무=유도탄 · 염=화염방사 ·
