// 🔴🔴 **채찍을 살린다 — 사용자가 조건부 폐기를 냈다**      (2026-08-28 10차)
//
// > 「얼음채찍은 아이디어는 좋은데 **채찍 느낌이 전혀 없어서 폐기.** 만약
// >  **채찍 느낌 살릴 수 있으면 해도 됨.** **소리보다 빠른 게 채찍인데 너무
// >  느림.** 그리고 **휘리릭 휘면서 쨕~! 쨕~! 하는 느낌**이 살아야 되는데」
//
// ── ⚠️ 앞 판이 왜 막대였나 — 코드에 원인이 그대로 있었다 ──────────────────
//   ㉠ `swing = IZss(B.hit)` — **매끈 계단**이라 시작도 끝도 느리고 가운데가
//      제일 빠르다. 이건 **문이 열리는 곡선**이지 채찍이 아니다.
//   ㉡ `lag = ang − LAG·w0²·(1−hit)` — 뒤처짐이 **한 번에 고르게 풀린다.**
//      채찍은 말림이 **손잡이에서 끝으로 이동**하는 물건인데, 이 식은 축 전체가
//      같은 시각에 같이 편다 ⇒ **통째로 휘는 막대**다.
//   ㉢ 굵기가 `3.4 + 4.6·w0` — **끝이 제일 굵었다.** 채찍은 반대다.
//   ㉣ 한 주기에 **한 번만** 친다. 「쨕~! 쨕~!」이 아니다.
//   ㉤ **터지는 순간이 없다.** 「쨕」은 끝이 음속을 넘을 때 나는 소리인데
//      그 한 점에 아무 획도 없었다.
//
// ── ⭐⭐ 채찍이 채찍이 되는 다섯 ──────────────────────────────────────────
