//      뿌리에서 끝으로 달린다([IZW_WAVE]). 이것 하나가 막대와 채찍을 가른다.
//   ② **끝이 폭발적으로 빠르다** — 경계가 지나는 폭이 **끝으로 갈수록 좁다**
//      ([IZW_SNAP0]→[IZW_SNAP1]). 각속도가 끝에서 **2.8배**가 되고, 반지름이
//      74칸이라 **선속도는 아홉 배**다. 「소리보다 빠른」이 이 수다.
//   ③ **끝이 제일 가늘다** — 굵기를 뒤집었다(뿌리 5.0 → 끝 0.9, **5.6배**).
//   ④ **쨕이 두 번** — 발현을 **두 타**로 가른다(0.30 + 0.06 + 0.30 = 0.66).
//   ⑤ **끝에서 터진다** — 경계가 끝을 지나는 그 한 프레임에 흰 섬광 + **원뿔
//      파문** + 얼음 조각. **그 한 점이 이 스킬의 전부**다.
// ══════════════════════════════════════════════════════════════════════════
